"use client";

/* eslint-disable @typescript-eslint/no-explicit-any */

import { useEffect, useMemo, useRef, useState } from "react";
import { useRouter } from "next/navigation";
import { createClientComponentClient } from "@/lib/platformClient";
import AskThisRunPanel from "@/components/AskThisRunPanel";
import {
  DIGITAL_HEM_DEFAULT_STAGE_TOGGLES,
  HemAutomaticRunControls,
  HemChildDashboardLinks,
  digitalHemNextStageLabel,
  digitalHemStageOptions,
} from "@/components/HemAutomaticRun";
import NextWorkflowLauncher from "@/components/NextWorkflowLauncher";
import WorkflowEvidenceDashboard from "@/components/WorkflowEvidenceDashboard";

const supabase = createClientComponentClient();
const API_BASE = process.env.NEXT_PUBLIC_API_URL || "/api";

type WorkflowRow = {
  id: string;
  status?: string | null;
  phase?: string | null;
  logs?: string | null;
  updated_at?: string | null;
};

function parseLogLines(logs: string | null | undefined): string[] {
  if (!logs) return [];
  return logs
    .split("\n")
    .map((l) => l.trimEnd())
    .filter((l) => l.trim().length > 0);
}

export default function DQAAppPage() {
  const router = useRouter();

  const [sessionUserId, setSessionUserId] = useState<string | null>(null);
  const [accessToken, setAccessToken] = useState<string | null>(null);

  const [loading, setLoading] = useState(true);
  const [running, setRunning] = useState(false);
  const [err, setErr] = useState<string | null>(null);

  const [workflowId, setWorkflowId] = useState<string | null>(null);
  const [runId, setRunId] = useState<string | null>(null);
  const [workflowRow, setWorkflowRow] = useState<WorkflowRow | null>(null);

  // Intake (minimal but useful)
  const [rtlSourceMode, setRtlSourceMode] = useState<"from_arch2rtl" | "paste" | "repo_path">("repo_path");
  const [fromWorkflowId, setFromWorkflowId] = useState("");
  const [repoPath, setRepoPath] = useState("");
  const [pastedRtl, setPastedRtl] = useState(""); // simple text area for now
  const [parentWorkflowId, setParentWorkflowId] = useState("");
  const [upstreamWorkflows, setUpstreamWorkflows] = useState<Record<string, string> | null>(null);

  const [lintProfile, setLintProfile] = useState<"strict" | "medium">("medium");
  const [cdcProfile, setCdcProfile] = useState<"default" | "aggressive">("default");
  const [target, setTarget] = useState<"asic" | "fpga">("asic");
  const [enableAutofix, setEnableAutofix] = useState(false);
  const [hemEnabled, setHemEnabled] = useState(false);
  const [hemAdaptive, setHemAdaptive] = useState(false);
  const [hemStageToggles, setHemStageToggles] = useState({ ...DIGITAL_HEM_DEFAULT_STAGE_TOGGLES });

  const logLines = useMemo(() => parseLogLines(workflowRow?.logs), [workflowRow?.logs]);
  const logsRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    if (!logsRef.current) return;
    logsRef.current.scrollTop = logsRef.current.scrollHeight;
  }, [logLines.length]);

  function authHeaders(): HeadersInit {
    const h: Record<string, string> = {};
    if (sessionUserId) h["x-user-id"] = sessionUserId;
    if (accessToken) h["Authorization"] = `Bearer ${accessToken}`;
    return h;
  }

  async function postJSON<T>(path: string, body: any): Promise<T> {
    const resp = await fetch(`${API_BASE}${path}`, {
      method: "POST",
      headers: { "Content-Type": "application/json", ...authHeaders() },
      body: JSON.stringify(body),
    });
    if (!resp.ok) {
      const txt = await resp.text().catch(() => "");
      throw new Error(`${resp.status} ${resp.statusText}${txt ? ` — ${txt}` : ""}`);
    }
    return resp.json();
  }

  // Auth gate
  useEffect(() => {
    (async () => {
      setLoading(true);
      setErr(null);

      const { data: { session } } = await supabase.auth.getSession();
      if (!session?.user) {
        router.replace("/login?next=/apps/dqa");
        return;
      }
      setSessionUserId(session.user.id);
      setAccessToken(session.access_token);
      setLoading(false);
    })();
  }, [router]);

  useEffect(() => {
    if (loading || typeof window === "undefined") return;
    const params = new URLSearchParams(window.location.search);
    if (params.get("handoff") !== "1") return;
    const sourceId = params.get("from_workflow_id") || params.get("source_arch2rtl_workflow_id") || "";
    if (sourceId) {
      setRtlSourceMode("from_arch2rtl");
      setFromWorkflowId(sourceId);
    }
    setParentWorkflowId(params.get("parent_workflow_id") || "");
    const rawUpstream = params.get("upstream_workflows");
    if (rawUpstream) {
      try {
        const parsed = JSON.parse(rawUpstream) as Record<string, string>;
        setUpstreamWorkflows(parsed && typeof parsed === "object" ? parsed : null);
      } catch {
        setUpstreamWorkflows(null);
      }
    }
  }, [loading]);

  // Live workflow updates
  useEffect(() => {
    if (!workflowId) return;

    let isActive = true;

    (async () => {
      const { data, error } = await supabase
        .from("workflows")
        .select("id,status,phase,logs,updated_at")
        .eq("id", workflowId)
        .single();

      if (isActive && !error && data) setWorkflowRow(data as any);
    })();

    const channel = supabase
      .channel(`wf-${workflowId}`)
      .on(
        "postgres_changes",
        { event: "*", schema: "public", table: "workflows", filter: `id=eq.${workflowId}` },
        (payload) => {
          const row = payload.new as any;
          setWorkflowRow({
            id: row.id,
            status: row.status,
            phase: row.phase,
            logs: row.logs,
            updated_at: row.updated_at,
          });
        }
      )
      .subscribe();

    return () => {
      isActive = false;
      supabase.removeChannel(channel);
    };
  }, [workflowId]);

  const canRun = useMemo(() => {
    if (running) return false;
    if (rtlSourceMode === "repo_path" && !repoPath.trim()) return false;
    if (rtlSourceMode === "from_arch2rtl" && !fromWorkflowId.trim()) return false;
    if (rtlSourceMode === "paste" && !pastedRtl.trim()) return false;
    return true;
  }, [running, rtlSourceMode, repoPath, fromWorkflowId, pastedRtl]);

  const hemRequiresSource = rtlSourceMode !== "from_arch2rtl" || !fromWorkflowId.trim();

  async function runNow() {
    setErr(null);
    setRunning(true);
    try {
      const out = await postJSON<{ ok: boolean; workflow_id: string; run_id: string }>(
        "/apps/dqa/run",
        {
          rtl_source_mode: rtlSourceMode,
          from_workflow_id: rtlSourceMode === "from_arch2rtl" ? fromWorkflowId : undefined,
          source_arch2rtl_workflow_id: rtlSourceMode === "from_arch2rtl" ? fromWorkflowId : undefined,
          parent_workflow_id: parentWorkflowId || undefined,
          upstream_workflows: rtlSourceMode === "from_arch2rtl" ? { ...(upstreamWorkflows || {}), arch2rtl: fromWorkflowId } : undefined,
          repo_path: rtlSourceMode === "repo_path" ? repoPath : undefined,
          // Keep simple for now (backend supports richer array; this is minimal)
          pasted_rtl_files:
            rtlSourceMode === "paste"
              ? [{ path: "rtl/top.sv", content: pastedRtl }]
              : undefined,

          lint_profile: lintProfile,
          cdc_profile: cdcProfile,
          target,
          hem_enabled: hemEnabled && !hemRequiresSource,
          hem_mode: hemAdaptive ? "adaptive" : "fixed",
          hem_stage_toggles: hemStageToggles,

          toggles: { enable_autofix: enableAutofix },
        }
      );

      setWorkflowId(out.workflow_id);
      setRunId(out.run_id);
    } catch (e: any) {
      setErr(e?.message || String(e));
    } finally {
      setRunning(false);
    }
  }

  function downloadZip() {
    if (!workflowId) return;
    window.open(`${API_BASE}/workflow/${workflowId}/download_zip?full=1`, "_blank");
  }

  if (loading) {
    return (
      <main className="min-h-screen bg-black text-white flex items-center justify-center">
        <div className="text-slate-300">Loading…</div>
      </main>
    );
  }

  return (
    <main className="min-h-screen bg-gradient-to-br from-slate-950 via-black to-slate-950 text-white">
      <div className="mx-auto max-w-[1440px] px-6 py-10">
        <div className="flex items-center justify-between">
          <button
            onClick={() => router.push("/apps")}
            className="rounded-xl bg-slate-800 px-4 py-2 hover:bg-slate-700 transition"
          >
            Back to Apps
          </button>
          <button
            onClick={() => router.push("/workflow")}
            className="rounded-xl border border-slate-700 px-4 py-2 hover:bg-slate-900 transition"
          >
            Studio
          </button>
        </div>

        <div className="mt-6 rounded-2xl border border-slate-800 bg-slate-900/30 p-6">
          <div className="text-sm text-slate-400">Digital Loop</div>
          <h1 className="mt-2 text-3xl font-extrabold text-white">DQA</h1>
          <p className="mt-2 text-slate-300">
            RTL Quality Gate: Lint + CDC + Reset integrity + Synthesis readiness (optional auto-fix).
          </p>

          <div className="mt-6 grid gap-4 md:grid-cols-2">
            <div className="space-y-3">
              <label className="block text-sm text-slate-300">RTL source</label>
              <select
                value={rtlSourceMode}
                onChange={(e) => setRtlSourceMode(e.target.value as any)}
                className="w-full rounded-xl border border-slate-800 bg-black/30 px-4 py-2 text-slate-100"
              >
                <option value="repo_path">Repo / path</option>
                <option value="from_arch2rtl">Use Arch2RTL output</option>
                <option value="paste">Paste RTL</option>
              </select>

              {rtlSourceMode === "repo_path" ? (
                <>
                  <label className="block text-sm text-slate-300">Repo path *</label>
                  <input
                    value={repoPath}
                    onChange={(e) => setRepoPath(e.target.value)}
                    className="w-full rounded-xl border border-slate-800 bg-black/30 px-4 py-2 text-slate-100"
                    placeholder="/path/to/repo or git URL"
                  />
                </>
              ) : null}

              {rtlSourceMode === "from_arch2rtl" ? (
                <>
                  <label className="block text-sm text-slate-300">From workflow_id *</label>
                  <input
                    value={fromWorkflowId}
                    onChange={(e) => setFromWorkflowId(e.target.value)}
                    className="w-full rounded-xl border border-slate-800 bg-black/30 px-4 py-2 text-slate-100"
                    placeholder="workflow_id from Arch2RTL"
                  />
                </>
              ) : null}

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-sm text-slate-300">Lint profile</label>
                  <select
                    value={lintProfile}
                    onChange={(e) => setLintProfile(e.target.value as any)}
                    className="w-full rounded-xl border border-slate-800 bg-black/30 px-4 py-2 text-slate-100"
                  >
                    <option value="medium">Medium</option>
                    <option value="strict">Strict</option>
                  </select>
                </div>

                <div>
                  <label className="block text-sm text-slate-300">CDC profile</label>
                  <select
                    value={cdcProfile}
                    onChange={(e) => setCdcProfile(e.target.value as any)}
                    className="w-full rounded-xl border border-slate-800 bg-black/30 px-4 py-2 text-slate-100"
                  >
                    <option value="default">Default</option>
                    <option value="aggressive">Aggressive</option>
                  </select>
                </div>
              </div>

              <label className="block text-sm text-slate-300">Target</label>
              <select
                value={target}
                onChange={(e) => setTarget(e.target.value as any)}
                className="w-full rounded-xl border border-slate-800 bg-black/30 px-4 py-2 text-slate-100"
              >
                <option value="asic">ASIC</option>
                <option value="fpga">FPGA</option>
              </select>

              <label className="flex items-center gap-2 text-sm text-slate-300">
                <input
                  type="checkbox"
                  checked={enableAutofix}
                  onChange={(e) => setEnableAutofix(e.target.checked)}
                />
                Enable auto-fix (generate patch)
              </label>

              <HemAutomaticRunControls
                enabled={hemEnabled}
                adaptive={hemAdaptive}
                onEnabledChange={(value) => {
                  setHemEnabled(value);
                  if (!value) setHemAdaptive(false);
                }}
                onAdaptiveChange={setHemAdaptive}
                currentStageLabel="DQA"
                nextStageLabel={digitalHemNextStageLabel("dqa", hemStageToggles)}
                stageOptions={digitalHemStageOptions("dqa", hemStageToggles)}
                onStageToggle={(key, value) => setHemStageToggles((current) => ({ ...current, [key]: value }))}
                disabled={hemRequiresSource}
                disabledReason="Select 'Use Arch2RTL output' and enter the source workflow_id before enabling HEM from DQA."
              />

              <button
                onClick={runNow}
                disabled={!canRun}
                className={`mt-2 w-full rounded-xl px-5 py-3 font-semibold transition ${
                  canRun ? "bg-cyan-600 hover:bg-cyan-500" : "bg-slate-700 cursor-not-allowed"
                }`}
              >
                {running ? "Starting…" : "Run DQA"}
              </button>

              {err ? <div className="mt-3 text-sm text-red-300">{err}</div> : null}

            </div>

            <div>
              <label className="block text-sm text-slate-300">Paste RTL (only if RTL source = paste)</label>
              <textarea
                value={pastedRtl}
                onChange={(e) => setPastedRtl(e.target.value)}
                rows={18}
                className="mt-2 w-full rounded-2xl border border-slate-800 bg-black/30 p-4 text-slate-100"
                placeholder="Paste your RTL here… (minimal mode stores it as rtl/top.sv)"
                disabled={rtlSourceMode !== "paste"}
              />
              <div className="mt-2 text-xs text-slate-500">
                Minimal mode: saved as one file. We can enhance later to multi-file paste.
              </div>
            </div>
          </div>

          {workflowId ? (
            <div className="mt-6 space-y-4">
              <div className="rounded-xl border border-slate-800 bg-black/30 p-4 text-sm text-slate-300">
                <div>
                  workflow_id: <span className="break-all text-slate-100">{workflowId}</span>
                </div>
                <div>
                  run_id: <span className="break-all text-slate-100">{runId}</span>
                </div>
                <button
                  onClick={downloadZip}
                  className="mt-3 rounded-xl bg-slate-800 px-4 py-2 hover:bg-slate-700"
                >
                  Download ZIP (full=1)
                </button>
                <div className="mt-3">
                  <NextWorkflowLauncher
                    currentStage="dqa"
                    currentWorkflowId={workflowId}
                    currentRunId={runId}
                    sourceArch2RTLWorkflowId={rtlSourceMode === "from_arch2rtl" ? fromWorkflowId : null}
                    upstreamWorkflows={rtlSourceMode === "from_arch2rtl" ? { arch2rtl: fromWorkflowId, dqa: workflowId } : undefined}
                    disabled={workflowRow?.status !== "completed"}
                  />
                </div>
                <HemChildDashboardLinks logs={workflowRow?.logs} rootWorkflowId={workflowId} />
              </div>
              <WorkflowEvidenceDashboard workflowId={workflowId} status={workflowRow?.status} stage="dqa" logs={workflowRow?.logs} />
              <AskThisRunPanel workflowId={workflowId} compact />
            </div>
          ) : null}

          <div className="mt-6 rounded-2xl border border-slate-800 bg-black/20 p-4">
            <div className="text-sm font-semibold">Live logs</div>
            <div
              ref={logsRef}
              className="mt-3 max-h-[320px] overflow-auto rounded-xl border border-slate-800 bg-black/30 p-3 text-xs text-slate-200"
            >
              {logLines.length ? (
                logLines.map((l, i) => (
                  <div key={i} className="whitespace-pre-wrap">
                    {l}
                  </div>
                ))
              ) : (
                <div className="text-slate-500">No logs yet. Click “Run DQA”.</div>
              )}
            </div>
          </div>
        </div>
      </div>
    </main>
  );
}

