"use client";

/* eslint-disable @typescript-eslint/no-explicit-any */

import { useEffect, useMemo, useRef, useState } from "react";
import { useRouter } from "next/navigation";
import { createClientComponentClient } from "@/lib/platformClient";
import SpecTextBox from "@/components/SpecTextBox";
import TextFileUpload from "@/components/TextFileUpload";
import {
  HemAutomaticRunControls,
  HemChildDashboardLinks,
  SYSTEM_HEM_DEFAULT_STAGE_TOGGLES,
  SYSTEM_HEM_GOAL_OPTIONS,
  type SystemHemGoal,
  systemHemStageOptions,
} from "@/components/HemAutomaticRun";
import AskThisRunPanel from "@/components/AskThisRunPanel";
import WorkflowEvidenceDashboard from "@/components/WorkflowEvidenceDashboard";
import { DESIGN_CHAIN_CONTEXT_KEY, type DesignChainContext } from "@/lib/pwmFullStackDemo";

const supabase = createClientComponentClient();
const API_BASE = process.env.NEXT_PUBLIC_API_URL || "/api";

type WorkflowRow = {
  id: string;
  status?: string | null;
  phase?: string | null;
  logs?: string | null;
  updated_at?: string | null;
};

type ClockRow = {
  name: string;
  port: string;
  frequency_mhz: string;
  period_ns?: number | null;
  source?: string;
  needs_user_frequency?: boolean;
};

function parseLogLines(logs: string | null | undefined): string[] {
  if (!logs) return [];
  return logs.split("\n").map((l) => l.trimEnd()).filter((l) => l.trim().length > 0);
}

export default function SystemPDAppPage() {
  const router = useRouter();

  const [sessionUserId, setSessionUserId] = useState<string | null>(null);
  const [accessToken, setAccessToken] = useState<string | null>(null);

  const [loading, setLoading] = useState(true);
  const [running, setRunning] = useState(false);
  const [err, setErr] = useState<string | null>(null);

  const [workflowId, setWorkflowId] = useState<string | null>(null);
  const [runId, setRunId] = useState<string | null>(null);
  const [workflowRow, setWorkflowRow] = useState<WorkflowRow | null>(null);
  const [systemRtlWorkflowId, setSystemRtlWorkflowId] = useState("");

  // Intake
  const [projectName, setProjectName] = useState("");

  const [digitalSpecText, setDigitalSpecText] = useState("");
  const [analogSpecText, setAnalogSpecText] = useState("");
  const [socIntegrationSpecText, setSocIntegrationSpecText] = useState("");
  const [foundry, setFoundry] = useState("sky130");
  const [pdk, setPdk] = useState("sky130A");
  const [toolchain, setToolchain] = useState("openlane2");
  const [targetFreqMhz, setTargetFreqMhz] = useState("");
  const [constraintsSdc, setConstraintsSdc] = useState("");
  const [clockRows, setClockRows] = useState<ClockRow[]>([]);
  const [resetRows, setResetRows] = useState<any[]>([]);
  const [clockProbeStatus, setClockProbeStatus] = useState("");
  const [effort, setEffort] = useState<"fast" | "balanced" | "signoff">("balanced");
  const [runFill, setRunFill] = useState(true);
  const [runDrc, setRunDrc] = useState(true);
  const [runLvs, setRunLvs] = useState(true);
  const [runSignoffClosureLoop, setRunSignoffClosureLoop] = useState(false);
  const [maxSignoffClosureIterations, setMaxSignoffClosureIterations] = useState("1");
  const [allowTimingRepair, setAllowTimingRepair] = useState(true);
  const [allowDrcRepair, setAllowDrcRepair] = useState(true);
  const [allowLvsRepair, setAllowLvsRepair] = useState(true);
  const [allowLecRepair, setAllowLecRepair] = useState(true);
  const [runSynthesisClosureLoop, setRunSynthesisClosureLoop] = useState(false);
  const [maxSynthesisClosureIterations, setMaxSynthesisClosureIterations] = useState("1");
  const [allowSynthesisTimingRepair, setAllowSynthesisTimingRepair] = useState(true);
  const [allowSynthesisLecRepair, setAllowSynthesisLecRepair] = useState(true);
  const [allowSynthesisRetiming, setAllowSynthesisRetiming] = useState(false);
  const [allowSynthesisHierarchyFlattening, setAllowSynthesisHierarchyFlattening] = useState(false);
  const [stopOnSynthesisClosureFailure, setStopOnSynthesisClosureFailure] = useState(false);
  const [stopOnSynthesisLecFailure, setStopOnSynthesisLecFailure] = useState(false);
  const [runSpec2RtlCheck, setRunSpec2RtlCheck] = useState(false);
  const [enableScanDft, setEnableScanDft] = useState(false);
  const [analogPhysicalMode, setAnalogPhysicalMode] = useState<"blackbox" | "generate_sky130_gds" | "provided_gds">("blackbox");
  const [analogPdk, setAnalogPdk] = useState("sky130A");
  const [hasProvidedSpice, setHasProvidedSpice] = useState(false);
  const [analogSpiceText, setAnalogSpiceText] = useState("");
  const [spiceUploadMode, setSpiceUploadMode] = useState<"append" | "replace">("replace");
  const [nextFlow, setNextFlow] = useState<"system-firmware">("system-firmware");
  const [hemEnabled, setHemEnabled] = useState(false);
  const [hemAdaptive, setHemAdaptive] = useState(false);
  const [hemGoal, setHemGoal] = useState<SystemHemGoal>("implementation");
  const [hemStageToggles, setHemStageToggles] = useState({ ...SYSTEM_HEM_DEFAULT_STAGE_TOGGLES });

  const logLines = useMemo(() => parseLogLines(workflowRow?.logs), [workflowRow?.logs]);
  const logsRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    if (!logsRef.current) return;
    logsRef.current.scrollTop = logsRef.current.scrollHeight;
  }, [logLines.length]);

  function authHeaders(): HeadersInit {
    const h: Record<string, string> = {};
    if (sessionUserId) h["x-user-id"] = sessionUserId;
    if (accessToken) h["Authorization"] = `Bearer ${accessToken}`;
    return h;
  }

  async function postJSON<T>(path: string, body: any): Promise<T> {
    const resp = await fetch(`${API_BASE}${path}`, {
      method: "POST",
      headers: { "Content-Type": "application/json", ...authHeaders() },
      body: JSON.stringify(body),
    });
    if (!resp.ok) {
      const txt = await resp.text().catch(() => "");
      throw new Error(`${resp.status} ${resp.statusText}${txt ? ` — ${txt}` : ""}`);
    }
    return resp.json();
  }

  async function getJSON<T>(path: string): Promise<T> {
    const resp = await fetch(`${API_BASE}${path}`, {
      headers: { ...authHeaders() },
    });
    if (!resp.ok) {
      const txt = await resp.text().catch(() => "");
      throw new Error(`${resp.status} ${resp.statusText}${txt ? ` - ${txt}` : ""}`);
    }
    return resp.json();
  }

  // Auth gate
  useEffect(() => {
    (async () => {
      setLoading(true);
      setErr(null);
      const { data: { session } } = await supabase.auth.getSession();
      if (!session?.user) {
        router.replace("/login?next=/apps/system-pd");
        return;
      }
      setSessionUserId(session.user.id);
      setAccessToken(session.access_token);
      setLoading(false);
    })();
  }, [router]);

  useEffect(() => {
    if (loading || typeof window === "undefined") return;
    try {
      const context = JSON.parse(window.localStorage.getItem(DESIGN_CHAIN_CONTEXT_KEY) || "{}") as DesignChainContext;
      if (context.systemRtlWorkflowId) setSystemRtlWorkflowId(context.systemRtlWorkflowId);
    } catch {
      // ignore malformed handoff context
    }
  }, [loading]);

  useEffect(() => {
    if (loading || !systemRtlWorkflowId.trim()) {
      setClockRows([]);
      setResetRows([]);
      setClockProbeStatus("");
      return;
    }
    let cancelled = false;
    setClockProbeStatus("Detecting clocks from System RTL handoff...");
    (async () => {
      try {
        const data = await getJSON<{ clock_intent?: any }>(`/apps/digital/clock-candidates/${systemRtlWorkflowId.trim()}`);
        if (cancelled) return;
        const clocks = Array.isArray(data.clock_intent?.clocks) ? data.clock_intent.clocks : [];
        const resets = Array.isArray(data.clock_intent?.resets) ? data.clock_intent.resets : [];
        setClockRows(clocks.map((clock: any) => ({
          name: String(clock.name || clock.port || "clk"),
          port: String(clock.port || clock.name || "clk"),
          frequency_mhz: clock.frequency_mhz ? String(Number(clock.frequency_mhz).toFixed(3).replace(/\.?0+$/, "")) : "",
          period_ns: clock.period_ns ?? null,
          source: clock.source || "inferred",
          needs_user_frequency: Boolean(clock.needs_user_frequency),
        })));
        setResetRows(resets);
        setClockProbeStatus(clocks.length ? "Review detected clocks before physical design." : "No clock ports detected; enter target frequency or SDC manually.");
      } catch (error: any) {
        if (!cancelled) setClockProbeStatus(error?.message || "Clock detection failed.");
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [loading, systemRtlWorkflowId]);

  // Live workflow updates
  useEffect(() => {
    if (!workflowId) return;

    let isActive = true;

    (async () => {
      const { data, error } = await supabase
        .from("workflows")
        .select("id,status,phase,logs,updated_at")
        .eq("id", workflowId)
        .single();

      if (isActive && !error && data) setWorkflowRow(data as any);
    })();

    const channel = supabase
      .channel(`wf-${workflowId}`)
      .on(
        "postgres_changes",
        { event: "*", schema: "public", table: "workflows", filter: `id=eq.${workflowId}` },
        (payload) => {
          const row = payload.new as any;
          setWorkflowRow({
            id: row.id,
            status: row.status,
            phase: row.phase,
            logs: row.logs,
            updated_at: row.updated_at,
          });
        }
      )
      .subscribe();

    return () => {
      isActive = false;
      supabase.removeChannel(channel);
    };
  }, [workflowId]);

  const canRun = useMemo(() => {
    if (running) return false;
    if (systemRtlWorkflowId.trim()) return true;
    if (!digitalSpecText.trim()) return false;
    if (!analogSpecText.trim()) return false;
    if (!socIntegrationSpecText.trim()) return false;
    return true;
  }, [running, systemRtlWorkflowId, digitalSpecText, analogSpecText, socIntegrationSpecText]);

  function updateClockFrequency(index: number, value: string) {
    setClockRows((rows) => rows.map((row, idx) => (idx === index ? { ...row, frequency_mhz: value } : row)));
  }

  function clockConstraintsPayload() {
    if (!clockRows.length) return undefined;
    return {
      source: "ui_clock_table",
      clocks: clockRows.map((row) => {
        const mhz = Number(row.frequency_mhz);
        return {
          name: row.name || row.port,
          port: row.port || row.name,
          frequency_mhz: Number.isFinite(mhz) && mhz > 0 ? mhz : undefined,
          source: row.source || "ui_clock_table",
        };
      }),
      resets: resetRows,
    };
  }

  async function runNow() {
    setErr(null);
    setRunning(true);
    try {
      const freq = Number(targetFreqMhz);
      const out = await postJSON<{ ok: boolean; workflow_id: string; run_id: string }>(
        "/apps/system/pd/run",
        {
          project_name: projectName || undefined,
          rtl_source_mode: systemRtlWorkflowId.trim() ? "from_system_rtl" : undefined,
          system_rtl_workflow_id: systemRtlWorkflowId.trim() || undefined,
          from_workflow_id: systemRtlWorkflowId.trim() || undefined,
          digital_spec_text: digitalSpecText,
          analog_spec_text: analogSpecText,
          soc_integration_spec_text: socIntegrationSpecText,
          foundry,
          pdk,
          toolchain,
          target_frequency_mhz: Number.isFinite(freq) && freq > 0 ? freq : undefined,
          constraints_sdc: constraintsSdc || undefined,
          clock_constraints: clockConstraintsPayload(),
          effort,
          run_fill: runFill,
          run_drc: runDrc,
          run_lvs: runLvs,
          run_signoff_closure_loop: runSignoffClosureLoop,
          max_signoff_closure_iterations: runSignoffClosureLoop ? Number(maxSignoffClosureIterations) : 1,
          allow_timing_repair: allowTimingRepair,
          allow_drc_repair: allowDrcRepair,
          allow_lvs_repair: allowLvsRepair,
          allow_lec_repair: allowLecRepair,
          run_synthesis_closure_loop: runSynthesisClosureLoop,
          max_synthesis_closure_iterations: runSynthesisClosureLoop ? Number(maxSynthesisClosureIterations) : 1,
          allow_synthesis_timing_repair: allowSynthesisTimingRepair,
          allow_synthesis_lec_repair: allowSynthesisLecRepair,
          allow_synthesis_retiming: allowSynthesisRetiming,
          allow_synthesis_hierarchy_flattening: allowSynthesisHierarchyFlattening,
          stop_on_synthesis_closure_failure: stopOnSynthesisClosureFailure,
          stop_on_synthesis_lec_failure: stopOnSynthesisLecFailure,
          signoff_closure: {
            enabled: runSignoffClosureLoop,
            max_iterations: runSignoffClosureLoop ? Number(maxSignoffClosureIterations) : 1,
            allow_timing_repair: allowTimingRepair,
            allow_drc_repair: allowDrcRepair,
            allow_lvs_repair: allowLvsRepair,
            allow_lec_repair: allowLecRepair,
          },
          synthesis_closure: {
            enabled: runSynthesisClosureLoop,
            max_iterations: runSynthesisClosureLoop ? Number(maxSynthesisClosureIterations) : 1,
            allow_synthesis_timing_repair: allowSynthesisTimingRepair,
            allow_synthesis_lec_repair: allowSynthesisLecRepair,
            allow_synthesis_retiming: allowSynthesisRetiming,
            allow_synthesis_hierarchy_flattening: allowSynthesisHierarchyFlattening,
            stop_on_synthesis_closure_failure: stopOnSynthesisClosureFailure,
            stop_on_synthesis_lec_failure: stopOnSynthesisLecFailure,
          },
          analog_physical_mode: analogPhysicalMode,
          analog_pdk: analogPdk,
          analog_spice_text: hasProvidedSpice ? analogSpiceText || undefined : undefined,
          toggles: {
            run_spec2rtl_check: runSpec2RtlCheck,
            enable_scan_dft: enableScanDft,
            run_signoff_closure_loop: runSignoffClosureLoop,
            allow_timing_repair: allowTimingRepair,
            allow_drc_repair: allowDrcRepair,
            allow_lvs_repair: allowLvsRepair,
            allow_lec_repair: allowLecRepair,
            run_synthesis_closure_loop: runSynthesisClosureLoop,
            allow_synthesis_timing_repair: allowSynthesisTimingRepair,
            allow_synthesis_lec_repair: allowSynthesisLecRepair,
            allow_synthesis_retiming: allowSynthesisRetiming,
            allow_synthesis_hierarchy_flattening: allowSynthesisHierarchyFlattening,
            stop_on_synthesis_closure_failure: stopOnSynthesisClosureFailure,
            stop_on_synthesis_lec_failure: stopOnSynthesisLecFailure,
          },
          hem_enabled: hemEnabled,
          hem_mode: hemAdaptive ? "adaptive" : "fixed",
          hem_goal: hemGoal,
          hem_stage_toggles: hemStageToggles,
        }
      );
      setWorkflowId(out.workflow_id);
      setRunId(out.run_id);
    } catch (e: any) {
      setErr(e?.message || String(e));
    } finally {
      setRunning(false);
    }
  }

  function downloadZip() {
    if (!workflowId) return;
    window.open(`${API_BASE}/workflow/${workflowId}/download_zip?full=1`, "_blank");
  }

  function openNextFlow() {
    if (!workflowId || typeof window === "undefined") return;
    const sourceSystemRtlWorkflowId = systemRtlWorkflowId.trim() || workflowId;
    let context: DesignChainContext = {};
    try {
      context = JSON.parse(window.localStorage.getItem(DESIGN_CHAIN_CONTEXT_KEY) || "{}") as DesignChainContext;
    } catch {
      context = {};
    }
    context.systemRtlWorkflowId = sourceSystemRtlWorkflowId;
    context.systemPdWorkflowId = workflowId;
    context.systemPdRunId = runId || undefined;
    window.localStorage.setItem(DESIGN_CHAIN_CONTEXT_KEY, JSON.stringify(context));
    router.push(`/apps/${nextFlow}?handoff=1&from_workflow_id=${encodeURIComponent(sourceSystemRtlWorkflowId)}&parent_workflow_id=${encodeURIComponent(workflowId)}`);
  }

  if (loading) {
    return (
      <main className="min-h-screen bg-black text-white flex items-center justify-center">
        <div className="text-slate-300">Loading…</div>
      </main>
    );
  }

  return (
    <main className="min-h-screen bg-gradient-to-br from-slate-950 via-black to-slate-950 text-white">
      <div className="mx-auto w-full max-w-none px-6 py-10">
        <div className="flex items-center justify-between">
          <button onClick={() => router.push("/apps")} className="rounded-xl bg-slate-800 px-4 py-2 hover:bg-slate-700">
            Back to Apps
          </button>
          <button onClick={() => router.push("/workflow")} className="rounded-xl border border-slate-700 px-4 py-2 hover:bg-slate-900">
            Studio
          </button>
        </div>

        <div className="mt-6 rounded-2xl border border-slate-800 bg-slate-900/30 p-6">
          <div className="text-sm text-slate-400">System Loop</div>
          <h1 className="mt-2 text-3xl font-extrabold text-amber-300">System PD</h1>
          <p className="mt-2 text-slate-300">System RTL2GDS with synthesis, synthesis LEC, scan DFT, ATPG, STA, DRC/LVS/XOR, tapeout, and tapeout LEC evidence.</p>

          <div className="mt-6 grid gap-4 md:grid-cols-2">
            <div className="space-y-3">
              <label className="block text-sm text-slate-300">Project name (optional)</label>
              <input
                value={projectName}
                onChange={(e) => setProjectName(e.target.value)}
                className="w-full rounded-xl border border-slate-800 bg-black/30 px-4 py-2 text-slate-100"
              />
              <label className="block text-sm text-slate-300">
                System RTL workflow id
                <input
                  value={systemRtlWorkflowId}
                  onChange={(e) => setSystemRtlWorkflowId(e.target.value)}
                  className="mt-2 w-full rounded-xl border border-slate-800 bg-black/30 px-4 py-2 text-slate-100"
                  placeholder="Optional: continue from System RTL"
                />
              </label>
              <div className="grid gap-3 sm:grid-cols-3">
                <label className="block text-sm text-slate-300">
                  Foundry
                  <input value={foundry} onChange={(e) => setFoundry(e.target.value)} className="mt-2 w-full rounded-xl border border-slate-800 bg-black/30 px-4 py-2 text-slate-100" />
                </label>
                <label className="block text-sm text-slate-300">
                  PDK
                  <input value={pdk} onChange={(e) => setPdk(e.target.value)} className="mt-2 w-full rounded-xl border border-slate-800 bg-black/30 px-4 py-2 text-slate-100" />
                </label>
                <label className="block text-sm text-slate-300">
                  Toolchain
                  <input value={toolchain} onChange={(e) => setToolchain(e.target.value)} className="mt-2 w-full rounded-xl border border-slate-800 bg-black/30 px-4 py-2 text-slate-100" />
                </label>
              </div>

              <label className="block text-sm text-slate-300">
                Target frequency MHz
                <input value={targetFreqMhz} onChange={(e) => setTargetFreqMhz(e.target.value)} className="mt-2 w-full rounded-xl border border-slate-800 bg-black/30 px-4 py-2 text-slate-100" placeholder="Optional" />
              </label>

              {systemRtlWorkflowId.trim() ? (
                <div className="rounded-xl border border-slate-800 bg-black/30 p-3">
                  <div className="flex items-center justify-between gap-3">
                    <div className="text-sm font-semibold text-slate-200">Detected clock table</div>
                    <div className="text-xs text-slate-500">{clockProbeStatus}</div>
                  </div>
                  {clockRows.length ? (
                    <div className="mt-3 overflow-x-auto">
                      <table className="w-full text-left text-xs">
                        <thead className="text-slate-400">
                          <tr>
                            <th className="py-1 pr-2">Clock</th>
                            <th className="py-1 pr-2">Port</th>
                            <th className="py-1 pr-2">MHz</th>
                            <th className="py-1">Source</th>
                          </tr>
                        </thead>
                        <tbody>
                          {clockRows.map((clock, idx) => (
                            <tr key={`${clock.port}-${idx}`} className="border-t border-slate-800">
                              <td className="py-2 pr-2 text-slate-200">{clock.name}</td>
                              <td className="py-2 pr-2 text-slate-300">{clock.port}</td>
                              <td className="py-2 pr-2">
                                <input
                                  value={clock.frequency_mhz}
                                  onChange={(e) => updateClockFrequency(idx, e.target.value)}
                                  className="w-24 rounded-lg border border-slate-800 bg-black/40 px-2 py-1 text-slate-100"
                                  placeholder="MHz"
                                />
                              </td>
                              <td className="py-2 text-slate-500">{clock.source || "inferred"}</td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  ) : (
                    <div className="mt-2 text-xs text-slate-500">Clock rows will appear after a valid System RTL workflow ID is loaded.</div>
                  )}
                  {resetRows.length ? (
                    <div className="mt-2 text-xs text-slate-500">
                      Resets: {resetRows.map((reset: any) => reset.port || reset.name).filter(Boolean).join(", ")}
                    </div>
                  ) : null}
                </div>
              ) : null}

              <label className="block text-sm text-slate-300">
                SDC constraints
                <textarea value={constraintsSdc} onChange={(e) => setConstraintsSdc(e.target.value)} rows={4} className="mt-2 w-full rounded-2xl border border-slate-800 bg-black/30 p-4 text-slate-100" placeholder="Optional create_clock / constraints" />
              </label>

              <label className="block text-sm text-slate-300">
                Implementation effort
