                <label className="flex items-start gap-3 rounded-xl border border-slate-800 bg-black/20 p-3 text-sm text-slate-300">
                  <input type="checkbox" checked={runDrc} onChange={(e) => setRunDrc(e.target.checked)} className="mt-1" />
