                  type="button"
                  onClick={() => setQuestion(sample)}
                  className="rounded-md bg-slate-800 px-3 py-2 text-left text-xs text-slate-200 transition hover:bg-slate-700"
                >
                  {sample}
                </button>
              ))}
            </div>
          </div>
          <button
            type="button"
            onClick={askHelp}
            disabled={asking}
            className="mt-3 w-full rounded-md bg-cyan-300 px-4 py-2 text-sm font-bold text-slate-950 transition hover:bg-cyan-200 disabled:cursor-not-allowed disabled:opacity-60"
          >
            {asking ? "Asking..." : "Ask Help"}
          </button>

          {askError ? <p className="mt-3 rounded-md border border-red-500/30 bg-red-950/30 p-3 text-sm text-red-200">{askError}</p> : null}

          {answer ? (
            <section className="mt-4 rounded-lg border border-slate-800 bg-slate-950/70 p-4">
              <p className="text-sm leading-6 text-slate-200">{answer.answer}</p>
              <div className="mt-4">
                <p className="text-xs font-semibold uppercase text-slate-500">Suggested actions</p>
                <ul className="mt-2 space-y-2 text-sm text-slate-300">
                  {answer.suggested_actions.map((action) => (
                    <li key={action}>{action}</li>
                  ))}
                </ul>
              </div>
              <div className="mt-4 flex flex-wrap gap-2">
                {answer.sources.map((source) => (
                  <button
                    key={source.slug}
                    type="button"
                    onClick={() => selectTopic(source.slug)}
                    className="rounded-md border border-slate-700 px-3 py-2 text-xs font-semibold text-cyan-200 transition hover:border-cyan-400"
                  >
                    {source.title}
                  </button>
                ))}
              </div>
            </section>
          ) : null}
        </aside>
      </section>
    </main>
  );
}

"use client";

import React, { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import { createClientComponentClient, usesBackendPlatform } from "@/lib/platformClient";
import toast, { Toaster } from "react-hot-toast";

export default function LoginPage() {
  const router = useRouter();
  const supabase = createClientComponentClient();
  const backendPlatform = usesBackendPlatform();

  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [loading, setLoading] = useState(false);
  const [mode, setMode] = useState<"signin" | "signup">("signin");
  const [trialIntent, setTrialIntent] = useState(false);

  // ✅ NEW: prevent flash by waiting until auth is checked
  const [authChecked, setAuthChecked] = useState(false);

  const getNext = () => {
    if (typeof window === "undefined") return "/apps";
    const next = new URLSearchParams(window.location.search).get("next");
    return next && next.startsWith("/") ? next : "/apps";
  };

  useEffect(() => {
    let mounted = true;
  
    (async () => {
      const { data: { user } } = await supabase.auth.getUser();
      if (!mounted) return;
  
      const params = new URLSearchParams(window.location.search);
      if (params.get("mode") === "signup") setMode("signup");
      if (params.get("trial") === "1") setTrialIntent(true);

      setAuthChecked(true);
  
      if (user) router.replace(getNext());
    })();
  
    return () => {
      mounted = false;
    };
  }, [supabase, router]);
  
  
  // ✅ NEW: show a lightweight loading screen until session is known
  if (!authChecked) {
    return (
      <main className="min-h-screen flex flex-col justify-center items-center bg-[#0b0b0c] text-white">
        <div className="text-slate-300">Checking session...</div>
      </main>
    );
  }

  // 🔹 Email/Password sign-in or sign-up
  const handleEmailAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      let result;
      if (mode === "signup") {
        result = await supabase.auth.signUp({
          email,
          password,
          // ✅ small improvement: keep consistent apps-first landing after confirm
          options: {
            emailRedirectTo: `${window.location.origin}/auth/callback?next=${encodeURIComponent(getNext())}`,
          },
        });
      } else {
        result = await supabase.auth.signInWithPassword({ email, password });
      }

      if (result.error) throw result.error;

      toast.success(
        mode === "signup"
          ? trialIntent
            ? "Account created. Complete Stripe trial checkout to start your 3-day trial."
            : "Account created! Check your email to confirm."
          : "Welcome back!"
      );

      if (mode === "signin") router.replace(getNext()); // ✅ replace
    } catch (error: unknown) {
      const message = error instanceof Error ? error.message : "Something went wrong.";
      toast.error(message);
    } finally {
      setLoading(false);
    }
  };

  

  // 🔹 Magic Link
  const handleMagicLink = async () => {
    setLoading(true);
    const { error } = await supabase.auth.signInWithOtp({
      email,
      // ✅ small improvement: apps-first return
      options: { emailRedirectTo: `${window.location.origin}/auth/callback?next=${encodeURIComponent(getNext())}` },
    });
    setLoading(false);
    if (error) toast.error(error.message);
    else toast.success("Magic link sent. Check your inbox.");
  };

  const handleOidcLogin = () => {
    window.location.href = `/auth/oidc?next=${encodeURIComponent(getNext())}`;
  };

  return (
    <main className="min-h-screen flex flex-col justify-center items-center bg-[#0b0b0c] text-white">
      <Toaster position="top-center" reverseOrder={false} />
      <div className="bg-slate-900 border border-slate-700 p-8 rounded-2xl shadow-2xl w-96">
        <h1 className="text-3xl font-extrabold text-white text-center mb-4">
          {mode === "signup" && trialIntent ? "Start ChipLoop 3-Day Trial" : "ChipLoop Login"}
        </h1>

        {backendPlatform ? (
          <button
            onClick={handleOidcLogin}
            className="w-full rounded-md bg-cyan-500 px-4 py-3 font-semibold text-black transition hover:bg-cyan-400"
          >
            Sign in with company identity
          </button>
        ) : null}

        {/* Toggle between Sign In / Sign Up */}
        {!backendPlatform ? (
        <>
        <div className="flex justify-center mb-6 space-x-4">
          <button
            onClick={() => setMode("signin")}
            className={`px-4 py-2 rounded-md font-semibold ${
              mode === "signin"
                ? "bg-cyan-500 text-black"
                : "bg-slate-800 text-gray-300"
            }`}
          >
            Sign In
          </button>
          <button
            onClick={() => setMode("signup")}
            className={`px-4 py-2 rounded-md font-semibold ${
              mode === "signup"
                ? "bg-cyan-500 text-black"
                : "bg-slate-800 text-gray-300"
            }`}
          >
            Sign Up
          </button>
        </div>

        {mode === "signup" && trialIntent ? (
          <div className="mb-5 rounded-lg border border-cyan-700/60 bg-cyan-950/30 p-3 text-sm text-cyan-100">
            Free 3-day trial. Starter is $19.99/month after 3 days. Billing is handled securely by Stripe. Cancel anytime before trial ends.
          </div>
        ) : null}

        {/* Email form */}
        <form onSubmit={handleEmailAuth} className="flex flex-col space-y-4">
          <input
            type="email"
            placeholder="you@example.com"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            required
            className="px-4 py-2 rounded-md border border-slate-700 bg-slate-950 text-white placeholder:text-slate-500 outline-none focus:ring-2 focus:ring-cyan-400"
          />
          <input
            type="password"
            placeholder="Enter password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
            className="px-4 py-2 rounded-md border border-slate-700 bg-slate-950 text-white placeholder:text-slate-500 outline-none focus:ring-2 focus:ring-cyan-400"
          />

          <button
            type="submit"
            disabled={loading}
            className={`w-full py-2 rounded-md font-semibold transition ${
              loading
                ? "bg-gray-500 cursor-not-allowed"
                : "bg-cyan-500 hover:bg-cyan-400 text-black"
            }`}
          >
            {loading
              ? mode === "signup"
                ? "Creating..."
                : "Signing in..."
              : mode === "signup"
              ? trialIntent ? "Start free trial" : "Create Account"
              : "Sign In"}
          </button>
        </form>
        </>
        ) : null}

        {/* Magic link login */}
        {!backendPlatform ? (
        <div className="mt-4 text-center text-sm text-gray-400">
          <button
            onClick={handleMagicLink}
            className="text-cyan-400 hover:underline"
          >
            Or send me a Magic Link
          </button>
        </div>
        ) : null}

        
      </div>

      <p className="text-gray-500 text-xs mt-6">
        {backendPlatform ? "Secure login powered by your company identity provider." : "Secure login powered by Supabase Auth. Trial billing is handled by Stripe."}
      </p>
    </main>
  );
}

"use client";

import { useEffect, useState } from "react";
import { useParams } from "next/navigation";
import { apiGet, apiPost } from "@/lib/apiClient";
import TopNav from "@/components/TopNav";

type Listing = {
  id: string;
  name: string;
  slug: string;
  description?: string;
  domain?: string;
  loop_type?: string;
  version?: string;
  agent_spec?: Record<string, unknown>;
  skills?: string[];
  tools?: string[];
  hooks?: string[];
  reviews?: Review[];
};

type Review = { id?: string; user_id?: string; rating: number; review_text?: string; created_at?: string };

type DetailResponse = { status: string; agent: Listing };

type InstallResponse = { status: string; installed_agent?: { agent_name?: string } };

export default function MarketplaceAgentDetailPage() {
  const params = useParams<{ slug: string }>();
  const slug = params.slug;
  const [agent, setAgent] = useState<Listing | null>(null);
  const [rating, setRating] = useState(5);
  const [reviewText, setReviewText] = useState("");
  const [message, setMessage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  async function loadAgent() {
    setLoading(true);
    setError(null);
    try {
      const data = await apiGet<DetailResponse>(`/marketplace/agents/${slug}`);
      setAgent(data.agent);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to load agent.");
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    if (slug) loadAgent();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [slug]);

  async function installAgent() {
    if (!agent) return;
    setMessage(null);
    setError(null);
    try {
      const data = await apiPost<InstallResponse>(`/marketplace/agents/${agent.id}/install`);
      setMessage(`Installed ${data.installed_agent?.agent_name || agent.name} into My Agents.`);
      window.dispatchEvent(new Event("refreshAgents"));
    } catch (err) {
      setError(err instanceof Error ? err.message : "Install failed.");
    }
  }

  async function submitReview() {
    if (!agent) return;
    setMessage(null);
    setError(null);
    try {
      await apiPost(`/marketplace/agents/${agent.id}/reviews`, { rating, review_text: reviewText });
      setReviewText("");
      setMessage("Review saved.");
      loadAgent();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Review failed.");
    }
  }

  return (
    <main className="min-h-screen bg-gradient-to-br from-slate-950 via-black to-slate-950 text-white">
      <TopNav current="marketplace" showMarketplace />

      <section className="mx-auto max-w-[1440px] px-6 py-8">
        {loading ? <div className="text-slate-400">Loading...</div> : null}
        {error ? <div className="rounded-xl border border-red-900/70 bg-red-950/30 p-4 text-red-200">{error}</div> : null}
        {message ? <div className="rounded-xl border border-emerald-900/70 bg-emerald-950/30 p-4 text-emerald-200">{message}</div> : null}

        {agent ? (
          <div className="grid gap-6 lg:grid-cols-[1fr_360px]">
            <div className="space-y-5">
              <section className="rounded-2xl border border-slate-800 bg-slate-900/35 p-6">
                <div className="flex flex-wrap items-start justify-between gap-4">
                  <div>
                    <div className="text-xs font-semibold uppercase text-cyan-300">Verified marketplace agent</div>
                    <h1 className="mt-2 text-3xl font-extrabold">{agent.name}</h1>
                    <p className="mt-3 max-w-3xl leading-7 text-slate-300">{agent.description || "No description provided."}</p>
                  </div>
                  <button onClick={installAgent} className="rounded-xl bg-cyan-600 px-5 py-3 font-bold hover:bg-cyan-500">Install Agent</button>
                </div>
                <div className="mt-5 flex flex-wrap gap-2 text-xs text-slate-300">
                  <span className="rounded-full border border-slate-700 px-2 py-1">{agent.loop_type || "system"}</span>
