"use client";

import { useEffect, useMemo, useState } from "react";
import { useParams, useRouter } from "next/navigation";
import TopNav from "@/components/TopNav";
import SpecTextBox from "@/components/SpecTextBox";
import { apiDelete, apiGet, apiPatch, apiPost } from "@/lib/apiClient";

type Stage = {
  id: string;
  label: string;
  app: string;
  required?: boolean;
  recommended?: boolean;
  optional?: boolean;
  enabled?: boolean;
  settings?: Record<string, unknown>;
};

type Product = {
  id: string;
  name: string;
  product_type: string;
  starting_point: string;
  description: string;
  status: string;
  stage_config?: {
    source?: string;
    reference_slug?: string;
    stages?: Stage[];
  };
  stage_results?: Record<string, unknown>;
  updated_at?: string;
};

type ProductRun = {
  id: string;
  product_id: string;
  status: string;
  current_stage?: string | null;
  error?: string | null;
  stage_results?: Record<string, unknown>;
  logs?: string | null;
  created_at?: string;
  updated_at?: string;
  completed_at?: string | null;
};

type StageRun = {
  id: string;
  stage_id: string;
  stage_label: string;
  app: string;
  status: string;
  workflow_id?: string | null;
  run_id?: string | null;
  inputs?: Record<string, unknown> | null;
  outputs?: Record<string, unknown> | null;
  error?: string | null;
  started_at?: string | null;
  completed_at?: string | null;
};

type ProductRunWithStages = ProductRun & {
  stage_runs?: StageRun[];
};

type StageOption = string | {
  value: string;
  label?: string;
  disabled?: boolean;
};

type UserApp = {
  id: string;
  workflow_id: string;
  workflow_name?: string | null;
  name: string;
  description?: string | null;
  category?: string | null;
  loop_type?: string | null;
  input_schema?: {
    fields?: Array<{
      key: string;
      label?: string;
      type?: "text" | "textarea" | "number" | "boolean" | "select";
      default?: string | number | boolean;
      defaultValue?: string | number | boolean;
      required?: boolean;
      helper?: string;
      options?: StageOption[];
    }>;
    note?: string;
  } | null;
  default_config?: Record<string, string | number | boolean> | null;
  marketplace_status?: string | null;
};

type UserAppsResponse = {
  status: string;
  apps: UserApp[];
};

const APP_LINKS: Record<string, string> = {
  Digital_Arch2RTL: "/apps/arch2rtl",
