function typeLabel(value: string) {
  return value.replace(/_/g, "-").replace(/\b\w/g, (letter) => letter.toUpperCase());
}

function stageKind(stage: Stage) {
  if (stage.required) return "Required";
  if (stage.recommended) return "Recommended";
  if (stage.optional) return "Optional";
  return "Stage";
}

function stageEnabled(stage: Stage) {
  if (stage.required) return true;
  if (stage.optional && stage.enabled === undefined) return false;
  return stage.enabled !== false;
}

function fieldValue(stage: Stage, field: StageField) {
  return stage.settings?.[field.key] ?? field.defaultValue;
}

function userAppSchemaFromStage(stage: Stage): StageSchema | null {
  if (!stage.app.startsWith("User_App:")) return null;
  const inputSchema = stage.settings?.input_schema;
  if (!inputSchema || typeof inputSchema !== "object" || Array.isArray(inputSchema)) {
    return { fields: [], note: "This app does not have a stored input contract. Recreate or update the app from a workflow that defines workflow settings." };
  }
  const rawFields = (inputSchema as { fields?: unknown }).fields;
  if (!Array.isArray(rawFields)) {
    return { fields: [], note: "This app input contract has no fields. Recreate or update the app from a workflow that defines workflow settings." };
  }
  const defaultConfig = stage.settings?.default_config && typeof stage.settings.default_config === "object" && !Array.isArray(stage.settings.default_config)
    ? stage.settings.default_config as Record<string, string | number | boolean>
    : {};
  const fields = rawFields.flatMap((raw): StageField[] => {
    if (!raw || typeof raw !== "object" || Array.isArray(raw)) return [];
    const item = raw as Record<string, unknown>;
    const key = String(item.key || "").trim();
    if (!key) return [];
    const rawType = String(item.type || "text");
    const type: StageField["type"] =
      rawType === "number" || rawType === "boolean" || rawType === "select" || rawType === "textarea"
        ? rawType
        : "text";
    const defaultValue = defaultConfig[key] ?? item.defaultValue ?? item.default ?? (type === "boolean" ? false : "");
    return [{
      key,
      label: String(item.label || key),
      type,
      defaultValue: typeof defaultValue === "number" || typeof defaultValue === "boolean" ? defaultValue : String(defaultValue ?? ""),
      required: Boolean(item.required),
      helper: typeof item.helper === "string" ? item.helper : undefined,
      options: Array.isArray(item.options)
        ? item.options.flatMap((option): StageOption[] => {
            if (typeof option === "string") return option.trim() ? [option.trim()] : [];
            if (option && typeof option === "object" && !Array.isArray(option)) {
              const optionRow = option as Record<string, unknown>;
              const value = String(optionRow.value || "").trim();
              if (!value) return [];
              return [{
                value,
                label: typeof optionRow.label === "string" ? optionRow.label : undefined,
                disabled: Boolean(optionRow.disabled),
              }];
            }
            return [];
          })
        : undefined,
    }];
  });
  return {
    fields,
    note: typeof (inputSchema as { note?: unknown }).note === "string"
      ? String((inputSchema as { note?: unknown }).note)
      : "Inputs come from the app's saved workflow contract.",
  };
}

function stageSchemaForStage(stage: Stage, stageSchemas: Record<string, StageSchema>): StageSchema | null {
  return userAppSchemaFromStage(stage) || stageSchemas[stage.app] || null;
}

function normalizedWorkflowName(value?: string | null) {
  return String(value || "").replace(/^App:\s*/, "").trim();
}

function mergeSchemaFields(fields: StageField[], additions: StageField[]) {
  const seen = new Set(additions.map((field) => field.key));
  return [...additions, ...fields.filter((field) => !seen.has(field.key))];
}

function fullWorkflowRootInputs(workflowName: string): StageField[] {
  const name = normalizedWorkflowName(workflowName);
  if (/^Digital_/.test(name) && !["Digital_Arch2RTL", "Digital_Spec2RTL_Check"].includes(name)) {
    return [
      { key: "spec_text", label: "Digital spec text", type: "textarea", defaultValue: "", helper: "Required when this workflow app runs without an upstream Arch2RTL handoff." },
      { key: "top_module", label: "Top module", type: "text", defaultValue: "" },
    ];
  }
  if (/^System_/.test(name) && !["System_RTL", "System_Product_App_Builder"].includes(name)) {
    return [
      { key: "digital_spec", label: "Digital spec", type: "textarea", defaultValue: "", helper: "Required when this workflow app runs without an upstream System RTL handoff." },
      { key: "analog_spec", label: "Analog spec", type: "textarea", defaultValue: "", helper: "Required when this workflow app runs without an upstream System RTL handoff." },
      { key: "soc_spec", label: "SoC spec", type: "textarea", defaultValue: "", helper: "Required when this workflow app runs without an upstream System RTL handoff." },
    ];
  }
  return [];
}

function augmentSchemaForWorkflowApp(schema: StageSchema, workflowName: string): StageSchema {
  const additions = fullWorkflowRootInputs(workflowName);
  if (!additions.length) return schema;
  return {
    ...schema,
    note: schema.note || "This private app can run as a full workflow. Provide root specs when no upstream handoff stage exists.",
    fields: mergeSchemaFields(schema.fields || [], additions),
  };
}

function userAppPlatformSchema(app: UserApp, stageSchemas: Record<string, StageSchema>): StageSchema | null {
  const candidates = [
    app.workflow_name,
    app.name,
    app.workflow_name?.replace(/^App:\s*/, ""),
    app.name?.replace(/^App:\s*/, ""),
  ].filter(Boolean) as string[];
  for (const candidate of candidates) {
    const schema = stageSchemas[candidate];
    if (schema?.fields?.length) return augmentSchemaForWorkflowApp(schema, candidate);
  }
  return null;
}

function defaultConfigFromSchema(schema?: StageSchema | null): Record<string, string | number | boolean> {
  const out: Record<string, string | number | boolean> = {};
  for (const field of schema?.fields || []) {
    out[field.key] = field.defaultValue;
  }
  return out;
}

function inputSchemaHasFields(schema: unknown): boolean {
  if (!schema || typeof schema !== "object" || Array.isArray(schema)) return false;
  const fields = (schema as { fields?: unknown }).fields;
  return Array.isArray(fields) && fields.length > 0;
}

function inputSchemaHasAllFieldKeys(schema: unknown, expectedSchema: unknown): boolean {
  if (!schema || typeof schema !== "object" || Array.isArray(schema)) return false;
  if (!expectedSchema || typeof expectedSchema !== "object" || Array.isArray(expectedSchema)) return true;
  const currentFields = (schema as { fields?: unknown }).fields;
  const expectedFields = (expectedSchema as { fields?: unknown }).fields;
  if (!Array.isArray(currentFields) || !Array.isArray(expectedFields)) return true;
  const currentKeys = new Set(currentFields.flatMap((field) => (
    field && typeof field === "object" && !Array.isArray(field) ? [String((field as { key?: unknown }).key || "")] : []
  )));
  return expectedFields.every((field) => {
    if (!field || typeof field !== "object" || Array.isArray(field)) return true;
    const key = String((field as { key?: unknown }).key || "");
    return !key || currentKeys.has(key);
  });
}

function appContractForProductStage(app: UserApp, stageSchemas: Record<string, StageSchema>) {
  const savedFields = app.input_schema?.fields || [];
  if (savedFields.length) {
    return {
      inputSchema: app.input_schema,
      defaultConfig: app.default_config || {},
      source: "user_app_contract",
    };
  }
  const platformSchema = userAppPlatformSchema(app, stageSchemas);
  if (platformSchema) {
    return {
      inputSchema: platformSchema,
      defaultConfig: defaultConfigFromSchema(platformSchema),
      source: "platform_stage_schema",
    };
  }
  return {
    inputSchema: { fields: [] },
    defaultConfig: {},
    source: "missing_contract",
  };
}

function optionValue(option: StageOption) {
  return typeof option === "string" ? option : option.value;
}

function optionLabel(option: StageOption) {
  return typeof option === "string" ? option : option.label || option.value;
}

function optionDisabled(option: StageOption) {
  return typeof option === "string" ? false : Boolean(option.disabled);
}

function isBlank(value: unknown) {
  return value === undefined || value === null || (typeof value === "string" && value.trim().length === 0);
}

function formatDate(value?: string | null) {
  if (!value) return "-";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "-";
  return date.toLocaleString();
}

function appLink(app: string, workflowId?: string | null, runId?: string | null) {
