  const rawLines = stageRun.outputs?.agent_log_lines;
  if (!Array.isArray(rawLines)) return [];
  return rawLines.flatMap((line) => {
    const text = typeof line === "string" ? line.trim() : "";
    return text ? [`${stageRun.stage_label || stageRun.app}: ${text}`] : [];
