              className="w-full mb-4 rounded-lg bg-slate-800 border border-slate-700 p-2 text-slate-200"
            />
           <div className="flex justify-end gap-2">
              <button
                onClick={() => setRenameTarget({ oldName: "", newName: "" })}
                className="px-4 py-2 rounded bg-slate-700 hover:bg-slate-600"
              >
                Cancel
              </button>
              <button
                onClick={renameCustomWorkflow}
                className="px-4 py-2 rounded bg-cyan-500 text-black font-semibold hover:bg-cyan-400"
              >
                Rename
              </button>
            </div>
          </div>
        </div>
      )}

             {/* Agent context menu */}
      {agentMenu && (
          <div
            className="fixed z-50 bg-slate-800 text-white border border-slate-600 rounded shadow-xl py-1"
            style={{ left: agentMenu.x, top: agentMenu.y }}
            onMouseLeave={closeAgentMenu}
          >
            <button
              className="px-4 py-1 hover:bg-slate-700 w-full text-left"
              onClick={() => openAgentEditor(agentMenu.name)}
            >
              View / Edit Draft
            </button>
            <div className="my-1 border-t border-slate-700" />
            <button
              className="px-4 py-1 hover:bg-slate-700 w-full text-left"
              onClick={() => renameCustomAgent(agentMenu.name)}
            >
              Rename
            </button>
            <button
              className="px-4 py-1 hover:bg-slate-700 disabled:cursor-not-allowed disabled:opacity-60 w-full text-left"
              onClick={() => publishCustomAgent(agentMenu.name)}
              disabled={agentMenu.status === "submitted"}
            >
              {agentMenu.status === "submitted" ? "Submitted for Review" : "Submit to Marketplace"}
            </button>
            <button
              className="px-4 py-1 hover:bg-slate-700 w-full text-left text-red-400"
              onClick={() => deleteCustomAgent(agentMenu.name)}
            >
              Delete
            </button>
          </div>
      )}

      {agentEditor && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/70 p-4">
          <div className="flex max-h-[92vh] w-full max-w-5xl flex-col overflow-hidden rounded-xl border border-slate-700 bg-slate-950 text-white shadow-2xl">
            <div className="flex items-start justify-between gap-4 border-b border-slate-800 p-5">
              <div>
                <h3 className="text-xl font-bold text-white">Private Draft Agent</h3>
                <p className="mt-1 text-sm text-slate-400">View and edit the saved draft content. JSON fields must remain valid before saving.</p>
              </div>
              <button className="rounded border border-slate-700 px-3 py-2 text-sm text-slate-300 hover:bg-slate-900" onClick={() => setAgentEditor(null)}>
                Close
              </button>
            </div>

            <div className="min-h-0 overflow-y-auto p-5 scrollbar-thin scrollbar-thumb-slate-700 scrollbar-track-transparent">
              {agentEditor.error ? (
                <div className="mb-4 rounded border border-red-800 bg-red-950/30 p-3 text-sm text-red-200">{agentEditor.error}</div>
              ) : null}

              <section className="grid gap-4 md:grid-cols-3">
                <label className="text-sm font-semibold text-slate-200">
                  Name
                  <input
                    value={agentEditor.name}
                    onChange={(event) => setAgentEditor((current) => current ? { ...current, name: event.target.value } : current)}
                    className="mt-2 w-full rounded border border-slate-700 bg-black/40 px-3 py-2 text-sm font-normal outline-none focus:border-cyan-600"
                  />
                </label>
                <label className="text-sm font-semibold text-slate-200">
                  Loop
                  <select
                    value={agentEditor.loopType}
                    onChange={(event) => setAgentEditor((current) => current ? { ...current, loopType: event.target.value } : current)}
                    className="mt-2 w-full rounded border border-slate-700 bg-black/40 px-3 py-2 text-sm font-normal outline-none focus:border-cyan-600"
                  >
                    {["physical_ai", "digital", "analog", "embedded", "system", "validation"].map((item) => (
                      <option key={item} value={item}>{item[0].toUpperCase() + item.slice(1)}</option>
                    ))}
                  </select>
                </label>
                <label className="text-sm font-semibold text-slate-200">
                  Status
                  <select
                    value={agentEditor.status}
                    onChange={(event) => setAgentEditor((current) => current ? { ...current, status: event.target.value } : current)}
                    className="mt-2 w-full rounded border border-slate-700 bg-black/40 px-3 py-2 text-sm font-normal outline-none focus:border-cyan-600"
                  >
                    {["draft", "private", "submitted"].map((item) => (
                      <option key={item} value={item}>{item[0].toUpperCase() + item.slice(1)}</option>
                    ))}
                  </select>
                </label>
              </section>

              <label className="mt-4 block text-sm font-semibold text-slate-200">
                Description
                <textarea
                  value={agentEditor.description}
                  onChange={(event) => setAgentEditor((current) => current ? { ...current, description: event.target.value } : current)}
                  className="mt-2 h-24 w-full resize-none rounded border border-slate-700 bg-black/40 p-3 text-sm font-normal outline-none focus:border-cyan-600"
                />
              </label>

              <section className="mt-4 grid gap-4 lg:grid-cols-2">
                {[
                  ["Agent spec", "agentSpecText", "h-72"],
                  ["Skills", "skillsText", "h-40"],
                  ["Tools / MCP", "toolsText", "h-40"],
                  ["Hooks", "hooksText", "h-40"],
                  ["Generated files", "generatedFilesText", "h-56"],
                  ["Registry patch", "registryPatchText", "h-56"],
                ].map(([label, key, height]) => (
                  <label key={key} className="block text-sm font-semibold text-slate-200">
                    {label}
                    <textarea
                      value={String(agentEditor[key as keyof typeof agentEditor] || "")}
                      onChange={(event) => setAgentEditor((current) => current ? { ...current, [key]: event.target.value } : current)}
                      spellCheck={false}
                      className={`mt-2 ${height} w-full resize-none rounded border border-slate-700 bg-black/40 p-3 font-mono text-xs font-normal outline-none focus:border-cyan-600`}
                    />
                  </label>
                ))}
              </section>
            </div>

            <div className="flex justify-end gap-2 border-t border-slate-800 p-4">
              <button className="rounded border border-slate-700 px-4 py-2 text-sm text-slate-200 hover:bg-slate-900" onClick={() => setAgentEditor(null)}>
                Cancel
              </button>
              <button
                className="rounded bg-emerald-700 px-4 py-2 text-sm font-bold text-white hover:bg-emerald-600 disabled:cursor-not-allowed disabled:bg-slate-800 disabled:text-slate-500"
                onClick={saveAgentEditor}
                disabled={agentEditor.saving}
              >
                {agentEditor.saving ? "Saving..." : "Save Draft"}
              </button>
            </div>
          </div>
        </div>
      )}

      {designIntentMenu && (
        <div
          className="absolute z-50 bg-slate-900 border border-slate-700 rounded shadow-lg text-xs"
          style={{ top: designIntentMenu.y, left: designIntentMenu.x }}
          onMouseLeave={closeDesignIntentMenu}
        >
          <button
            className="block w-full text-left px-3 py-1 hover:bg-slate-800"
            onClick={() => {
          // Edit = open in Planner with hydration
              openDesignIntentJsonEditor(designIntentMenu.intent);
              closeDesignIntentMenu();
            }}
          >
            Edit
          </button>
          <button
            className="block w-full text-left px-3 py-1 hover:bg-slate-800"
            onClick={() => renameDesignIntent(designIntentMenu.intent)}
          >
            Rename
          </button>
          <button
            className="block w-full text-left px-3 py-1 text-red-400 hover:bg-red-900/40"
            onClick={() => deleteDesignIntent(designIntentMenu.intent)}
          >
            Delete
          </button>
        </div>
      )}

      {showInstrumentPicker && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70">
          {selectedWorkflowName === "Validation_Create_Bench" && (
            <div className="mb-4 space-y-2">
              <input
                className="w-full border px-2 py-1"
                placeholder="Bench name"
                value={benchName}
                onChange={(e) => setBenchName(e.target.value)}
              />
              <input
                className="w-full border px-2 py-1"
                placeholder="Bench location (optional)"
                value={benchLocation}
                onChange={(e) => setBenchLocation(e.target.value)}
              />
            </div>
          )}

          <div className="w-full max-w-2xl rounded-xl bg-zinc-900 p-5 text-white shadow-xl">
            <div className="flex items-center justify-between">
              <h2 className="text-lg font-semibold">Select instruments for this Validation run</h2>
              <button
                className="rounded px-2 py-1 bg-zinc-800 hover:bg-zinc-700"
                onClick={() => setShowInstrumentPicker(false)}
              >
                x
              </button>
            </div>

            {instrumentLoadErr && (
              <div className="mt-3 rounded bg-red-900/40 p-2 text-sm">{instrumentLoadErr}</div>
            )}

            <div className="mt-4 space-y-2">
              {(validationInstruments || []).map((inst: any) => (
                <label key={inst.id} className="flex items-center gap-3 rounded bg-zinc-800/60 p-3">
                  <input
                    type="checkbox"
                    checked={selectedInstrumentIds.includes(inst.id)}
                    onChange={() => toggleInstrument(inst.id)}
                  />
                  <div className="flex-1">
                    <div className="font-medium">
                      {inst.nickname} {inst.is_default ? <span className="text-xs text-cyan-300">(default)</span> : null}
                    </div>
                    <div className="text-xs text-zinc-300">
                      {inst.vendor} {inst.model} - {inst.instrument_type} - {inst.interface} - {inst.resource_string}
                    </div>
                    {inst.scpi_idn && <div className="text-xs text-zinc-400 mt-1">IDN: {inst.scpi_idn}</div>}
                  </div>

                  <button
                    className="rounded bg-zinc-700 px-3 py-1 text-sm hover:bg-zinc-600"
                    onClick={async () => {
                      await fetch(`${API_BASE}/validation/instruments/${inst.id}/probe`, { method: "POST" });
                      await fetchValidationInstruments();
                    }}
                  >
                    Test
                  </button>
                </label>
              ))}
            </div>

            {/* Add instrument mini-form */}
            <div className="mt-5 rounded bg-zinc-800/50 p-3">
              <div className="text-sm font-medium mb-2">Add instrument</div>

              <div className="grid grid-cols-2 gap-2">
                <input
                  className="rounded bg-zinc-900 p-2 text-sm"
                  placeholder="Nickname"
                  value={newInstrument.nickname}
                  onChange={(e) => setNewInstrument(s => ({ ...s, nickname: e.target.value }))}
                />
                <input
                  className="rounded bg-zinc-900 p-2 text-sm"
                  placeholder="Model (e.g. E36312A)"
                  value={newInstrument.model}
                  onChange={(e) => setNewInstrument(s => ({ ...s, model: e.target.value }))}
                />

                {/* Instrument Type */}
                <select
                  className="rounded bg-zinc-900 p-2 text-sm border border-zinc-700"
                  value={newInstrument.instrument_type}
                  onChange={(e) =>
                    setNewInstrument({
                      ...newInstrument,
                      instrument_type: e.target.value,
                    })
                  }
                >
                  <option value="psu">PSU</option>
                  <option value="dmm">DMM</option>
                  <option value="smu">SMU</option>
                  <option value="scope">Scope</option>
                </select>
  
                <input
                  className="col-span-2 rounded bg-zinc-900 p-2 text-sm"
                  placeholder='Resource string (e.g. TCPIP0::192.168.0.10::INSTR)'
                  value={newInstrument.resource_string}
                  onChange={(e) => setNewInstrument(s => ({ ...s, resource_string: e.target.value }))}
                />
              </div>

              <div className="mt-2 flex gap-2">
                <button
                  className="rounded bg-cyan-700 px-3 py-2 text-sm hover:bg-cyan-600"
                  onClick={registerValidationInstrument}
                >
                  Register
                </button>
              </div>
            </div>

            {/* Confirm */}
            <div className="mt-5 flex justify-end gap-2">
              <button
                className="rounded bg-zinc-800 px-4 py-2 text-sm hover:bg-zinc-700"
                onClick={() => setShowInstrumentPicker(false)}
              >
                Cancel
              </button>
              <button
                className="rounded bg-green-700 px-4 py-2 text-sm hover:bg-green-600"
                
                onClick={async () => {
                  if (!selectedInstrumentIds.length) {
                    alert("Select at least one instrument.");
                    return;
                  }
                  const wfNameLower = (selectedWorkflowName || "").toLowerCase();
                  const isCreateBench = wfNameLower.includes("validation_create_bench");

                  const isBenchRun =
                    wfNameLower.includes("validation_preflight_bench") ||
                    wfNameLower.includes("validation_hardware_test_run") ||
                    wfNameLower.includes("preflight") ||
                    wfNameLower.includes("hardware_test_run");
                
                  // Create Bench: NO spec required, NO preview, run immediately
                  if (isCreateBench) {
                    if (!benchName || !benchName.trim()) {
                      alert("Bench name is required.");
                      return; // keep modal open
                    }
                    if (!pendingWorkflowPayload) {
                      alert("Missing pending workflow payload. Please click Run Workflow again.");
                      return;
                    }
                
                    setShowInstrumentPicker(false);
                
                    // spec_text must be empty for create-bench
                    await runWorkflowWithFormData(
                      pendingWorkflowPayload,
                      "",            // spec text
                      undefined,     // spec file
                      selectedInstrumentIds,
                      undefined,     // scope payload
                      undefined,      // benchId
                      testPlanName,
                      previewTestPlan
                    );
                
                    return;
                  }

                  // Bench runs: also skip spec + preview
                  if (isBenchRun) {
                    if (!pendingWorkflowPayload) {
                      alert("Missing pending workflow payload. Please click Run Workflow again.");
                      return;
                    }
                    setShowInstrumentPicker(false);

                    await runWorkflowWithFormData(
                      pendingWorkflowPayload,
                      "",                 // spec text
                      undefined,          // spec file
                      selectedInstrumentIds,
                      undefined,          // scope
                      selectedBenchId || undefined,// bench_id if you have it (optional)
                      testPlanName,
                      previewTestPlan
                    );
                    return;
                  }
                
                  // Existing Validation run flow (WF-1): preview -> scope modal
                  setShowInstrumentPicker(false);
                
                  if (!pendingWorkflowPayload) {
                    alert("Missing pending workflow payload. Please click Run Workflow again.");
                    return;
                  }

                  setShowInstrumentPicker(false);
                  // Trigger actual workflow execution now
                  if (!pendingWorkflowPayload) {
                    alert("Missing pending workflow payload. Please click Run Workflow again.");
                    return;
                  }

                  // Phase-0 (Option 1): generate test plan preview, then open scope modal
                  const selectedInstrumentRows = (validationInstruments || []).filter((i: any) =>
                    selectedInstrumentIds.includes(i.id)
                  );

                  setSelectedInstrumentRows(selectedInstrumentRows);

                  const wfId =
                    pendingWorkflowPayload?.workflow_id ||
                    pendingWorkflowPayload?.id ||
                    pendingWorkflowPayload?.workflowId;

                  const dsText = (pendingSpecText || "").trim();

                  if (!wfId) {
                    alert("Missing workflow_id for preview. Please click Run Workflow again.");
                    return;
                  }
                  if (!dsText) {
                    alert("Missing datasheet/spec text. Please paste datasheet in the Spec modal.");
                    return;
                  }

                  console.log("[Preview] wfId =", wfId);
                  console.log("[Preview] datasheet_text length =", dsText.length);
                  const resp = await fetch(`${API_BASE}/validation/test_plan/preview`, {
                    method: "POST",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify({
                      workflow_id: wfId,
                      datasheet_text: dsText,
                      goal: "Create a validation test plan",
                    }),
                  });

                  let data: any;
                  try {
                    data = await resp.json();
                  } catch (e) {
                    const raw = await resp.text().catch(() => "");
                    console.error("[Preview] resp.json() failed. status=", resp.status, "raw=", raw);
                    alert(`Preview response was not JSON (status ${resp.status}). See console.`);
                    return;
                  }

                  
                  if (!resp.ok || data?.status !== "ok") {
                    alert(data?.message || "Failed to generate test plan preview");
                    return;
                  }

                  const plan = data.test_plan;
                  setPreviewTestPlan(plan);
                  // open scope modal (user selects tests/features + sees instrument coverage)
                  setShowScopeModal(true);

                  try {
                    const tests = Array.isArray(plan?.tests) ? plan.tests : [];
                    const allNames = tests.map((t: any) => t?.name).filter(Boolean);
                    setSelectedTestNames(allNames);
                  
                    const missing = computeMissingInstrumentTypes(plan, allNames, selectedInstrumentRows);
                    setMissingInstrumentTypes(missing);
                  } catch (e) {
                    console.error("[Preview] post-processing failed:", e, plan);
                    // modal is already open; user can still proceed or you can show a message later
                    setSelectedTestNames([]);
                    setMissingInstrumentTypes([]);
                  }

                  
                }}
              >
                Use selected instruments
              </button>
            </div>
          </div>
        </div>
      )}

      {showBenchPicker && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60">
          <div className="w-[700px] max-w-[95vw] rounded-lg bg-zinc-900 p-4 border border-zinc-700">
            <div className="flex items-center justify-between">
              <h3 className="text-lg font-semibold text-white">Select Bench</h3>
              <button className="text-zinc-300 hover:text-white" onClick={() => setShowBenchPicker(false)}>x</button>
            </div>

            <div className="mt-3">
              <select
                className="w-full rounded bg-zinc-800 border border-zinc-700 p-2 text-white"
                value={selectedBenchId}
                onChange={(e) => setSelectedBenchId(e.target.value)}
              >
                <option value="">-- choose a bench --</option>
                {validationBenches.map((b) => (
                  <option key={b.id} value={b.id}>
                    {b.name} - {b.location || "NA"} ({b.status})
                  </option>
                ))}
              </select>
              {/* NEW: View Schematic */}
              <div className="mt-2 flex justify-end">
                <button
                  className="rounded bg-cyan-700 px-3 py-1.5 text-xs text-white hover:bg-cyan-600 disabled:opacity-50"
                  disabled={!selectedBenchId}
                  onClick={async () => {
                    if (!selectedBenchId) return;
                    await openBenchSchematic(selectedBenchId);
                  }}
                  title={!selectedBenchId ? "Select a bench first" : "View bench schematic"}
                >
                  View Schematic
                </button>
              </div>
            </div>

            {/* WF4 only: Select Test Plan Name from saved plans */}

            

            {needsTestPlanName  && (
              <div className="mt-4">
                <div className="text-sm text-zinc-200 mb-1">Test Plan (required)</div>

                <select
                  className="w-full rounded bg-zinc-800 border border-zinc-700 p-2 text-white"
                  value={selectedTestPlanId}
                  onChange={(e) => {
                    const id = e.target.value;
                    setSelectedTestPlanId(id);

                    const picked = validationTestPlans.find((p) => p.id === id);
                    if (picked?.name) {
                      setTestPlanName(picked.name); // this is what backend expects (test_plan_name)
                    }
                  }}
                >
                  <option value="">-- choose a test plan --</option>
                  {validationTestPlans.map((p) => (
                    <option key={p.id} value={p.id}>
                      {p.name}
                    </option>
                  ))}
                </select>

                {/* Optional fallback text input (keep if you want manual entry) */}
                <div className="mt-2">
                  <div className="text-xs text-zinc-400 mb-1">Or type a name (advanced)</div>
                  <input
                    className="w-full rounded border border-zinc-700 bg-black px-2 py-1 text-zinc-100"
                    placeholder="e.g., Baby"
                    value={testPlanName}
                    onChange={(e) => setTestPlanName(e.target.value)}
                  />
                </div>
              </div>
            )}


            <div className="mt-5 flex justify-end gap-2">
              <button className="rounded bg-zinc-800 px-4 py-2 text-sm hover:bg-zinc-700"
                onClick={() => setShowBenchPicker(false)}>
                Cancel
              </button>

              <button className="rounded bg-green-700 px-4 py-2 text-sm hover:bg-green-600"
                onClick={async () => {
                  if (!selectedBenchId) {
                    alert("Select a bench.");
                    return;
                  }
                  if (needsTestPlanName && !testPlanName.trim()) {
                    alert("Enter Test Plan Name (required).");
                    return;
                  }
                  setShowBenchPicker(false);
                  if (!pendingWorkflowPayload) {
                    alert("Missing pending workflow payload. Close and click Run Workflow again.");
                    return;
                  }
                  // For WF-2/WF-3: run preflight/run-validation directly with bench_id
                  await runWorkflowWithFormData(
                    pendingWorkflowPayload,
                    "",
                    undefined,
                    [],                 // instruments not required here
                    null,               // scope_json optional
                    selectedBenchId,      // add as new param
                    testPlanName,
                    previewTestPlan 
                  );
                }}>
                Use selected bench
              </button>
            </div>
          </div>
        </div>
      )}


      {/* ===== Modals ===== */}
      {showSpecModal && (
        <SpecInputModal
          loop={loop}
          configSchema={selectedWorkflowEffectiveConfigSchema}
          runConfig={pendingRunConfig}
          onRunConfigChange={setPendingRunConfig}
          showTestPlanName={selectedWorkflowName === "Validation_Generate_Lab_Handoff"}
          testPlanName={testPlanName}
          setTestPlanName={setTestPlanName}
          onClose={() => setShowSpecModal(false)}
          onSubmit={(text, file) => {
            handleSpecSubmit(text, file);
            setShowSpecModal(false);
            console.log("Spec submitted:", { text, file, testPlanName });
         
          }}
        />
      )}

      {showWorkflowConfigModal && (
        <WorkflowConfigModal
          schema={selectedWorkflowEffectiveConfigSchema}
          defaults={selectedWorkflowEffectiveDefaultConfig}
          suggestedFields={suggestWorkflowInputsFromAgents(nodes)}
          onClose={() => setShowWorkflowConfigModal(false)}
          onSave={saveWorkflowConfigSchema}
        />
      )}

      {/* NEW: Bench Schematic Viewer Modal */}
      {showBenchSchematicModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70">
          <div className="w-[1100px] max-w-[96vw] max-h-[92vh] overflow-auto rounded-xl border border-zinc-700 bg-zinc-900 p-4 shadow-2xl">
            <div className="flex items-center justify-between mb-3">
              <div className="text-cyan-300 font-semibold">Bench Schematic</div>
              <button
                className="text-zinc-300 hover:text-white"
                onClick={() => setShowBenchSchematicModal(false)}
              >
                x
              </button>
            </div>

            {benchSchematicErr && (
              <div className="rounded border border-red-700 bg-red-950/40 p-3 text-red-200 text-sm">
                {benchSchematicErr}
              </div>
            )}

            {!benchSchematicErr && benchSchematicModalLoading && (
              <div className="text-zinc-400 text-sm">Loading schematic...</div>
            )}

            {!benchSchematicErr && !benchSchematicModalLoading && benchSchematicObj && (
              <div className="space-y-3">
                {/* Minimal visual summary first */}
                <div className="rounded-lg border border-zinc-700 bg-black/30 p-3">
                  <div className="text-zinc-200 text-sm">
                    <span className="text-cyan-300 font-semibold">Bench:</span>{" "}
                    {benchSchematicObj?.bench?.name || "Unknown"}{" "}
                    <span className="text-zinc-500">
                      {benchSchematicObj?.bench?.location ? `- ${benchSchematicObj.bench.location}` : ""}
                    </span>
                  </div>
                  <div className="text-zinc-200 text-sm mt-1">
                    <span className="text-cyan-300 font-semibold">DUT:</span>{" "}
                    {benchSchematicObj?.dut?.name || "DUT"}
                  </div>
                </div>

                {/* Raw JSON (always useful for now) */}

                {renderBenchSchematicVisual(benchSchematicObj)}

                <details className="mt-4 rounded-lg border border-zinc-700 bg-black/30 p-3">
                  <summary className="cursor-pointer text-zinc-200 text-sm font-semibold">
                    Raw JSON (debug)
                  </summary>
                  <pre className="mt-3 text-xs text-zinc-200 whitespace-pre-wrap overflow-auto">
                    {JSON.stringify(benchSchematicObj, null, 2)}
                  </pre>
                </details>
              </div>
            )}
          </div>
        </div>
      )}
  
      {showCreateAgentModal && (
        <CreateAgentModal
          onClose={() => setShowCreateAgentModal(false)}
          onSubmit={(backendLabel, uiLabel, desc) => {
            const next = [...customAgents, { uiLabel, backendLabel, desc }];
            setCustomAgents(next);
            localStorage.setItem("custom_agents", JSON.stringify(next));
          }}
        />
      )}

      {showScopeModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60">
          <div className="w-[900px] max-w-[95vw] rounded-lg bg-zinc-900 p-4 border border-zinc-700">
            <div className="flex items-center justify-between">
              <h3 className="text-lg font-semibold text-white">Validation Scope for this Run</h3>
              <button className="text-zinc-300 hover:text-white" onClick={() => setShowScopeModal(false)}>x</button>
            </div>

            <div className="mt-3 grid grid-cols-2 gap-4">
              <div className="border border-zinc-700 rounded p-3">
                <div className="text-sm text-zinc-200 mb-2">Select tests/features to include:</div>
                <div className="max-h-[380px] overflow-auto space-y-2">
                  {(previewTestPlan?.tests || []).map((t: any) => {
                    const name = t?.name;
                    if (!name) return null;
                    const checked = selectedTestNames.includes(name);
                    return (
                      <label key={name} className="flex items-start gap-2 text-zinc-100">
                        <input
                          type="checkbox"
                          checked={checked}
                          onChange={(e) => {
                            const next = e.target.checked
                              ? [...selectedTestNames, name]
                              : selectedTestNames.filter((x) => x !== name);
                            setSelectedTestNames(next);

                            // recompute missing
                            const missing = computeMissingInstrumentTypes(previewTestPlan, next, selectedInstrumentRows);
                            setMissingInstrumentTypes(missing);
                          }}
                        />
                        <div>
                          <div className="font-medium">{name}</div>
                          <div className="text-xs text-zinc-400">{t?.objective || ""}</div>
                          <div className="text-xs text-zinc-500">
                            requires: {(t?.required_instruments || []).join(", ")}
                          </div>
                        </div>
                      </label>
                    );
                  })}
                </div>
              </div>

              <div className="border border-zinc-700 rounded p-3">
                <div className="text-sm text-zinc-200 mb-2">Instrument coverage</div>

                {missingInstrumentTypes.length === 0 ? (
                  <div className="text-green-400 text-sm">Your selected instruments cover this scope.</div>
                ) : (
                  <div className="text-yellow-300 text-sm">
                    Missing instrument types for selected scope: <b>{missingInstrumentTypes.join(", ")}</b>
                    <div className="text-xs text-zinc-400 mt-2">
                      Either (1) deselect tests requiring these instruments, or (2) register/select matching instruments.
                    </div>
                  </div>
                )}

                <div className="mt-4 flex gap-2">
                  <button
                    className="px-3 py-2 rounded bg-zinc-700 text-white hover:bg-zinc-600"
                    onClick={() => {
                    // go back to instrument selection
                      setShowScopeModal(false);
                      setShowInstrumentPicker(true);
                    }}
                  >
                    Change Instruments
                  </button>

                  <button
                    className="ml-auto px-3 py-2 rounded bg-cyan-600 text-white hover:bg-cyan-500"
                    onClick={async () => {
                      if (!pendingWorkflowPayload) {
                        alert("Missing pending workflow payload. Please click Run Workflow again.");
                        return;
                      }
                      if (selectedTestNames.length === 0) {
                        alert("Please select at least one test.");
                        return;
                      }

                      // Build scope payload for Validation Scope Agent
                      const scopePayload = {
                        mode: "by_test_names",
                        include_tests: selectedTestNames,
                      };

                      // Run the workflow uninterrupted with scope_json
                      await runWorkflowWithFormData(
                        pendingWorkflowPayload,
                        pendingSpecText,
                        pendingSpecFile,
                        selectedInstrumentIds,
                        scopePayload,
                        selectedBenchId || undefined,
                        testPlanName,
                        previewTestPlan
                      );

                      // cleanup
                      setShowScopeModal(false);
                      setPreviewTestPlan(null);
                    }}
                  >
                    Run Selected Scope
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}

      
  
      {showPlanner && (
        <PlannerModal
          onClose={() => setShowPlanner(false)}
          onBuildWorkflow={(intent) => {
            setSystemPlannerIntent(intent);
            setShowPlanner(false);
            setShowAgentPlanner(true);
          }}
        />
      )}
      {showAgentPlanner && (
        <AgentPlannerModal
          initialDesignIntent={systemPlannerIntent}
          onClose={() => {
            setShowAgentPlanner(false);
            setSystemPlannerIntent(null);
          }}
        />
      )}
      {showStudioAgentPlanner && (
        <StudioAgentPlannerModal
          initialLoop={loop}
          onClose={() => setShowStudioAgentPlanner(false)}
        />
      )}
      {showCreateApp && (
        <CreateAppModal
          workflowId={selectedWorkflowId}
          workflowName={selectedWorkflowName}
          loopType={(selectedWorkflowLoopType || loop).toLowerCase()}
          configSchema={selectedWorkflowEffectiveConfigSchema}
          defaultConfig={selectedWorkflowEffectiveDefaultConfig}
          workflowSnapshot={{
            id: selectedWorkflowId,
            name: selectedWorkflowName,
            loop_type: selectedWorkflowLoopType || loop,
            definitions: {
              ...(selectedWorkflowDefinitions || { nodes, edges }),
              workflow_config_schema: selectedWorkflowEffectiveConfigSchema,
              default_run_config: selectedWorkflowEffectiveDefaultConfig,
            },
          }}
          authHeaders={authHeaders}
          onConfigureWorkflow={() => {
            if (!selectedWorkflowId) {
              alert("Select or save a workflow before configuring settings.");
              return;
            }
            setShowCreateApp(false);
            setShowWorkflowConfigModal(true);
          }}
          onClose={() => setShowCreateApp(false)}
        />
      )}
      {showDagPreview && (
        <DagPreviewModal
          loopType={loop}
          nodes={nodes}
          edges={edges}
          savedWorkflows={composerWorkflows}
          selectedWorkflowName={selectedWorkflowName}
          onOpenComposedWorkflow={(workflow) => {
            setNodes(workflow.nodes as Node<AgentNodeData>[]);
            setEdges(workflow.edges);
            if (workflow.loopType) setLoop(normalizeLoopType(workflow.loopType));
            if (workflow.name) setSelectedWorkflowName(workflow.name);
            setTimeout(() => fitView({ padding: 0.2 }), 50);
          }}
          onClose={() => setShowDagPreview(false)}
        />
      )}
    </main>
  );
  
  
}

/* =========================
   Modals
========================= */
function WorkflowConfigModal({
  schema,
  defaults,
  suggestedFields,
  onClose,
  onSave,
}: {
  schema: WorkflowConfigSchema;
  defaults: Record<string, string | number | boolean>;
  suggestedFields: WorkflowConfigField[];
  onClose: () => void;
  onSave: (schema: WorkflowConfigSchema, defaults: Record<string, string | number | boolean>) => void;
}) {
  const initialFields = normalizeWorkflowConfigSchema(schema).fields || [];
  const [fields, setFields] = useState<WorkflowConfigField[]>(
    initialFields,
  );
  const [defaultValues, setDefaultValues] = useState<Record<string, string | number | boolean>>(
    buildConfigDefaults({ version: 1, fields }, defaults),
  );

  const updateField = (index: number, patch: Partial<WorkflowConfigField>) => {
    setFields((current) => {
      const next = current.map((field, idx) => (idx === index ? { ...field, ...patch } : field));
      setDefaultValues((values) => buildConfigDefaults({ version: 1, fields: next }, values));
      return next;
    });
  };

  const addField = () => {
    setFields((current) => [
      ...current,
      { key: `setting_${current.length + 1}`, label: `Setting ${current.length + 1}`, type: "text", default: "", required: false, options: [] },
    ]);
  };

  const addAdvancedOverride = () => {
    setFields((current) => [
      ...current,
      {
        key: `advanced_control_${current.length + 1}`,
        label: `Advanced control ${current.length + 1}`,
        type: "text",
        default: "",
        required: false,
        options: [],
      },
    ]);
  };

  const applySuggestedInputs = () => {
    setFields((current) => {
      const next = mergeWorkflowConfigFields(current, suggestedFields);
      setDefaultValues((values) => buildConfigDefaults({ version: 1, fields: next }, values));
      return next;
    });
  };

  const removeField = (index: number) => {
    setFields((current) => {
      const next = current.filter((_, idx) => idx !== index);
      setDefaultValues((values) => buildConfigDefaults({ version: 1, fields: next }, values));
      return next;
    });
  };

  const save = () => {
    const normalized = normalizeWorkflowConfigSchema({ version: 1, fields });
    const seen = new Set<string>();
    for (const field of normalized.fields || []) {
      if (seen.has(field.key)) {
        alert(`Duplicate setting key: ${field.key}`);
        return;
      }
      seen.add(field.key);
    }
    onSave(normalized, buildConfigDefaults(normalized, defaultValues));
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70">
      <div className="max-h-[92vh] w-[920px] max-w-[96vw] overflow-y-auto rounded-2xl border border-slate-800 bg-slate-900 p-6 text-slate-100 shadow-2xl scrollbar-thin scrollbar-thumb-slate-700 scrollbar-track-transparent">
        <div className="flex items-start justify-between gap-4">
          <div>
            <h2 className="text-2xl font-bold text-white">Configure Workflow Settings</h2>
            <p className="mt-1 text-sm leading-6 text-slate-400">
              Define the real input contract for this workflow. These fields appear in Product configuration when the workflow is packaged as an app.
            </p>
            <p className="mt-2 text-xs leading-5 text-slate-500">
              Suggestions focus on user-facing setup values and meaningful run controls. Agent-to-agent handoff artifacts are skipped by default. Expose downstream controls only when they materially affect the run, such as synthesis loop count, simulator choice, seed count, effort, or stop-on-failure policy.
            </p>
          </div>
          <button onClick={onClose} className="rounded-lg border border-slate-700 px-3 py-2 text-sm text-slate-200 hover:bg-slate-800">
            Close
          </button>
        </div>

        <div className="mt-5 grid gap-3">
          {suggestedFields.length ? (
            <div className="rounded-lg border border-cyan-500/20 bg-cyan-950/20 p-4">
              <div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
                <div>
                  <div className="text-xs font-semibold uppercase text-cyan-300">Suggested Inputs</div>
                  <p className="mt-1 text-sm leading-6 text-slate-300">
                    Review these before saving. Examples include spec text, target frequency, simulator, toolchain, synthesis loop count, seed count, and stop-on-failure controls when they should be user-configurable.
                  </p>
                </div>
                <button
                  type="button"
                  onClick={applySuggestedInputs}
                  className="rounded-lg border border-cyan-600 px-3 py-2 text-sm font-semibold text-slate-100 hover:bg-cyan-950/40"
                >
                  Suggest Inputs from Agents
                </button>
              </div>
              <div className="mt-3 flex flex-wrap gap-2">
                {suggestedFields.slice(0, 8).map((field) => (
                  <span key={field.key} className="rounded border border-slate-700 bg-slate-950/70 px-2 py-1 text-xs text-slate-300">
                    {field.label}
                  </span>
                ))}
              </div>
            </div>
          ) : null}
          {!fields.length ? (
            <div className="rounded-lg border border-slate-800 bg-slate-950/60 p-4 text-sm leading-6 text-slate-400">
              No workflow inputs are saved yet. Use Suggest Inputs from Agents when available, or add the values a user must provide or tune. Internal handoff artifacts should stay hidden by default. Add downstream controls only when they make sense for the app, such as synthesis iterations, simulator, seed count, effort, or stop-on-failure behavior.
            </div>
          ) : null}
          {fields.map((field, index) => {
            const currentDefault = defaultValues[field.key] ?? field.default ?? (field.type === "boolean" ? false : "");
            return (
              <div key={`${field.key}-${index}`} className="rounded-lg border border-slate-800 bg-slate-950/60 p-4">
                <div className="grid gap-3 md:grid-cols-[1fr_1fr_150px]">
                  <label className="grid gap-1">
                    <span className="text-xs font-semibold uppercase text-slate-400">Key</span>
                    <input
                      value={field.key}
                      onChange={(event) => updateField(index, { key: event.target.value.replace(/\s+/g, "_") })}
                      className="rounded-lg border border-slate-700 bg-slate-950 px-3 py-2 text-sm text-white outline-none focus:border-cyan-400"
                    />
                  </label>
                  <label className="grid gap-1">
                    <span className="text-xs font-semibold uppercase text-slate-400">Label</span>
                    <input
                      value={field.label}
                      onChange={(event) => updateField(index, { label: event.target.value })}
                      className="rounded-lg border border-slate-700 bg-slate-950 px-3 py-2 text-sm text-white outline-none focus:border-cyan-400"
                    />
                  </label>
                  <label className="grid gap-1">
                    <span className="text-xs font-semibold uppercase text-slate-400">Type</span>
                    <select
                      value={field.type}
                      onChange={(event) => updateField(index, { type: event.target.value as WorkflowConfigField["type"] })}
                      className="rounded-lg border border-slate-700 bg-slate-950 px-3 py-2 text-sm text-white outline-none focus:border-cyan-400"
                    >
                      <option value="text">text</option>
                      <option value="textarea">textarea</option>
                      <option value="number">number</option>
                      <option value="boolean">boolean</option>
                      <option value="select">select</option>
                    </select>
                  </label>
                </div>
                <div className="mt-3 grid gap-3 md:grid-cols-[1fr_1fr_auto]">
                  <label className="grid gap-1">
                    <span className="text-xs font-semibold uppercase text-slate-400">Default</span>
                    {field.type === "boolean" ? (
                      <div className="flex h-10 items-center rounded-lg border border-slate-700 bg-slate-950 px-3">
                        <input
                          type="checkbox"
                          checked={Boolean(currentDefault)}
                          onChange={(event) => setDefaultValues((current) => ({ ...current, [field.key]: event.target.checked }))}
                          className="h-4 w-4 accent-cyan-500"
                        />
                      </div>
                    ) : (
                      <input
                        type={field.type === "number" ? "number" : "text"}
                        value={String(currentDefault)}
                        onChange={(event) => setDefaultValues((current) => ({ ...current, [field.key]: coerceConfigValue(field, event.target.value) }))}
                        className="rounded-lg border border-slate-700 bg-slate-950 px-3 py-2 text-sm text-white outline-none focus:border-cyan-400"
                      />
                    )}
                  </label>
                  <label className="grid gap-1">
                    <span className="text-xs font-semibold uppercase text-slate-400">Select Options</span>
                    <input
                      value={(field.options || []).map((option) => (typeof option === "string" ? option : option.value)).join(", ")}
                      onChange={(event) => updateField(index, { options: event.target.value.split(",").map((item) => item.trim()).filter(Boolean) })}
                      placeholder="verilator, icarus"
                      disabled={field.type !== "select"}
                      className="rounded-lg border border-slate-700 bg-slate-950 px-3 py-2 text-sm text-white outline-none focus:border-cyan-400 disabled:cursor-not-allowed disabled:opacity-40"
                    />
                  </label>
                  <div className="flex items-end gap-3">
                    <label className="flex h-10 items-center gap-2 rounded-lg border border-slate-700 bg-slate-950 px-3 text-sm text-slate-200">
                      <input
                        type="checkbox"
                        checked={Boolean(field.required)}
                        onChange={(event) => updateField(index, { required: event.target.checked })}
                        className="h-4 w-4 accent-cyan-500"
                      />
                      Required
                    </label>
                    <button
                      onClick={() => removeField(index)}
                      className="h-10 rounded-lg border border-red-500/50 px-3 text-sm font-semibold text-red-200 hover:bg-red-950/40"
                    >
                      Remove
                    </button>
                  </div>
                </div>
              </div>
            );
          })}
        </div>

        <div className="mt-5 flex justify-between gap-3">
          <div className="flex flex-wrap gap-3">
            <button onClick={addField} className="rounded-lg border border-slate-700 px-4 py-2 text-sm font-semibold text-slate-200 hover:bg-slate-800">
              Add Setting
            </button>
            <button onClick={addAdvancedOverride} className="rounded-lg border border-slate-700 px-4 py-2 text-sm font-semibold text-slate-200 hover:bg-slate-800">
              Add Advanced Control
            </button>
          </div>
          <div className="flex gap-3">
            <button onClick={onClose} className="rounded-lg border border-slate-700 px-4 py-2 text-sm font-semibold text-slate-200 hover:bg-slate-800">
              Cancel
            </button>
            <button onClick={save} className="rounded-lg bg-cyan-500 px-5 py-2 text-sm font-bold text-black hover:bg-cyan-400">
              Save Settings
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

function SpecInputModal({
  loop,
  onClose,
  onSubmit,
  configSchema,
  runConfig,
  onRunConfigChange,
  showTestPlanName,
  testPlanName,
  setTestPlanName,
}: {
  loop: string;
  onClose: () => void;
  onSubmit: (text: string, file?: File) => void;
  configSchema?: WorkflowConfigSchema;
  runConfig?: Record<string, string | number | boolean>;
  onRunConfigChange?: (next: Record<string, string | number | boolean>) => void;
  showTestPlanName?: boolean;
  testPlanName?: string;
  setTestPlanName?: (v: string) => void;
}) {
  const [text, setText] = useState("");
  const [file, setFile] = useState<File | null>(null);
  const normalizedSchema = normalizeWorkflowConfigSchema(configSchema);
  const fields = normalizedSchema.fields || [];

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70">
      <div className="max-h-[92vh] w-full max-w-2xl overflow-y-auto rounded-2xl bg-slate-900 p-6 text-slate-100 shadow-2xl scrollbar-thin scrollbar-thumb-slate-700 scrollbar-track-transparent">
      <h2 className="mb-4 text-2xl font-bold text-white">Enter Spec for {loop.charAt(0).toUpperCase() + loop.slice(1)} Loop</h2>
        {showTestPlanName && (
          <div className="mb-4">
            <label className="mb-2 block text-sm font-medium text-slate-200">
             Test Plan Name (saved)
            </label>
            <input
              className="w-full rounded-lg border border-slate-600 bg-slate-800 p-3 text-slate-100 outline-none focus:ring-2 focus:ring-cyan-500"
              placeholder="e.g., PMIC_Bringup_v1 / PCIe_Smoke_TP"
              value={testPlanName || ""}
              onChange={(e) => setTestPlanName?.(e.target.value)}
            />
            <div className="mt-1 text-xs text-slate-400">
              This name will be stored with the generated test_plan_id in Supabase.
            </div>
          </div>
        )}
        <textarea
          className="mb-4 h-40 w-full rounded-lg border border-slate-600 bg-slate-800 p-4 text-lg outline-none focus:ring-2 focus:ring-cyan-500"
          placeholder={
              loop === "digital"
              ? "Describe the digital module (I/Os, behavior)"
              : loop === "analog"
              ? "Describe the analog circuit (R, C, gain, etc.)"
              : loop === "embedded"
              ? "Describe MCU logic and IO behavior"
              : "Describe System (integrated digital + firmware+Analog) behavior"
          }
          value={text}
          onChange={(e) => setText(e.target.value)}
        />
        <div className="mb-4">
          <GitHubImportPanel
            compact
            onImport={(importedText) => {
              setText((current) => [current.trim(), importedText.trim()].filter(Boolean).join("\n\n"));
            }}
          />
        </div>
        <div className="mb-4">
          <label className="mb-2 block text-sm font-medium">Upload Spec Document</label>
          <label htmlFor="file-upload" className="flex w-full cursor-pointer items-center justify-center rounded-lg border-2 border-dashed border-slate-600 bg-slate-800 px-4 py-6 hover:bg-slate-700">
            <svg xmlns="http://www.w3.org/2000/svg" className="mr-2 h-6 w-6 text-cyan-400" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M4 16v1a2 2 0 002 2h12a2 2 0 002-2v-1M12 12V4m0 8l-3-3m3 3l3-3" />
            </svg>
            <span className="text-slate-300">Click to upload</span>
            <input id="file-upload" type="file" accept=".txt,md,pdf" className="hidden" onChange={(e) => setFile(e.target.files?.[0] || null)} />
          </label>
          {file && <p className="mt-2 text-sm text-green-400">{file.name} selected</p>}
        </div>
        {fields.length > 0 ? (
          <div className="mb-4 rounded-lg border border-slate-700 bg-slate-950/50 p-4">
            <h3 className="text-sm font-semibold text-cyan-300">Workflow Settings</h3>
            <div className="mt-3 grid gap-3">
              {fields.map((field) => {
                const current = runConfig?.[field.key] ?? field.default ?? (field.type === "boolean" ? false : "");
                const update = (value: string | number | boolean) => {
                  const next = {
                    ...(runConfig || {}),
                    [field.key]: coerceConfigValue(field, value),
                  };
                  onRunConfigChange?.(next);
                };
                if (field.type === "boolean") {
                  return (
                    <label key={field.key} className="flex items-center justify-between gap-3 rounded-lg border border-slate-800 bg-slate-900/60 px-3 py-2">
                      <span className="text-sm text-slate-200">{field.label}</span>
                      <input
                        type="checkbox"
                        checked={Boolean(current)}
                        onChange={(event) => update(event.target.checked)}
                        className="h-4 w-4 accent-cyan-500"
                      />
                    </label>
                  );
                }
                return (
                  <label key={field.key} className="grid gap-2">
                    <span className="text-sm font-medium text-slate-200">
                      {field.label}{field.required ? " *" : ""}
                    </span>
                    {field.type === "select" ? (
                      <select
                        value={String(current)}
                        onChange={(event) => update(event.target.value)}
                        className="rounded-lg border border-slate-700 bg-slate-950 px-3 py-2 text-sm text-white outline-none focus:border-cyan-400"
                      >
                        {(field.options || []).map((option) => {
                          const value = typeof option === "string" ? option : option.value;
                          const label = typeof option === "string" ? option : option.label || option.value;
                          const disabled = typeof option === "string" ? false : Boolean(option.disabled);
                          return <option key={value} value={value} disabled={disabled}>{label}</option>;
                        })}
                      </select>
                    ) : field.type === "textarea" ? (
                      <textarea
                        value={String(current)}
                        onChange={(event) => update(event.target.value)}
                        rows={3}
                        className="rounded-lg border border-slate-700 bg-slate-950 px-3 py-2 text-sm text-white outline-none focus:border-cyan-400"
                      />
                    ) : (
                      <input
                        type={field.type === "number" ? "number" : "text"}
                        value={String(current)}
                        onChange={(event) => update(event.target.value)}
                        className="rounded-lg border border-slate-700 bg-slate-950 px-3 py-2 text-sm text-white outline-none focus:border-cyan-400"
                      />
                    )}
                  </label>
                );
              })}
            </div>
          </div>
        ) : null}
        <div className="flex justify-end space-x-3">
          <button onClick={onClose} className="rounded-lg bg-slate-700 px-4 py-2 hover:bg-slate-600">Cancel</button>
          <button
            onClick={() => { onSubmit(text, file || undefined); onClose(); }}
            className="rounded-lg bg-cyan-500 px-6 py-2 font-bold text-black hover:bg-cyan-400"
          >
            Run Spec Agent
          </button>
        </div>
      </div>
    </div>
  );
}

function CreateAgentModal({ onClose, onSubmit }: { onClose: () => void; onSubmit: (backendLabel: string, uiLabel: string, desc: string) => void }) {
