"use client";

import React, { useState,useEffect } from "react";
import { useVoiceAnalyzer } from "@/hooks/useVoiceAnalyzer";
import MissingAgentNamingDialog from "./MissingAgentNamingDialog";
import MissingAgentsResolverModal from "@/components/studio/MissingAgentsResolverModal";
import SpecTextBox from "@/components/SpecTextBox";
import { createClientComponentClient } from "@/lib/platformClient";
const supabase = createClientComponentClient();
import WorkflowConsole from "@/app/workflow/WorkflowConsole";
import { getStableUserId } from "@/utils/userId";

type PreplanResult = {
  loop_type?: string;
  agents?: string[];
  missing_agents?: string[];
};

type InitialDesignIntent = {
  id?: string;
  refined_prompt?: string;
  full_intent?: {
    refined_prompt?: string;
  };
};


function autoLayoutHorizontal(nodes, spacing = 350, startX = 100, startY = 200) {
  return nodes.map((node, index) => ({
    ...node,
    position: { x: startX + index * spacing, y: startY },
  }));
}


function getValueFromSpec(obj, path) {
  try {
    return path
      .replace(/\]/g, "")
      .split(/\.|\[/)
      .reduce((o, k) => (o ? o[k] : undefined), obj);
  } catch {
    return undefined;
  }
}


export default function AgentPlannerModal({
  onClose,
  initialDesignIntent,
}: {
  onClose: () => void;
  initialDesignIntent?: InitialDesignIntent | null;
}) {
  const [goal, setGoal] = useState("");
  const [agent, setAgent] = useState<any>(null);
  const [backendSource, setBackendSource] = useState("");
  const [loading, setLoading] = useState(false);
  const [isRecording, setIsRecording] = useState(false);
  const [mediaRecorder, setMediaRecorder] = useState<MediaRecorder | null>(null);
  const [summary, setSummary] = useState<any>(null);
  const [coverage, setCoverage] = useState(0);
  const [isSelectingAgents, setIsSelectingAgents] = useState(false);
  const [selectedAgents, setSelectedAgents] = useState<string[]>([]);
  const [missingAgents, setMissingAgents] = useState<string[]>([]);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isGeneratingAgent, setIsGeneratingAgent] = useState(false);
  const [spec, setSpec] = useState<any>(null);
  const [missingFields, setMissingFields] = useState([]);
  const [readyForPlanning, setReadyForPlanning] = useState(false);
  const [fieldEdits, setFieldEdits] = useState({});
  const [improvedSpec, setImprovedSpec] = useState<string | null>(null);
  const [finalizedSpec, setFinalizedSpec] = useState<string | null>(null);
  const [result, setResult] = useState<any>(null);
  const [missingFieldEdits, setMissingFieldEdits] = useState({});
  const [preplan, setPreplan] = useState<PreplanResult | null>(null);
  const [stage, setStage] = useState<"initial" | "analyzed" | "autofill" | "finalized" | "workflow">("initial");
  const [showNamingDialog, setShowNamingDialog] = useState(false);
  const [showMissingResolver, setShowMissingResolver] = useState(false);
  const [namingTargets, setNamingTargets] = useState<string[]>([]);
  // ADD this new state near your other state declarations:
  const [workflowGraph, setWorkflowGraph] = useState<any | null>(null);
  const [finalAgents, setFinalAgents] = useState<string[]>([]);
  const [recentlyGenerated, setRecentlyGenerated] = useState<string[]>([]);

  const [savedIntents, setSavedIntents] = useState<any[]>([]);
  const [selectedIntentId, setSelectedIntentId] = useState<string>("");
  const [activePlannerTab, setActivePlannerTab] = useState<"describe" | "plan" | "agents" | "build">("describe");


  const [voiceSummary, setVoiceSummary] = useState<string | null>(null);

  useEffect(() => {
    if (!initialDesignIntent) return;
    const intentText =
      initialDesignIntent.refined_prompt ||
      initialDesignIntent.full_intent?.refined_prompt ||
      "";
    setSelectedIntentId(initialDesignIntent.id || "");
    setGoal(intentText);
    setFinalizedSpec(null);
    setImprovedSpec(null);
    setSpec(null);
    setStage("initial");
    setActivePlannerTab("describe");
  }, [initialDesignIntent]);



  
  const handlePublish = () => {
    console.log("⚠️ Publish is not implemented yet. Coming in Step 7.");
  };
  function normalizeMissing(input) {
    return (input || []).map(m =>
      typeof m === "string"
        ? m                     // ✅ keep raw strings as strings
        : m                     // ✅ keep dict objects untouched
    );
  }
 // function normalizeMissing(input) {
  //  return (input || []).map(m =>
  //    typeof m === "string" ? { path: m, ask: "", type: "text" } : m
 //   );
 // }
    async function startStopRecording() {
    if (isRecording && mediaRecorder) {
      mediaRecorder.stop();
      setIsRecording(false);
      return;
    }

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const rec = new MediaRecorder(stream);
      const chunks: BlobPart[] = [];

      rec.ondataavailable = (e) => chunks.push(e.data);

      rec.onstop = async () => {
        const blob = new Blob(chunks, { type: "audio/webm" });
        const formData = new FormData();
        formData.append("file", blob);

        try {
          // 1) Send audio → backend (append to Notion)
          await fetch("/api/voice_stream", {
            method: "POST",
            body: formData,
          });

          // 2) Ask backend to summarize Notion into a spec-style summary
          const sumRes = await fetch("/api/summarize_notion", {
            method: "POST",
          });

          const sumJson = await sumRes.json();
          // backend usually returns { summary: "<text or json>" }
          const raw = sumJson.summary ?? sumJson.result ?? "";

          console.log("🎧 Notion voice summary (raw):", raw);

          const summaryText =
            typeof raw === "string" ? raw : JSON.stringify(raw, null, 2);

          // 3) Use this as the current goal + voice summary
          setVoiceSummary(summaryText);
          setGoal(summaryText);
          setBackendSource("Voice → Notion summary");

          // 4) Reset spec state so Analyze Spec runs cleanly on this new text
          setSpec(null);
          setMissingFields([]);
          setCoverage(0);
          setStage("initial");
          setReadyForPlanning(false);
        } catch (err) {
          console.error("❌ Voice → Notion pipeline failed", err);
        }
      };

      rec.start();
      setMediaRecorder(rec);
      setIsRecording(true);
    } catch (err) {
      console.error("🎙️ Voice recording failed:", err);
    }
  }


  useEffect(() => {
    const handler = (e: any) => {
      const agentName = e.detail;
      fetch(`/api/agents/get_code?agent=${agentName}`)
        .then(r => r.text())
        .then(code => {
          setSelectedAgent(agentName);
          setAgentCode(code);
          setOpen(true);
        });
    };
    window.addEventListener("editAgent", handler);
    return () => window.removeEventListener("editAgent", handler);
  }, []);

  useEffect(() => {
    async function loadDesignIntentsForSystemPlanner() {
      try {
        const stableId = await getStableUserId(supabase);
        const { data, error } = await supabase
          .from("design_intent_drafts")
          .select("*")
          .eq("user_id", stableId)
          .order("created_at", { ascending: false });

        if (error) {
          console.error(
            "❌ Failed to load design intents for System Planner:",
            error.message
          );
          return;
        }

        setSavedIntents(data || []);
      } catch (err) {
        console.error("❌ Unexpected error loading design intents:", err);
      }
    }

    loadDesignIntentsForSystemPlanner();
  }, []);

  // --- Generate Agent Plan ---

  const handleAnalyzeSpec = async () => {
    setIsAnalyzing(true);
    try {

      const payload = voiceSummary
      ? { voice_summary: voiceSummary, user_id: "anonymous" }
      : { goal, user_id: "anonymous" };

      const res = await fetch("/api/analyze_spec", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });
      
  
      const data = await res.json();
      console.log("DEBUG ANALYZE SPEC RESPONSE:", data);
  
      const result = data?.result ?? data;
      setResult(result);



      if (result.structured_spec_final) {
        setSpec(result.structured_spec_final);
        setCoverage(result.coverage ?? result.coverage?.total_score ?? 0);
        setMissingFields([]);
        setReadyForPlanning(true);
        setResult(null);
        setActivePlannerTab("agents");
        return;
      } else if (result.structured_spec_draft) {
        setSpec(result.structured_spec_draft);
        setCoverage(result.coverage ?? result.coverage?.total_score ?? 0);
        const missingList = normalizeMissing(result.missing ?? []);
        
        setMissingFields(missingList);

        setReadyForPlanning(false);
        setActivePlannerTab("plan");
        return;
      }

    } catch (err) {
      console.error(err);
      alert("❌ Analyze Spec failed");
    } finally {
      setIsAnalyzing(false);
      setStage("analyzed");
    }

  };
  const handleSelectAgents = async () => {
    if (!goal.trim()) return;
    setIsSelectingAgents(true);
    

  
    try {

      const { data: { session } } = await supabase.auth.getSession();
      const user_id = session?.user?.id || "anonymous";

      const res = await fetch("/api/plan_workflow", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(
          spec
            ? { prompt: goal, structured_spec_final: spec,user_id } // now spec is not null 🎯
            : { prompt: goal,user_id }
        ),
      });
  
      const data = await res.json();
      const plan = data.plan || {};

      
  
      setPreplan(plan);
  
      setSelectedAgents(plan.agents ?? []);
      setMissingAgents(plan.missing_agents ?? []);
      setActivePlannerTab(plan.missing_agents?.length ? "agents" : "build");

      console.log("🧭 PREPLAN (from Select Agents):", JSON.stringify(plan, null, 2));
      console.log("🔗 Ordered agent list:", plan.agents);
      console.log("❓ Missing agents detected:", plan.missing_agents);
    

    
        // ✅ No missing → This is the final agent set
      setFinalAgents(plan.agents ?? []);
      setRecentlyGenerated([]); // none generated yet
      
  
    } catch (err) {
      console.error(err);
      alert("❌ Select Agents failed");
    }
    
    setIsSelectingAgents(false);
  };
  
  const handleGenerateMissingAgents = async () => {
    try {
      // Case 1: User did NOT run Select Agents yet → compute missing agents automatically
      if ((!preplan || !preplan.missing_agents || preplan.missing_agents.length === 0) && spec) {
        const res = await fetch("/api/plan_workflow", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            prompt: goal,
            structured_spec_final: spec,
          }),
        });
  
        const data = await res.json();
        const newPlan = data.plan || data;
  
        setPreplan(newPlan);
        setMissingAgents(newPlan.missing_agents || []);
  
        // 👇 Open naming dialog with missing agents
        setNamingTargets(newPlan.missing_agents || []);
        setShowMissingResolver(true);
        setActivePlannerTab("agents");
        return;
      }
  
      // Case 2: User already ran Select Agents → just open naming dialog
      setNamingTargets(missingAgents);
      setShowMissingResolver(true);
      setActivePlannerTab("agents");

      window.dispatchEvent(new Event("refreshAgents"));

  
    } catch (err) {
      console.error("❌ Setup for Generate Missing Agents failed:", err);
      alert("❌ Could not determine missing agents.");
    }
  };
  
  


  const handleFinalizeSpec = async () => {
    if (!goal.trim()) return;
  
    setIsAnalyzing(true);
    try {
      const res = await fetch("/api/finalize_spec_natural_sentences", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          original_text: goal,
          improved_text: improvedSpec,
          structured_spec_draft: JSON.parse(JSON.stringify(spec)),
          edited_values: {...missingFieldEdits},
          missing: JSON.parse(JSON.stringify(missingFields)),
          user_id: null,
        }),
      });
  
      const data = await res.json();

      console.group("🧪 FINALIZE PAYLOAD");
      console.log("spec?", spec && Object.keys(spec || {}).length, spec);
      console.log("missingFields:", missingFields);
      console.log("edited_values:", missingFieldEdits);
      console.log("improvedSpec?", !!improvedSpec);
      console.groupEnd();
  
      // ✅ Store natural language final spec
      setFinalizedSpec(data.final_text);
      setGoal(data.final_text);
  
      // ✅ Store machine spec
      setSpec(data.structured_spec_final);


      /* ✅ Normalize & update missing list correctly */
      const remaining = normalizeMissing(data.remaining_missing ?? []);
      setMissingFields(remaining);
  
      // ✅ Extract correct coverage

      const cov = data.coverage ?? data.coverage_final ?? 0;
      setCoverage(typeof cov === "object" ? (cov.total_score ?? 0) : cov);
  
  
      // ✅ ★ KEY FIX ★ Stop UI returning to auto-fill panel
      setResult(null);
      // setMissingFields([]);
      setMissingFieldEdits({});
      setImprovedSpec(null);
  
      // ✅ Enable Select Agents
      //setReadyForPlanning(true);
      setReadyForPlanning(remaining.length === 0);
      setActivePlannerTab(remaining.length === 0 ? "agents" : "plan");
  
    } catch (err) {
      console.error("❌ Finalize Spec failed:", err);
    }
    setIsAnalyzing(false);
    setStage("finalized");
  };
  const handleAutoFillMissingFields = async () => {
    if (!spec) return;
  
    setIsAnalyzing(true);
    try {
      const res = await fetch("/api/auto_fill_missing_fields", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          structured_spec_draft: spec,
          missing: missingFields,
          original_text: goal,   
        })
      }).then(r => r.json());

  
      // ✅ Natural language preview text (just preview, do NOT overwrite goal)
      setImprovedSpec(res.improved_text ?? null);
  
      // ✅ Structured spec from backend (if inferred)
      if (res.structured_spec_enhanced) setSpec(res.structured_spec_enhanced);
  
      // ✅ SAFELY extract missing fields (works whether objects OR strings)
      const remaining = normalizeMissing(res.remaining_missing_fields ?? missingFields);
      setMissingFields(remaining);

      const autoVals = res.auto_filled_values ?? {};

      function resolveAutoValue(path: string, autoVals: any) {
        const leaf = path.split(".").pop().replace(/\[\d+\]/g, "");
        return (
          autoVals[path] ??
          autoVals[leaf] ??
          autoVals[leaf.toLowerCase()] ??
          ""
        );
      }
      
      setMissingFieldEdits(
        Object.fromEntries(
          remaining.map((m: any) => [m.path, resolveAutoValue(m.path, autoVals)])
        )
      );
      
      // ✅ Switch UI to edit panel
      setStage("autofill");
      setActivePlannerTab("plan");

  
    } catch (err) {
      console.error("❌ Auto-fill failed:", err);
    } finally {
      setIsAnalyzing(false);
    }
  };
  
    // NEW: Build Workflow (Step 3)
  const handleBuildWorkflow = async () => {
    try {
      // Ensure we have a user_id (your Select step already uses Supabase)
      const { data: { session } } = await supabase.auth.getSession();
      const user_id = session?.user?.id || "anonymous";

      if (!finalAgents || finalAgents.length === 0) {
        alert("Please run Select Agents first (or add at least one agent).");
        return;
      }

      console.log("🧾 Before PREPLAN snapshot at Build:", preplan);
      console.log("✅ Before FINAL AGENTS (frontend):", finalAgents);


      const res = await fetch("/api/build_workflow", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          user_id,
          final_agents : finalAgents, // ← reuse from Step 2
          preplan : preplan,
        }),
      });

      console.log("🚀 FINAL AGENTS SENT TO BACKEND:", preplan?.agents);
      console.log("🧾 After PREPLAN snapshot at Build:", preplan);
      console.log("✅ After FINAL AGENTS (frontend):", finalAgents);


      if (!res.ok) {
        const msg = await res.text();
        throw new Error(msg || "Build workflow failed.");
      }

      const data = await res.json();
      // Expecting { workflow: { nodes: [...], edges: [...], ... } }

      const laidOutNodes = autoLayoutHorizontal(data.workflow.nodes);

      const builtWorkflow = {
       ...data.workflow,
       nodes: laidOutNodes,
       edges: data.workflow.edges,
      };

// ✅ SEND WORKFLOW TO CANVAS
      setWorkflowGraph(builtWorkflow);
      setStage("workflow");
      setActivePlannerTab("build");
      try {
        const workflowName = prompt(
          "💾 Enter a name to save this workflow:",
          `AI_Composed_${new Date().toISOString().slice(0, 10)}`
        );
        const loopType = preplan?.loop_type || "system";
        if (workflowName) {
          await fetch("/api/save_custom_workflow", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              workflow: {
                workflow_name: workflowName.trim(),              // ✅ matches working format
                loop_type: loopType.toLowerCase(),               // ✅ matches sidebar categories
                nodes: builtWorkflow.nodes,                      // ✅ do NOT send definitions wrapper
                edges: builtWorkflow.edges,
                summary: `Auto-composed workflow for ${workflowName}`, 
              },
              user_id: user_id && user_id !== "anonymous"
                ? user_id
                : localStorage.getItem("anon_user_id") || "anonymous",  // ✅ matches working workflow planner
            }),
          });
   
          window.dispatchEvent(new Event("refreshWorkflows")); // ✅ Refresh sidebar
        }
      } catch (err) {
        console.error("❌ Save workflow failed", err);
      }
    } catch (err) {
      console.error("❌ Build Workflow failed:", err);
      alert(`❌ Build Workflow failed: ${String(err)}`);
    }
  };
  useEffect(() => {

    const ws = new WebSocket("/spec_live_feedback");

    // const WS_URL =
    //  process.env.NEXT_PUBLIC_WS_URL ||
    //  "wss://209.38.74.151/spec_live_feedback";

    //console.log("🔌 Connecting to WebSocket:", WS_URL);
    //const ws = new WebSocket(WS_URL);

  
    ws.onmessage = (event) => {
      try {
        const data = JSON.parse(event.data);

        if (data.summary) {
          setSummary(data.summary);
        }

        if (data.coverage !== undefined && data.coverage !== null) {
          // coverage can be a number or an object with total_score
          const cov =
            typeof data.coverage === "object"
              ? data.coverage.total_score ?? 0
              : data.coverage;
          setCoverage(cov);
        } else if (data.result?.coverage !== undefined) {
          const cov =
            typeof data.result.coverage === "object"
              ? data.result.coverage.total_score ?? 0
              : data.result.coverage;
          setCoverage(cov);
        }
      } catch (err) {
        console.error("⚠️ Error parsing WebSocket data", err);
      }
    };

  
    ws.onclose = () => console.log("🔌 WebSocket closed");
    ws.onerror = (err) => console.error("⚠️ WS Error:", err);
  
    return () => ws.close();
  }, []);

  useEffect(() => {
    if (stage === "workflow" && workflowGraph) {
      console.log("📡 Dispatching workflow graph to canvas:", workflowGraph);
      window.dispatchEvent(
        new CustomEvent("loadWorkflowGraph", { detail: workflowGraph })
      );
      onClose(); // ✅ Close the System Planner modal when done
    }
  }, [stage, workflowGraph, onClose]);

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 p-4">
      <div className="relative flex h-[calc(100vh-2rem)] max-h-[920px] w-full max-w-6xl flex-col overflow-hidden rounded-2xl border border-slate-800 bg-slate-950 p-6 text-white shadow-2xl">
        {/* Floating Spec Coverage Badge */}
        {stage === "analyzed" && coverage !== null && coverage !== undefined && (
          <div className="absolute top-4 right-6 bg-purple-600/80 text-xs px-2 py-1 rounded shadow-md">
            Coverage: {coverage || 0}%
          </div>
        )}

        <div className="mb-4 flex shrink-0 items-center justify-between">
          <h2 className="text-xl font-bold text-white">System Planner</h2>
          <button
            onClick={onClose}
            className="text-[0px] text-slate-400 transition hover:text-white"
          >
            <span className="text-sm">X</span>
            ✖
          </button>
        </div>

        <p className="mb-4 shrink-0 text-sm text-slate-400">
          Enter a goal or description. The planner will analyze the spec,
          leverage memory, and design a new agent if required.
        </p>

        <div className="mb-4 flex shrink-0 flex-wrap gap-2">
          {[
            ["describe", "Describe"],
            ["plan", "Plan"],
            ["agents", "Agents"],
            ["build", "Build"],
          ].map(([key, label]) => (
            <button
              key={key}
              type="button"
              onClick={() => setActivePlannerTab(key as "describe" | "plan" | "agents" | "build")}
              className={`rounded-lg px-3 py-1.5 text-sm font-semibold ${
                activePlannerTab === key
                  ? "bg-cyan-600 text-white"
                  : "border border-slate-700 text-slate-300 hover:bg-slate-900"
              }`}
            >
              {label}
            </button>
          ))}
        </div>

        <div className="min-h-0 flex-1 overflow-y-auto pr-1 scrollbar-thin scrollbar-thumb-slate-700 scrollbar-track-transparent">

        {activePlannerTab === "describe" && (
          <div className="grid gap-5 lg:grid-cols-[minmax(0,1fr)_360px]">
            <div className="space-y-4">

        {/* Optional: Start from existing Design Intent (only in initial stage) */}
        {stage === "initial" && (
          <div className="mb-3">
            <label className="text-xs text-slate-400">
              Start from Design Intent (optional)
            </label>

            <select
              value={selectedIntentId}
              onChange={(e) => {
                const id = e.target.value;
                setSelectedIntentId(id);

                const intent = savedIntents.find((d: any) => d.id === id);

                if (intent) {
                  const newGoal =
                    intent.refined_prompt ||
                    intent.full_intent?.refined_prompt ||
                    "";

                  // Fill System Planner spec input
                  setGoal(newGoal);

                  // Reset pipeline
                  setFinalizedSpec(null);
                  setImprovedSpec(null);
                  setSpec(null);
                  setStage("initial");
                }
              }}
              className="w-full bg-slate-700 text-xs text-white rounded px-2 py-1 mt-1"
            >
              <option value="">Select saved design intent…</option>
              {savedIntents.map((intent: any) => (
                <option key={intent.id} value={intent.id}>
                  {intent.title || "Untitled design intent"}
                </option>
              ))}
            </select>
          </div>
        )}

        <SpecTextBox
          label="Planner spec"
          value={finalizedSpec ?? goal}
          onChange={(value) => {
            if (finalizedSpec !== null) setFinalizedSpec(value);
            else if (improvedSpec !== null) setImprovedSpec(value);
            else setGoal(value);
          }}
          onApplyText={(value) => {
            setVoiceSummary(value);
            setGoal(value);
            setBackendSource("Spec draft");
            setSpec(null);
            setMissingFields([]);
            setCoverage(0);
            setStage("initial");
            setReadyForPlanning(false);
          }}
          rows={12}
          voiceTitle="Voice Spec Draft"
          voiceLoopType="system"
          voiceTarget="System Planner spec"
          uploadLabel="Upload planner spec"
          uploadHelper="Load a system spec, architecture notes, markdown, JSON, YAML, RTL, or text notes."
          placeholder="e.g., Design a 4-bit counter agent for RTL generation"
          textareaClassName="h-[36vh] min-h-64 w-full resize-none bg-transparent p-1 text-sm leading-6 text-white outline-none"
        />
            </div>

          </div>
        )}

        <div className="hidden">

          <button
            onClick={handleAnalyzeSpec}
            disabled={isAnalyzing  || !goal.trim()}
            className="bg-cyan-600 hover:bg-cyan-500 text-white text-sm px-4 py-2 rounded disabled:opacity-40 transition"
          >
            {isAnalyzing ? "Analyzing..." : "Analyze Spec"}
          </button>



          <button
            onClick={handleSelectAgents}
            disabled={!goal.trim() || isSelectingAgents}
            className="bg-cyan-600 hover:bg-cyan-500 text-white text-sm px-4 py-2 rounded disabled:opacity-40 transition"
          >
            {isSelectingAgents? "Selecting Agents..." : "Select Agents"}
          </button>


          <button
            onClick={handleGenerateMissingAgents}
            disabled={isGeneratingAgent || !goal.trim()}
            className="bg-cyan-600 hover:bg-cyan-500 text-white text-sm px-4 py-2 rounded disabled:opacity-40 transition"
          >
            {isGeneratingAgent  ? "Planning..." : "Resolve Missing Agents"}
          </button>

          <button
            onClick={handleBuildWorkflow}
            disabled={missingAgents.length > 0 || finalAgents.length === 0}
            className="bg-cyan-600 hover:bg-cyan-500 text-white text-sm px-4 py-2 rounded disabled:opacity-40 transition"
          >
            Build Workflow
          </button>

          <button
            onClick={startStopRecording}
            className={`bg-cyan-600 hover:bg-cyan-500 text-white text-sm px-4 py-2 rounded disabled:opacity-40 transition ${
              isRecording
                ? "bg-red-600 hover:bg-red-700 text-white animate-pulse"
                : "bg-purple-600 hover:bg-purple-700 text-white"
              }`}
          >
            🎙 {isRecording ? "Stop" : "Start"}
          </button>

          <button
            onClick={onClose}
            className="bg-slate-700 hover:bg-slate-600 px-3 py-1 rounded ml-auto"
          >
            Close
          </button>

        </div>


        {/* Show missing fields simply */}
        {activePlannerTab === "plan" && (
          <div className="space-y-4">
        {!finalizedSpec && missingFields.length > 0 && (
          <div className="mt-3 text-yellow-400 text-sm">
            Missing Details ({missingFields.length}):
            <ul className="list-disc pl-6">
             {missingFields.map((m, idx) => (
              <li key={idx}>{m.path}</li>
             ))}
            </ul>
          </div>
        )}
        {/* Auto-Fill Button */}
        {!finalizedSpec && missingFields.length > 0  && (
          <button
            className="mt-3 px-4 py-2 rounded-lg bg-yellow-500 text-black font-semibold"
            onClick={handleAutoFillMissingFields}        
          >
            Auto-Fill Missing Details
          </button>
        )}
        {stage === "autofill" && missingFields.length > 0 && (
         <div className="mt-4 border border-yellow-500 p-3 rounded-md bg-yellow-900/30">
          <h3 className="text-yellow-300 font-semibold mb-2">
            Review & Edit Auto-Filled Values
          </h3>

          <table className="w-full text-sm">
            <tbody>
              {missingFields.map((item, idx) => (
                <tr key={idx}>
                  <td className="py-1 pr-2 text-gray-200">{item.path}</td>
                  <td className="py-1">
                    <input
                      className="w-full bg-gray-800 text-white border border-gray-600 rounded px-2 py-1"
                      value={missingFieldEdits[item.path] ?? ""}
                      onChange={(e) =>
                        setMissingFieldEdits({
                          ...missingFieldEdits,
                          [item.path]: e.target.value,
                        })
                      }
                    />
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
         </div>
        )}

        {/* Finalize Spec Button */}
        {stage === "autofill" && (
          <button
            className="mt-3 px-4 py-2 rounded-lg bg-green-500 text-black font-semibold"
            onClick={handleFinalizeSpec}
          >
            Finalize Spec
          </button>
        )}

        {/* NEW: Workflow Canvas stage */}
        
        
        {false && missingAgents.length > 0 && (
          <div className="mt-4 border border-cyan-700 rounded-lg p-3 bg-slate-800/60">
            <p className="text-cyan-300 text-sm font-semibold mb-2">Detected Agents:</p>
            <p className="text-green-400 text-xs mb-1">Required Agents:</p>
            <ul className="ml-4 mb-2">
              {(finalAgents.length > 0 ? finalAgents : selectedAgents).map(a => (
                <li key={a} className="text-green-300 text-xs">• {a}</li>
              ))}
            </ul>
            <p className="text-yellow-400 text-xs mb-1">Missing Agents:</p>
            <ul className="ml-4">
              {missingAgents.length > 0
                ? missingAgents.map(a => (
                   <li key={a} className="text-yellow-300 text-xs">• {a}</li>
                  ))
                : <li className="text-gray-400 text-xs">None 🎉</li>
              }
            </ul>
          </div>
        )}

        {false && missingAgents.length === 0 && finalAgents.length > 0 && (
          <div className="mt-6 border border-cyan-700 rounded-lg p-3 bg-slate-800/60">
            <p className="text-cyan-300 text-sm font-semibold mb-2">
              ✅ Final Agents for Workflow:
            </p>

            <ul className="ml-4 mb-3 space-y-0.5">
              {finalAgents.map(a => (
                <li key={a} className="text-green-300 text-xs">• {a}</li>
              ))}
            </ul>

            {recentlyGenerated.length > 0 && (
              <div className="bg-green-900/30 border border-green-600 rounded p-2 mt-2">
                <p className="text-green-400 text-xs font-medium mb-1">
                  🟢 Generated in this step:
                </p>
                <ul className="ml-4 space-y-0.5">
                  {recentlyGenerated.map(a => (
                    <li key={a} className="text-green-300 text-xs">+ {a}</li>
                  ))}
                </ul>
              </div>
            )}


          </div>
        )}


        {stage === "analyzed" && coverage !== null && (
          <div className="mt-4 bg-slate-900 rounded-lg p-3 border border-slate-700">
            <div className="w-full bg-gray-700 rounded-full h-2.5 mb-2">
              <div
                className={`h-2.5 rounded-full ${
                  coverage >= 80
                   ? "bg-green-500"
                   : coverage >= 60
                   ? "bg-yellow-400"
                   : "bg-red-500"
                }`}
                style={{ width: `${coverage}%` }}
              ></div>
            </div>
            <p className="text-sm text-slate-300">Spec Coverage: {coverage}%</p>
          </div>
        )}
             
        {backendSource && (
          <p className="mt-3 text-xs text-slate-400">
            Source: <span className="text-slate-300">{backendSource}</span>
          </p>
        )}
          </div>
        )}



        {(activePlannerTab === "agents" || activePlannerTab === "build") && (
          <div className="space-y-4">
            {missingAgents.length > 0 ? (
              <div className="rounded-lg border border-amber-700 bg-amber-950/30 p-4">
                <p className="mb-2 text-sm font-semibold text-amber-200">Missing Agents</p>
                <ul className="ml-4 list-disc space-y-1 text-sm text-amber-100">
                  {missingAgents.map((agentName) => (
                    <li key={agentName}>{agentName}</li>
                  ))}
                </ul>
              </div>
            ) : null}

            {finalAgents.length > 0 ? (
              <div className="rounded-lg border border-cyan-800 bg-cyan-950/20 p-4">
                <p className="mb-2 text-sm font-semibold text-cyan-200">Final Agents for Workflow</p>
                <ul className="ml-4 list-disc space-y-1 text-sm text-slate-200">
                  {finalAgents.map((agentName) => (
                    <li key={agentName}>{agentName}</li>
                  ))}
                </ul>
                {recentlyGenerated.length ? (
                  <div className="mt-3 rounded border border-emerald-800 bg-emerald-950/20 p-3 text-xs text-emerald-100">
                    Generated in this step: {recentlyGenerated.join(", ")}
                  </div>
                ) : null}
              </div>
            ) : (
              <div className="rounded-lg border border-slate-800 bg-black/30 p-4 text-sm text-slate-400">
                Click Select Agents after the spec is ready.
              </div>
            )}
          </div>
        )}

        {/* Display Agent JSON */}
        {agent && (
          <div className="mt-6 bg-slate-900 p-4 rounded-lg text-xs font-mono text-slate-200 border border-slate-700">
            <div className="flex justify-between items-center mb-2">
              <h3 className="font-semibold text-slate-100">
                🧩 {agent.agent_name || "Unnamed Agent"}
              </h3>
            </div>


            {stage === "analyzed" && coverage !== null && (
              <div className="absolute top-4 right-6 bg-purple-600/80 text-xs px-2 py-1 rounded shadow-md">
                Spec Coverage: {coverage}%
              </div>
            )}

            
            <pre className="whitespace-pre-wrap text-slate-300">
              {JSON.stringify(agent, null, 2)}
            </pre>
          </div>
        )}
        {showNamingDialog && (
          <MissingAgentNamingDialog
            missingAgents={namingTargets}
            domain={(spec?.loop_type || "digital").toLowerCase()}
            onCancel={() => setShowNamingDialog(false)}
            onConfirm={async (finalNames) => {
              setShowNamingDialog(false);
              setIsGeneratingAgent(true);
            
              try {
                const { data: { session } } = await supabase.auth.getSession();
                const user_id = session?.user?.id;
                const res = await fetch("/api/generate_missing_agents_batch", {
                  method: "POST",
                  headers: { "Content-Type": "application/json" },
                  body: JSON.stringify({
                    goal,
                    user_id: user_id,
                    agent_names: finalNames.map(n => (typeof n === "string" ? n : n.new)),
                    structured_spec_final: spec
                  })
                }).then(r => r.json());
            
                // Append new agents to local custom agent list
                const existing = JSON.parse(localStorage.getItem("custom_agents") || "[]");
                const newOnes = (res.created_agents || []).map(a => ({
                  agent_name: a.agent_name,
                  loop_type: a.loop_type,
                  script_path: a.path,
                  description: a.description,
                }));
                localStorage.setItem("custom_agents", JSON.stringify([...existing, ...newOnes]));
            
                // Trigger UI refresh event
                window.dispatchEvent(new Event("refreshAgents"));
            
                alert("✅ Missing agents successfully generated!");

                // ✅ After new agent(s) are successfully generated
                // ✅ Replace missing agent names in-place (preserves original order)
                // ✅ Names created in this step (keep for the green panel)
                const newlyCreated = (res.created_agents || []).map((a: any) => a.agent_name);
                console.log("🟢 Newly Generated Agents:", newlyCreated);

                // ✅ Build the final ordered list for System Planner:
                //    1) Keep the order from Select Agents (preplan.agents)
                //    2) Append the newly created agents at the end (for now)
                //       (We’ll introduce LLM-based ordering later.)
                const base = preplan?.agents || [];
                const mergedAgents = [...base, ...newlyCreated];

                console.log("🟢 Newly merged Agents:", mergedAgents);

                // ✅ Update all relevant state in one place
                setFinalAgents(mergedAgents);
                setSelectedAgents(mergedAgents);
                setRecentlyGenerated(newlyCreated);

                // ✅ Clear “missing” and reflect it in preplan too
                setMissingAgents([]);
                setPreplan(prev =>
                  prev
                    ? { ...prev, agents: mergedAgents, missing_agents: [] }
                    : {
                        loop_type: (spec?.loop_type || "system").toLowerCase(),
                        agents: mergedAgents,
                        missing_agents: [],
                      }
                );
                             
                // ✅ Small visual cue
                alert("✅ Missing agents resolved! You can now Build Workflow.");

            
              } catch (err) {
                console.error(err);
                alert("❌ Failed to generate missing agents");
              }
            
              setIsGeneratingAgent(false);
            }}
          />
        )}
        {showMissingResolver && (
          <MissingAgentsResolverModal
            missingAgents={namingTargets.length ? namingTargets : missingAgents}
            goal={goal}
            loopType={(spec?.loop_type || preplan?.loop_type || "system").toLowerCase()}
            domain={(spec?.domain || spec?.loop_type || preplan?.loop_type || "system").toLowerCase()}
            spec={spec}
            baseAgents={preplan?.agents || selectedAgents || []}
            onClose={() => setShowMissingResolver(false)}
            onResolved={(resolvedNames) => {
              const base = preplan?.agents || selectedAgents || [];
              const mergedAgents = [...base, ...resolvedNames];
              setFinalAgents(mergedAgents);
              setSelectedAgents(mergedAgents);
              setRecentlyGenerated(resolvedNames);
              setMissingAgents([]);
              setNamingTargets([]);
              setPreplan(prev =>
                prev
                  ? { ...prev, agents: mergedAgents, missing_agents: [] }
                  : {
                      loop_type: (spec?.loop_type || "system").toLowerCase(),
                      agents: mergedAgents,
                      missing_agents: [],
                    }
              );
              setShowMissingResolver(false);
              window.dispatchEvent(new Event("refreshAgents"));
            }}
          />
        )}



        </div>

        <div className="mt-4 flex shrink-0 flex-wrap justify-end gap-2 border-t border-slate-800 pt-4">
          {activePlannerTab === "describe" ? (
            <button
              onClick={handleAnalyzeSpec}
              disabled={isAnalyzing || !goal.trim()}
              className="rounded-lg bg-cyan-600 px-4 py-2 text-sm font-bold text-white hover:bg-cyan-500 disabled:cursor-not-allowed disabled:bg-slate-800 disabled:text-slate-500"
            >
              {isAnalyzing ? "Analyzing..." : "Analyze Spec"}
            </button>
          ) : null}
          {activePlannerTab === "plan" && missingFields.length > 0 && !finalizedSpec ? (
            <button
              onClick={handleAutoFillMissingFields}
              disabled={isAnalyzing}
              className="rounded-lg bg-yellow-500 px-4 py-2 text-sm font-bold text-black hover:bg-yellow-400 disabled:cursor-not-allowed disabled:bg-slate-800 disabled:text-slate-500"
            >
              Auto-Fill Missing Details
            </button>
          ) : null}
          {activePlannerTab === "plan" && stage === "autofill" ? (
            <button
              onClick={handleFinalizeSpec}
              disabled={isAnalyzing}
              className="rounded-lg bg-emerald-700 px-4 py-2 text-sm font-bold text-white hover:bg-emerald-600 disabled:cursor-not-allowed disabled:bg-slate-800 disabled:text-slate-500"
            >
              Finalize Spec
            </button>
          ) : null}
          {activePlannerTab === "agents" ? (
            <>
              <button
                onClick={handleSelectAgents}
                disabled={!goal.trim() || isSelectingAgents}
                className="rounded-lg bg-cyan-600 px-4 py-2 text-sm font-bold text-white hover:bg-cyan-500 disabled:cursor-not-allowed disabled:bg-slate-800 disabled:text-slate-500"
              >
                {isSelectingAgents ? "Selecting Agents..." : "Select Agents"}
              </button>
              {missingAgents.length > 0 ? (
                <button
                  onClick={handleGenerateMissingAgents}
                  disabled={isGeneratingAgent || !goal.trim()}
                  className="rounded-lg border border-slate-700 px-4 py-2 text-sm font-semibold text-slate-200 hover:bg-slate-900 disabled:cursor-not-allowed disabled:text-slate-500"
                >
                  {isGeneratingAgent ? "Planning..." : "Resolve Missing Agents"}
                </button>
              ) : null}
            </>
          ) : null}
          {activePlannerTab === "build" ? (
            <button
              onClick={handleBuildWorkflow}
              disabled={missingAgents.length > 0 || finalAgents.length === 0}
              className="rounded-lg bg-emerald-700 px-4 py-2 text-sm font-bold text-white hover:bg-emerald-600 disabled:cursor-not-allowed disabled:bg-slate-800 disabled:text-slate-500"
            >
              Build Workflow
            </button>
          ) : null}
        </div>

        {summary && (
          <div className="mt-3 max-h-36 shrink-0 overflow-auto rounded-xl border border-slate-800 bg-slate-900 p-3 text-white [&>h3]:hidden">
              <div className="mb-2 text-sm font-bold">Spec Summary Preview</div>
              <h3 className="font-bold text-sm mb-2">🧾 Spec Summary Preview</h3>
              <pre className="text-xs whitespace-pre-wrap bg-gray-800 p-2 rounded-md max-h-48 overflow-auto">
                {JSON.stringify(summary, null, 2)}
              </pre>
              <div className="mt-2">
                <div className="w-full bg-gray-700 rounded-full h-2.5">
                  <div
                    className={`h-2.5 rounded-full ${
                      coverage >= 80
                        ? "bg-green-500"
                        : coverage >= 60
                        ? "bg-yellow-400"
                        : "bg-red-500"
                    }`}
                    style={{ width: `${coverage}%` }}
                  />
                </div>
                <p className="text-xs mt-1 text-gray-400">Coverage: {coverage}%</p>
              </div>
          </div>
        )}
      
      </div>
    </div>
  );
}

