}

type SupabaseHemChildRun = {
  workflow_id: string;
  label: string;
  status?: string | null;
  dashboard_path: string;
  has_artifacts?: boolean;
};

function artifactIndexHasEntries(value: unknown): boolean {
  if (typeof value === "string") return value.trim().length > 0;
  if (Array.isArray(value)) return value.some(artifactIndexHasEntries);
  if (value && typeof value === "object") return Object.values(value as Record<string, unknown>).some(artifactIndexHasEntries);
  return false;
}

export function HemChildDashboardLinks({ logs, runs, rootWorkflowId }: { logs: string | null | undefined; runs?: SupabaseHemChildRun[]; rootWorkflowId?: string | null }) {
  const [linkedRuns, setLinkedRuns] = useState<SupabaseHemChildRun[]>([]);
  const supabase = useMemo(() => createClientComponentClient(), []);

  useEffect(() => {
    if (!rootWorkflowId) {
      setLinkedRuns([]);
      return;
    }
    let active = true;
    let interval: number | null = null;
    const fetchLinkedRuns = async () => {
      const { data, error } = await supabase
        .from("workflows")
        .select("id,name,status,definitions,artifacts")
        .contains("definitions", { hem_root_workflow_id: rootWorkflowId });
      if (!active || error || !data) return;
      const next = (data as Array<{ id: string; name?: string | null; status?: string | null; definitions?: Record<string, unknown> | null; artifacts?: unknown }>)
        .filter((row) => Boolean(row.id))
        .map((row) => {
          const definitions = row.definitions || {};
          const stage = String(definitions.hem_stage || "");
          const dashboardStage = dashboardStageFromHemStage(stage || String(definitions.hem_dashboard_stage || "run"));
          return {
            workflow_id: row.id,
            label: String(definitions.hem_stage_label || row.name || labelFromStage(stage)),
            status: row.status || "running",
            dashboard_path: `/dashboard/${row.id}?stage=${encodeURIComponent(dashboardStage)}&app=HEM`,
            has_artifacts: artifactIndexHasEntries(row.artifacts),
          };
        });
      setLinkedRuns(next);
    };
    void fetchLinkedRuns();
    interval = window.setInterval(() => void fetchLinkedRuns(), 2500);
    return () => {
      active = false;
      if (interval) window.clearInterval(interval);
    };
  }, [rootWorkflowId, supabase]);

  const childRuns = useMemo(() => {
    const authoritative = [...(runs || []), ...linkedRuns].map((run) => ({
      label: run.label,
      workflowId: run.workflow_id,
      dashboardPath: run.dashboard_path,
      status: run.status || "running",
      hasArtifacts: run.has_artifacts,
    }));
    const byId = new Map<string, (typeof authoritative)[number]>();
    for (const run of authoritative) {
      const previous = byId.get(run.workflowId);
      byId.set(run.workflowId, {
        ...previous,
        ...run,
        hasArtifacts: previous?.hasArtifacts === true || run.hasArtifacts === true
          ? true
          : run.hasArtifacts ?? previous?.hasArtifacts,
      });
    }
    for (const parsed of parseHemChildRuns(logs)) {
      if (!byId.has(parsed.workflowId)) byId.set(parsed.workflowId, { ...parsed, status: parsed.status || "running", hasArtifacts: undefined });
    }
    return Array.from(byId.values()).sort((a, b) => {
      const aIndex = HEM_STAGE_ORDER.indexOf(stageFromLabel(a.label));
      const bIndex = HEM_STAGE_ORDER.indexOf(stageFromLabel(b.label));
      return (aIndex === -1 ? 99 : aIndex) - (bIndex === -1 ? 99 : bIndex);
    });
  }, [linkedRuns, logs, runs]);
  const workflowIds = useMemo(() => childRuns.map((child) => child.workflowId), [childRuns]);
  const workflowIdKey = workflowIds.join(",");
  const [workflowStatuses, setWorkflowStatuses] = useState<Record<string, string>>({});
  useEffect(() => {
    const ids = workflowIdKey.split(",").filter(Boolean);
    if (!ids.length) {
      setWorkflowStatuses({});
      return;
    }

    let active = true;
    let interval: number | null = null;
    const fetchStatuses = async () => {
      const { data, error } = await supabase
        .from("workflows")
        .select("id,status")
        .in("id", ids);
      if (!active || error || !data) return;
      const nextStatuses: Record<string, string> = {};
      for (const row of data as Array<{ id: string; status?: string | null }>) {
        if (row.id && row.status) nextStatuses[row.id] = row.status;
      }
      setWorkflowStatuses(nextStatuses);
      const currentStatuses = ids.map((id) => nextStatuses[id]).filter(Boolean);
      const allTerminal =
        currentStatuses.length === ids.length &&
        currentStatuses.every((status) => ["completed", "failed", "cancelled", "stopped"].includes(status.toLowerCase()));
      if (allTerminal && interval) window.clearInterval(interval);
    };

    void fetchStatuses();
    interval = window.setInterval(() => {
      void fetchStatuses();
    }, 2500);

    return () => {
      active = false;
      if (interval) window.clearInterval(interval);
    };
  }, [supabase, workflowIdKey]);

  return (
    <div className="mt-3 rounded-xl border border-cyan-900/50 bg-cyan-950/15 p-4 text-sm text-slate-300">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <div>
          <div className="font-semibold text-cyan-100">HEM Run Summary</div>
          <div className="mt-1 text-xs text-slate-500">
            Open each workflow dashboard to review generated artifacts, logs, and results.
          </div>
        </div>
        <div className="rounded-full border border-cyan-800/60 bg-black/20 px-3 py-1 text-xs text-cyan-100">
          {childRuns.length} linked workflow{childRuns.length === 1 ? "" : "s"}
        </div>
      </div>
      <div className="mt-3 overflow-x-auto rounded-xl border border-slate-800">
        <table className="w-full min-w-[720px] text-left text-xs">
          <thead className="bg-black/30 text-slate-400">
            <tr>
              <th className="px-3 py-2 font-semibold">Workflow</th>
              <th className="px-3 py-2 font-semibold">Status</th>
              <th className="px-3 py-2 font-semibold">Workflow ID</th>
              <th className="px-3 py-2 text-right font-semibold">Actions</th>
            </tr>
          </thead>
          <tbody>
            {!childRuns.length && (
              <tr className="border-t border-slate-800 bg-black/10">
                <td colSpan={4} className="px-3 py-6 text-center text-sm text-slate-400">
                  Waiting for the next HEM workflow to start…
                </td>
              </tr>
            )}
            {childRuns.map((child) => (
              <tr key={`${child.label}-${child.workflowId}`} className="border-t border-slate-800 bg-black/10">
                <td className="px-3 py-3 font-semibold text-slate-100">{child.label}</td>
                <td className="px-3 py-3">
                  <span className="rounded-full border border-slate-700 bg-black/30 px-2 py-1 text-slate-300">
                    {workflowStatuses[child.workflowId] || child.status || "running"}
                  </span>
                </td>
                <td className="max-w-[340px] break-all px-3 py-3 font-mono text-[11px] text-slate-400">
                  {child.workflowId}
                </td>
                <td className="px-3 py-3">
                  <div className="flex flex-wrap justify-end gap-2">
                  <a
                    href={child.dashboardPath}
                    target="_blank"
                    rel="noreferrer"
                    className="rounded-lg bg-cyan-700 px-3 py-2 text-xs font-semibold text-white hover:bg-cyan-600"
                  >
                    Open Dashboard
                  </a>
                  {child.hasArtifacts === false ? (
                    <span className="cursor-not-allowed rounded-lg border border-slate-700 bg-slate-900/70 px-3 py-2 text-xs font-semibold text-slate-500" title="This workflow produced no indexed artifacts. Open Dashboard to review its status and failure reason.">
                      No artifacts
                    </span>
                  ) : (
                    <a
                      href={`${process.env.NEXT_PUBLIC_API_URL || "/api"}/workflow/${encodeURIComponent(child.workflowId)}/download_zip?full=1`}
                      target="_blank"
                      rel="noreferrer"
                      className="rounded-lg border border-emerald-500/50 bg-emerald-500/10 px-3 py-2 text-xs font-semibold text-emerald-100 hover:border-emerald-400"
                    >
                      Download ZIP
                    </a>
                  )}
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

