"use client";

import { useEffect, useMemo, useState } from "react";
import { ApiClientError, apiGet } from "@/lib/apiClient";
import { createClientComponentClient } from "@/lib/platformClient";

type Stage = "physical_ai" | "arch2rtl" | "dqa" | "rtl_review" | "constraint_review" | "timing_debug" | "smoke" | "synthesis" | "tapeout" | "fpga" | "fpga_target_explorer" | "verification" | "embedded" | "software" | "validation" | "product";
type JsonMap = Record<string, unknown>;

type Props = {
  workflowId: string | null;
  status?: string | null;
  stage: Stage;
  logs?: string | null;
  linkedHeatmaps?: Array<{
    label: string;
    workflowId: string | null;
    status?: string | null;
    logs?: string | null;
  }>;
};

type WorkflowLogRow = {
  logs?: string | null;
};

type TokenHeatmapAgent = {
  agent_name: string;
  capability?: string | null;
  provider?: string | null;
  model?: string | null;
  input_tokens: number;
  output_tokens: number;
  total_tokens: number;
  estimated_cost_usd?: number | null;
  estimated_credits?: number | null;
  event_count?: number | null;
  failed_event_count?: number | null;
  context_mode?: string | null;
  full_context_estimate_tokens?: number | null;
  smart_context_tokens?: number | null;
  smart_context_reduction_percent?: number | null;
};

type TokenHeatmapResponse = {
  workflow_id: string;
  available: boolean;
  agents: TokenHeatmapAgent[];
  summary: {
    agent_count: number;
    input_tokens: number;
    output_tokens: number;
    total_tokens: number;
    estimated_cost_usd?: number | null;
    estimated_credits?: number | null;
    event_count?: number | null;
    highest_usage_agent?: string | null;
    previous_workflow_id?: string | null;
    previous_total_tokens?: number | null;
    token_delta_percent?: number | null;
    optimization_suggestions?: string[];
  };
};

type FlowItem = { id: Stage; label: string };

const RTL_STAGE: FlowItem = { id: "arch2rtl", label: "RTL" };

const MAIN_FLOW: FlowItem[] = [
  RTL_STAGE,
  { id: "verification", label: "Verify" },
  { id: "embedded", label: "Firmware" },
  { id: "software", label: "Software" },
  { id: "validation", label: "Validation" },
  { id: "product", label: "Product" },
];

const OPTIONAL_DIGITAL_FLOW: Record<Extract<Stage, "dqa" | "rtl_review" | "constraint_review" | "timing_debug" | "smoke" | "synthesis" | "tapeout" | "fpga">, FlowItem> = {
  dqa: { id: "dqa", label: "DQA" },
  rtl_review: { id: "rtl_review", label: "RTL Review" },
  constraint_review: { id: "constraint_review", label: "Constraints" },
  timing_debug: { id: "timing_debug", label: "Timing Debug" },
  smoke: { id: "smoke", label: "Smoke" },
  synthesis: { id: "synthesis", label: "Synth" },
  tapeout: { id: "tapeout", label: "Tapeout" },
  fpga: { id: "fpga", label: "FPGA" },
};

function displayedFlow(stage: Stage): FlowItem[] {
  if (stage === "physical_ai") {
    return [
      { id: "physical_ai", label: "Physical AI" },
      { id: "arch2rtl", label: "RTL" },
      { id: "verification", label: "Verify" },
      { id: "fpga", label: "FPGA" },
      { id: "tapeout", label: "ASIC" },
    ];
  }
  if (stage === "fpga") {
    return [
      RTL_STAGE,
      { id: "synthesis", label: "Synth" },
      { id: "fpga", label: "P&R" },
      { id: "fpga", label: "Bitstream" },
    ];
  }
  if (stage === "dqa" || stage === "rtl_review" || stage === "constraint_review" || stage === "timing_debug" || stage === "smoke" || stage === "synthesis" || stage === "tapeout") {
    return [RTL_STAGE, OPTIONAL_DIGITAL_FLOW[stage]];
  }
  return MAIN_FLOW;
}

function record(value: unknown): JsonMap {
  return value && typeof value === "object" && !Array.isArray(value) ? value as JsonMap : {};
}

function array(value: unknown): unknown[] {
  return Array.isArray(value) ? value : [];
}

function number(value: unknown): number {
  return typeof value === "number" && Number.isFinite(value) ? value : 0;
}

function firstNumber(...values: unknown[]): number {
  for (const value of values) {
    if (typeof value === "number" && Number.isFinite(value)) return value;
  }
  return 0;
}

function firstString(...values: unknown[]): string {
  for (const value of values) {
    if (typeof value === "string" && value.trim()) return value.trim();
  }
  return "";
}

function firstPresent(...values: unknown[]): unknown {
  for (const value of values) {
    if (value !== undefined && value !== null && value !== "") return value;
  }
  return undefined;
}

function metricValue(...values: unknown[]): string | number {
  const value = firstPresent(...values);
  if (typeof value === "number" && Number.isFinite(value)) return formatNumber(value);
  if (typeof value === "string" && value.trim()) return value.trim();
  return "not produced";
}

function metricWithUnit(unit: string, ...values: unknown[]): string | number {
  const value = firstPresent(...values);
  if (typeof value === "number" && Number.isFinite(value)) return `${formatNumber(value)} ${unit}`;
  if (typeof value === "string" && value.trim()) {
    const text = value.trim();
    return text.toLowerCase().includes(unit.toLowerCase()) ? text : `${text} ${unit}`;
  }
  return "not produced";
}

function fileLabel(...values: unknown[]): string {
  const value = firstString(...values);
  if (!value) return "";
  const normalized = value.replaceAll("\\", "/");
  return normalized.split("/").pop() || normalized;
}

function signedMetric(...values: unknown[]): string | number {
  const value = firstPresent(...values);
  if (typeof value === "number" && Number.isFinite(value)) return formatNumber(value);
  if (typeof value === "string" && value.trim()) return value.trim();
  return "not run";
}

function zeroWhenClean(status: unknown, value: unknown): unknown {
  if (value !== undefined && value !== null && value !== "") return value;
  const text = typeof status === "string" ? status.trim().toLowerCase() : "";
  return ["ok", "clean", "pass", "completed", "generated"].includes(text) ? 0 : value;
}

function formatNumber(value: number): string | number {
  if (!Number.isFinite(value)) return "not produced";
  if (Number.isInteger(value)) return value;
  return Number(value.toFixed(3)).toString();
}

function formatCompactNumber(value: unknown): string {
  const numeric = typeof value === "number" && Number.isFinite(value) ? value : 0;
  return new Intl.NumberFormat("en-US", { notation: numeric >= 10000 ? "compact" : "standard", maximumFractionDigits: 1 }).format(numeric);
}

function formatCost(value: unknown): string {
  if (typeof value !== "number" || !Number.isFinite(value) || value <= 0) return "not tracked";
  if (value < 0.01) return `$${value.toFixed(4)}`;
  return `$${value.toFixed(2)}`;
}

function formatDelta(value: unknown): string {
  if (typeof value !== "number" || !Number.isFinite(value)) return "no prior run";
  if (value === 0) return "flat vs previous";
  return `${value > 0 ? "+" : ""}${value}% vs previous`;
}

function unprovenMetric(status: unknown, value: unknown): string | number {
  const text = typeof status === "string" ? status.trim().toLowerCase() : "";
  if (["pass", "ok", "clean"].includes(text)) return 0;
  return metricValue(value);
}

function pct(value: unknown): string {
  return typeof value === "number" && Number.isFinite(value) ? `${value}%` : "Unavailable";
}

function pctWithStatus(value: unknown, status: unknown): string {
  if (typeof value === "number" && Number.isFinite(value)) return `${value}%`;
  const text = typeof status === "string" && status.trim() ? status.trim() : "";
  if (text === "not_reported_by_verilator_lcov" || text === "not_reported_by_verilator_annotate_points") return "Not reported";
  return text ? `Unavailable (${text})` : "Unavailable";
}

function statusLabel(value: unknown): string {
  const text = typeof value === "string" && value.trim() ? value.trim() : "not_enabled";
  return text.replaceAll("_", " ");
}

function dftDashboardStatus(dft: JsonMap): string {
  const status = firstString(dft.status);
  if (status === "scan_cell_mapping_required") return "scan-cell mapping required";
  if (status === "scan_not_inserted") return "scan not inserted";
  return statusLabel(status);
}

function atpgDashboardStatus(atpg: JsonMap): string {
  const status = firstString(atpg.status);
  const reason = firstString(atpg.reason);
  if (reason === "scan_cell_mapping_required") return "blocked: scan-cell mapping required";
  if (status === "tool_detected_needs_adapter_command") return "adapter command required";
  if (status === "adapter_completed_no_metrics") return "adapter ran: no metrics";
  if (status === "adapter_completed_no_patterns") return "adapter ran: no patterns";
  if (status === "patterns_generated") return "patterns generated";
  if (status === "adapter_command_missing") return "adapter command missing";
  if (status === "adapter_failed") return "adapter failed";
  return statusLabel(status);
}

function atpgMetric(status: unknown, ...values: unknown[]): string | number {
  const text = typeof status === "string" ? status.trim() : "";
  if (text === "not_applicable") return "not applicable";
  if (text !== "patterns_generated") return "not produced";
  return metricValue(...values);
}

function scanMetric(status: unknown, value: unknown): string | number {
  const text = typeof status === "string" ? status.trim() : "";
  if (text === "not_applicable" || text === "scan_not_inserted" || text === "scan_cell_mapping_required" || text === "no_scan_flops" || text === "tool_unavailable") {
    return "not applicable";
  }
  return metricValue(value);
}

function lecDashboardStatus(lec: JsonMap): string {
  const status = firstString(lec.status);
  if (status === "missing_cell_library") return "setup issue: missing liberty";
  if (status === "missing_stdcell_models") return "setup issue: missing stdcell models";
  if (status === "incomplete_stdcell_models") return "setup issue: incomplete stdcell models";
  if (status === "inconclusive_unresolved_cells") return "inconclusive: unresolved cells";
  if (status === "inconclusive_missing_sat_models") return "inconclusive: missing SAT models";
  return statusLabel(status);
}

function findingCount(report: JsonMap): number {
  return array(report.findings).length
    + array(report.heuristic_issues).length
    + array(report.synthesizable_subset_findings).length
    + array(record(report.yosys).errors).length;
}

function uniqueStrings(values: unknown[]): string[] {
  const out: string[] = [];
  const seen = new Set<string>();
  for (const value of values) {
    const text = typeof value === "string" ? value.trim() : "";
    if (!text || seen.has(text)) continue;
    seen.add(text);
    out.push(text);
  }
  return out;
}

function boolToolNames(tools: JsonMap): string[] {
  return Object.entries(tools)
    .filter(([, value]) => value === true)
    .map(([key]) => key);
}

function dqaToolSummary(lint: JsonMap, readiness: JsonMap, executionSummary: JsonMap, profileSummary: JsonMap) {
  const lintTooling = record(lint.tooling);
  const lintProfile = record(lintTooling.tool_profile);
  const summaryProfile = record(executionSummary.tool_profile);
  const explicitProfile = Object.keys(profileSummary).length ? profileSummary : {};
  const executions = [
    ...array(lintTooling.executions),
    ...array(executionSummary.executions),
  ].map(record);
  const yosys = record(readiness.yosys);
  const used = uniqueStrings([
    ...executions.map((item) => item.tool),
    yosys.available === true ? "yosys" : "",
  ]);
  const detected = boolToolNames(record(readiness.tools_detected));
  const profileTools = [
    ...array(lintProfile.tools),
    ...array(summaryProfile.tools),
    ...array(explicitProfile.tools),
  ];
  const available = uniqueStrings([...used, ...detected, ...profileTools]);
  return {
    used,
    available,
    defaultTool: used.join(" / ") || "not reported",
  };
}

function lintVerdict(report: JsonMap): string {
  if (!Object.keys(report).length) return "unavailable";
  const verilator = record(report.verilator_lint);
  if (verilator.available === false) return "unavailable";
  const rc = verilator.returncode;
  const issues = array(report.heuristic_issues);
  if (typeof rc === "number" && rc !== 0) return `fail (rc ${rc})`;
  if (issues.some((issue) => String(record(issue).severity || "").toLowerCase() === "warning")) return "warning";
  return "pass";
}

function findingsVerdict(report: JsonMap): string {
  if (!Object.keys(report).length) return "unavailable";
  const findings = array(report.findings);
  if (!findings.length) return "pass";
  const hasError = findings.some((item) => {
    const severity = String(record(item).severity || "").toLowerCase();
    return severity === "error" || severity === "critical" || severity === "fail";
  });
  return hasError ? "fail" : "warning";
}

function synthesisReadinessVerdict(report: JsonMap): string {
  if (!Object.keys(report).length) return "unavailable";
  const score = number(report.score);
  const yosys = record(report.yosys);
  if (yosys.available === false) return "unavailable";
  const errors = array(yosys.errors).length;
  if (errors > 0) return "fail";
  if (score >= 80) return "pass";
  if (score >= 60) return "warning";
  return "fail";
}

function synthesisStatus(summary: JsonMap): string {
  const status = firstString(summary.status, summary.verdict);
  const rc = summary.return_code;
  if (status === "ok" || status === "pass" || status === "passed") return "pass";
  if (status === "failed" || status === "fail") return typeof rc === "number" ? `fail (rc ${rc})` : "fail";
  return status || "not produced";
}

function sdcStatus(setup: JsonMap, synthSummary: JsonMap): string {
  const setupStatus = firstString(setup.status);
  const outputs = record(setup.outputs);
  const inputs = record(synthSummary.inputs);
  const sdc = firstString(outputs.sdc, inputs.sdc, record(synthSummary.outputs).sdc);
  const synthStatus = firstString(synthSummary.status);
  if (setupStatus === "ok" && sdc) return "pass";
  if (synthStatus === "failed" && firstString(synthSummary.error).toLowerCase().includes("sdc")) return "fail";
  return sdc ? "available" : "not produced";
}

function timingViolationValue(wns: unknown, tns: unknown, explicit: unknown): string | number {
  const direct = firstPresent(explicit);
  if (typeof direct === "number" && Number.isFinite(direct)) return direct;
  const w = typeof wns === "number" && Number.isFinite(wns) ? wns : Number.NaN;
  const t = typeof tns === "number" && Number.isFinite(tns) ? tns : Number.NaN;
  if (Number.isFinite(w) || Number.isFinite(t)) return w < 0 || t < 0 ? "violated" : "0";
  return "not run";
}

function countParticipatingAgents(logs: string | null | undefined): number | null {
  const agents = extractParticipatingAgentNames(logs);
  return agents.length || null;
}

function extractParticipatingAgentNames(logs: string | null | undefined): string[] {
  if (!logs) return [];
  const agents = new Set<string>();
  const normalizeAgentName = (value: string) =>
    value
      .replace(/^[^\w]+/u, "")
      .replace(/\s+/g, " ")
      .trim();
  const canonicalAgentName = (value: string) => {
    const normalized = normalizeAgentName(value);
    const lower = normalized.toLowerCase();
    if (lower.includes("fpga") && lower.includes("rtl") && lower.includes("handoff")) return "FPGA RTL Handoff Ingest Agent";
    if (lower.includes("fpga") && lower.includes("constraint")) return "FPGA Constraint Setup Agent";
    if (lower.includes("fpga") && lower.includes("yosys")) return "FPGA Yosys Synthesis Agent";
    if (lower.includes("fpga") && lower.includes("synthesis closure")) return "FPGA Synthesis Closure Agent";
    if ((lower.includes("fpga") || lower.startsWith("pnr ")) && (lower.includes("nextpnr") || lower.includes("place") || lower.includes("route"))) return "FPGA nextpnr Place & Route Agent";
    if (lower.includes("fpga") && lower.includes("timing") && lower.includes("drc")) return "FPGA Timing & DRC Agent";
    if (lower.includes("fpga") && lower.includes("timing closure")) return "FPGA Timing Closure Agent";
    if (lower.includes("fpga") && lower.includes("bitstream")) return "FPGA Bitstream Handoff Agent";
    if (lower.includes("fpga") && lower.includes("dashboard")) return "FPGA Dashboard Agent";
    return normalized;
  };
  for (const rawLine of logs.split("\n")) {
    const line = rawLine.trim();
    const running = line.match(/Running\s+(.+?\sAgent)\b/i);
    const finished = line.match(/^(.+?\sAgent)\s+(?:done|failed)\b/i);
    const lifecycle = line.match(/(?:^|:)\s*(.+?\sAgent)\s+(?:started|completed|done|failed)\b/i);
    const physicalAiLifecycle = line.match(/Physical\s+AI\s+agent\s+(?:started|completed|done|failed):\s*(.+?\sAgent)\b/i);
    const platformLifecycle = line.match(/^(?:ACTIVE\s+AGENT|AGENT\s+(?:COMPLETED|FAILED)):\s*(.+?\sAgent)(?:\s*\||$)/i);
    const name = platformLifecycle?.[1] || physicalAiLifecycle?.[1] || running?.[1] || finished?.[1] || lifecycle?.[1];
    if (name) {
      const normalized = canonicalAgentName(name);
      if (normalized) agents.add(normalized);
    }
  }
  return [...agents];
}

function hasTerminalEvidence(status: string | null | undefined, stage: Stage, logs: string | null | undefined): boolean {
  const normalized = String(status || "").toLowerCase();
  if (["completed", "complete", "success", "succeeded", "failed", "done"].includes(normalized)) return true;
  if (!logs) return false;
  if (/(?:system|digital|embedded|analog|validation|fpga)\s+(?:run\s+)?app\s+complete/i.test(logs)) return true;
  if (/system\s+app\s+complete:\s*system[_\s-]*(?:firmware|software|software[_\s-]*validation|product[_\s-]*app[_\s-]*builder|rtl|sim)/i.test(logs)) {
    return true;
  }
  if (stage === "embedded") {
    return /system[_\s-]*firmware.*(?:cosim|coverage|dashboard|complete|generated)|system_software_handoff/i.test(logs);
  }
  if (stage === "software") {
    return /system\s+software\s+(?:packaging|executive\s+summary).*done|system_software_(?:package|executive_summary|api_contract)\.json/i.test(logs);
  }
  if (stage === "validation") {
    return /system\s+software\s+validation\s+summary.*done|(?:l2_)?validation_summary\.json|system_software_validation_summary(?:_l2)?\.json|system_cosim_trace_validation_report\.json/i.test(logs);
  }
  if (stage === "product") {
    return /system\s+product\s+(?:package|dashboard|capability|collateral).*done|system_product_(?:package|dashboard_manifest|capability_model|collateral_contract)\.json|system\/product\/app\/index\.html/i.test(logs);
  }
  if (stage === "fpga") {
    return /fpga\s+(?:dashboard|bitstream|timing|nextpnr|yosys).*done|fpga_dashboard\.json|fpga_bitstream_summary\.json/i.test(logs);
  }
  return false;
}

async function artifact(workflowId: string, filename: string): Promise<JsonMap | null> {
  try {
    return record(
      await apiGet<JsonMap>(
        `/apps/dashboard/artifact/${workflowId}?filename=${encodeURIComponent(filename)}`
      )
    );
  } catch (reason) {
    if (reason instanceof ApiClientError && reason.status === 404) return null;
    if (reason instanceof ApiClientError && reason.status >= 500) return null;
    throw reason;
  }
}

function stageEvidenceReady(stage: Stage, evidence: Record<string, JsonMap | null>): boolean {
  const has = (key: string) => Object.keys(record(evidence[key])).length > 0;
  if (stage === "physical_ai") {
    return has("physical_ai_workflow_summary.json") || has("physical_ai_loop_state.json") || has("model_generated_architecture.json");
  }
  if (stage === "product") {
    return has("system_product_dashboard_manifest.json") || has("system_product_package.json");
  }
  if (stage === "fpga") {
    const dashboard = record(evidence["fpga_dashboard.json"] || evidence["fpga/fpga_dashboard.json"]);
    const hasRoutedSummary = Object.keys(record(dashboard.routed_result)).length > 0
      || Object.keys(record(dashboard.place_route)).length > 0
      || has("fpga_place_route_summary.json")
      || has("fpga/pnr/fpga_place_route_summary.json");
    const hasTimingSummary = Object.keys(record(dashboard.timing_summary)).length > 0
      || Object.keys(record(dashboard.timing_drc)).length > 0
      || has("fpga_timing_drc_summary.json")
      || has("fpga/reports/fpga_timing_drc_summary.json");
    const hasBitstreamSummary = Object.keys(record(dashboard.bitstream)).length > 0
      || has("fpga_bitstream_summary.json")
      || has("fpga/bitstream/fpga_bitstream_summary.json");
    return hasRoutedSummary && hasTimingSummary && hasBitstreamSummary;
  }
  return Object.values(evidence).some((value) => Object.keys(record(value)).length > 0);
}

function Stat({ title, value }: { title: string; value: string | number }) {
  return (
    <div className="min-w-0 rounded-lg border border-slate-800 bg-black/30 p-3">
      <div className="text-xs text-slate-400">{title}</div>
      <div className="mt-1 min-h-6 break-words text-base font-semibold leading-snug text-slate-100">{value}</div>
    </div>
  );
}

function ToolStrip({ used, defaultTool, label = "Tools Used" }: { used: string[]; defaultTool: string; label?: string }) {
  return (
    <div className="rounded-lg border border-slate-800 bg-black/30 p-3">
      <div className="min-w-0">
        <div className="text-xs text-slate-400">{label}</div>
        <div className="mt-1 break-words text-base font-semibold leading-snug text-slate-100">{defaultTool}</div>
        <div className="mt-2 flex gap-2 overflow-x-auto pb-1">
          {used.map((tool) => (
            <span key={tool} className="shrink-0 rounded border border-slate-700 bg-slate-950 px-2.5 py-1 text-xs font-semibold text-cyan-100">
              {tool}
            </span>
          ))}
          {!used.length ? <span className="text-sm text-slate-500">not reported</span> : null}
        </div>
      </div>
    </div>
  );
}

function CheckCard({ title, status, detail }: { title: string; status: string; tool?: string; detail?: string | number }) {
  return (
    <div className="min-w-0 rounded-lg border border-slate-800 bg-black/30 p-3">
      <div className="text-xs text-slate-400">{title}</div>
      <div className="mt-1 break-words text-base font-semibold leading-snug text-slate-100">{status}</div>
      {detail !== undefined ? <div className="mt-2 text-xs text-slate-500">{detail}</div> : null}
    </div>
  );
}

function CheckTable({ rows }: { rows: Array<{ check: string; status: string; detail: string; tool: string }> }) {
  return (
    <div className="overflow-x-auto rounded-lg border border-slate-800">
      <div className="min-w-[640px]">
        <div className="grid grid-cols-[1fr_1fr_1.4fr_1fr] border-b border-slate-800 bg-slate-950/70 px-4 py-2 text-xs font-semibold uppercase text-slate-400">
          <div>Check</div>
          <div>Status</div>
          <div>Evidence</div>
          <div>Tool</div>
        </div>
        {rows.map((row) => (
          <div key={row.check} className="grid grid-cols-[1fr_1fr_1.4fr_1fr] border-b border-slate-800 px-4 py-3 text-sm last:border-b-0">
            <div className="text-slate-300">{row.check}</div>
            <div className="font-semibold text-slate-100">{row.status}</div>
            <div className="text-slate-400">{row.detail}</div>
            <div className="text-cyan-100">{row.tool}</div>
          </div>
        ))}
      </div>
    </div>
  );
}

function Bar({ label, value, total, color }: { label: string; value: number; total: number; color: string }) {
  const width = total > 0 ? Math.max((value / total) * 100, value > 0 ? 5 : 0) : 0;
  return (
    <div className="space-y-1">
      <div className="flex justify-between text-xs text-slate-300">
        <span>{label}</span>
        <span>{value}</span>
      </div>
      <div className="h-3 overflow-hidden rounded bg-slate-800">
        <div className={`h-full rounded ${color}`} style={{ width: `${width}%` }} />
      </div>
    </div>
  );
}

function MiniMetric({ label, value }: { label: string; value: string | number }) {
  return (
    <div className="min-w-0 rounded-md border border-slate-800 bg-slate-950/50 px-3 py-2">
      <div className="truncate text-[11px] uppercase text-slate-500">{label}</div>
      <div className="mt-1 text-sm font-semibold text-slate-100">{value}</div>
    </div>
  );
}

function ClosureTrend({ title, chart, metrics }: { title: string; chart: JsonMap; metrics: Array<{ key: string; label: string }> }) {
  const series = array(chart.series).map(record);
  if (!series.length) return null;
  return (
    <div className="rounded-lg border border-slate-800 bg-black/30 p-4">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div>
          <div className="text-sm font-semibold text-slate-100">{title}</div>
          <div className="mt-1 text-xs text-slate-500">
            {chart.baseline_only === true ? "Baseline only: no closure iteration artifact yet." : "Baseline and completed closure iterations."}
          </div>
        </div>
        <div className="text-xs text-slate-500">{chart.no_fake_iterations === true ? "real artifacts only" : ""}</div>
      </div>
      <div className="mt-4 overflow-x-auto">
        <div className="min-w-[720px]">
          <div className={`grid border-b border-slate-800 bg-slate-950/70 px-3 py-2 text-xs font-semibold uppercase text-slate-400`} style={{ gridTemplateColumns: `140px repeat(${metrics.length}, minmax(110px, 1fr))` }}>
            <div>Run</div>
            {metrics.map((metric) => <div key={metric.key}>{metric.label}</div>)}
          </div>
          {series.map((point, index) => (
            <div key={`${point.label || "run"}-${index}`} className="grid border-b border-slate-800 px-3 py-3 text-sm last:border-b-0" style={{ gridTemplateColumns: `140px repeat(${metrics.length}, minmax(110px, 1fr))` }}>
              <div className="font-semibold text-slate-100">{firstString(point.label, `iteration ${index}`)}</div>
              {metrics.map((metric) => (
                <div key={metric.key} className="break-words text-slate-300">{metricValue(point[metric.key])}</div>
              ))}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

function TokenHeatmap({
  label = "Agent Token Heatmap",
  usage,
  loading,
  error,
  fallbackAgentNames,
}: {
  label?: string;
  usage: TokenHeatmapResponse | null;
  loading: boolean;
  error: string | null;
  fallbackAgentNames: string[];
}) {
  const [expanded, setExpanded] = useState(false);
  if (loading) {
    return (
      <div className="mt-5 rounded-lg border border-slate-800 bg-black/25 p-3 text-sm text-slate-400">
        Loading agent token heatmap...
      </div>
    );
  }
  if (error) {
    return (
      <div className="mt-5 rounded-lg border border-amber-500/30 bg-amber-950/20 p-4 text-sm text-amber-200">
        Token heatmap unavailable: {error}
      </div>
    );
  }
  const hasUsefulTokenUsage = tokenResponseHasUsefulUsage(usage);
  const shouldShowExecutionFallback = fallbackAgentNames.length > 0 && !hasUsefulTokenUsage;
  const tokenAgentNames = new Set((usage?.agents || []).map((agent) => agent.agent_name.trim().toLowerCase()));
  const executionOnlyAgentNames = fallbackAgentNames.filter((name) => !tokenAgentNames.has(name.trim().toLowerCase()));
  const agentCount = hasUsefulTokenUsage
    ? (usage?.agents.length || 0) + executionOnlyAgentNames.length
    : fallbackAgentNames.length;
  const compactTotalTokens = usage?.summary.total_tokens || 0;
  const compactLabel = hasUsefulTokenUsage
    ? `${formatCompactNumber(compactTotalTokens)} tokens across ${formatCompactNumber(agentCount)} agent${agentCount === 1 ? "" : "s"}`
    : agentCount
      ? `${formatCompactNumber(agentCount)} agent${agentCount === 1 ? "" : "s"} tracked; no model tokens recorded`
      : "Open token and agent accounting";
  if (!expanded) {
    return (
      <button
        type="button"
        onClick={() => setExpanded(true)}
        className="mt-5 flex w-full flex-wrap items-center justify-between gap-3 rounded-lg border border-cyan-400/25 bg-slate-950/55 px-4 py-3 text-left transition hover:border-cyan-300/60 hover:bg-cyan-950/15"
      >
        <span>
          <span className="block text-sm font-bold text-white">{label}</span>
          <span className="mt-1 block text-xs text-slate-400">{compactLabel}</span>
        </span>
        <span className="rounded-full border border-cyan-400/30 px-3 py-1 text-xs font-bold text-cyan-200">
          View summary
        </span>
      </button>
    );
  }
  if (shouldShowExecutionFallback) {
    return (
      <div className="mt-5 rounded-xl border border-cyan-400/25 bg-slate-950/70 p-4">
        <div className="flex flex-wrap items-start justify-between gap-3">
          <div>
            <div className="text-sm font-bold text-white">{label}</div>
            <div className="mt-1 text-xs text-slate-400">
              This workflow has agent execution evidence, but no model-token rows were recorded for this run.
            </div>
          </div>
          <div className="rounded-full border border-cyan-400/30 px-3 py-1 text-xs font-bold text-cyan-200">
            {fallbackAgentNames.length} agents tracked
          </div>
          <button
            type="button"
            onClick={() => setExpanded(false)}
            className="rounded-full border border-slate-700 px-3 py-1 text-xs font-bold text-slate-300 transition hover:border-cyan-400/50 hover:text-cyan-100"
          >
            Hide
          </button>
        </div>

        <div className="mt-4 rounded-lg border border-amber-400/25 bg-amber-950/15 p-3 text-sm leading-6 text-amber-100">
          No token usage events were found for this workflow. The chart below shows the agent execution map; these steps were tool-only, skipped model calls, or did not report usage for this run.
        </div>

        <div className="mt-5 space-y-3">
          {fallbackAgentNames.map((name, index) => (
            <div key={`${name}-${index}`} className="rounded-lg border border-slate-800 bg-black/25 p-3">
              <div className="flex flex-wrap items-center justify-between gap-2">
                <div className="break-words text-sm font-bold text-slate-100">{name}</div>
                <div className="text-xs font-semibold text-slate-500">no model tokens recorded</div>
              </div>
              <div className="mt-3 h-4 overflow-hidden rounded-full bg-slate-900">
                <div className="h-full rounded-full bg-slate-700/80" style={{ width: "100%" }} />
              </div>
              <div className="mt-2 text-xs text-slate-500">Input/output tokens were not attributed to this agent for this workflow.</div>
            </div>
          ))}
        </div>
      </div>
    );
  }

  if (!usage?.available || !usage.agents.length) {
    return (
      <div className="mt-5 rounded-lg border border-slate-800 bg-black/25 p-4 text-sm text-slate-400">
        Agent token heatmap will appear when this workflow records model usage or agent execution logs.
      </div>
    );
  }

  const maxTokens = Math.max(...usage.agents.map((agent) => agent.total_tokens || 0), 1);
  const totalTokens = Math.max(usage.summary.total_tokens || 0, 1);
  const hasTrackedTokens = usage.summary.total_tokens > 0;

  return (
    <div className="mt-5 rounded-xl border border-cyan-400/25 bg-slate-950/70 p-4">
      <div className="flex flex-wrap items-start justify-between gap-3">
        <div>
          <div className="text-sm font-bold text-white">{label}</div>
          <div className="mt-1 text-xs text-slate-400">Input and output tokens grouped by agent for this workflow run.</div>
        </div>
        <div className="rounded-full border border-cyan-400/30 px-3 py-1 text-xs font-bold text-cyan-200">
          {formatCompactNumber(usage.summary.total_tokens)} total tokens
        </div>
        <button
          type="button"
          onClick={() => setExpanded(false)}
          className="rounded-full border border-slate-700 px-3 py-1 text-xs font-bold text-slate-300 transition hover:border-cyan-400/50 hover:text-cyan-100"
        >
          Hide
        </button>
      </div>

      <div className="mt-4 grid gap-3 sm:grid-cols-2 lg:grid-cols-5">
        <MiniMetric label="Agents" value={formatCompactNumber(usage.summary.agent_count)} />
        <MiniMetric label="Input Tokens" value={formatCompactNumber(usage.summary.input_tokens)} />
        <MiniMetric label="Output Tokens" value={formatCompactNumber(usage.summary.output_tokens)} />
        <MiniMetric label="Cost Estimate" value={formatCost(usage.summary.estimated_cost_usd)} />
        <MiniMetric label="Prev Run Delta" value={formatDelta(usage.summary.token_delta_percent)} />
      </div>

      <div className="mt-3 rounded-lg border border-slate-800 bg-black/20 p-3">
        <div className="text-xs font-semibold uppercase text-slate-500">Optimization Signals</div>
        <div className="mt-2 space-y-1 text-sm leading-6 text-slate-300">
          {(usage.summary.optimization_suggestions || []).map((suggestion) => (
            <div key={suggestion}>- {suggestion}</div>
          ))}
          {!(usage.summary.optimization_suggestions || []).length ? <div>- No token optimization signal yet.</div> : null}
        </div>
      </div>

      <div className="mt-5 space-y-3">
        {usage.agents.map((agent) => {
          const totalWidth = Math.max((agent.total_tokens / maxTokens) * 100, agent.total_tokens > 0 ? 4 : 0);
          const inputWidth = agent.total_tokens > 0 ? (agent.input_tokens / agent.total_tokens) * 100 : 0;
          const outputWidth = agent.total_tokens > 0 ? (agent.output_tokens / agent.total_tokens) * 100 : 0;
          const share = (agent.total_tokens / totalTokens) * 100;
          const statusText = agent.failed_event_count ? `${agent.failed_event_count} failed call(s)` : `${agent.event_count || 0} call(s)`;
          return (
            <div key={agent.agent_name} className="rounded-lg border border-slate-800 bg-black/25 p-3">
              <div className="flex flex-wrap items-start justify-between gap-2">
                <div className="min-w-0">
                  <div className="break-words text-sm font-bold text-slate-100">{agent.agent_name}</div>
                  <div className="mt-1 text-xs text-slate-500">
                    {[agent.model, agent.provider, agent.context_mode || "workflow", statusText].filter(Boolean).join(" | ")}
                  </div>
                </div>
                <div className="text-right text-xs text-slate-400">
                  <div className="font-bold text-cyan-200">{formatCompactNumber(agent.total_tokens)} tokens</div>
                  <div>{share.toFixed(1)}% of run</div>
                </div>
              </div>
              <div className="mt-3 h-4 rounded-full bg-slate-900">
                {hasTrackedTokens || agent.total_tokens > 0 ? (
                  <div className="flex h-full overflow-hidden rounded-full" style={{ width: `${totalWidth}%` }}>
                    <div className="bg-cyan-400" style={{ width: `${inputWidth}%` }} title={`Input: ${agent.input_tokens.toLocaleString()} tokens`} />
                    <div className="bg-amber-300" style={{ width: `${outputWidth}%` }} title={`Output: ${agent.output_tokens.toLocaleString()} tokens`} />
                  </div>
                ) : (
                  <div className="h-full rounded-full bg-slate-700/80" style={{ width: "100%" }} title="Agent executed; no model tokens attributed." />
                )}
              </div>
              <div className="mt-2 flex flex-wrap gap-x-4 gap-y-1 text-xs text-slate-400">
                <span>Input: <span className="text-cyan-200">{agent.input_tokens.toLocaleString()}</span></span>
                <span>Output: <span className="text-amber-200">{agent.output_tokens.toLocaleString()}</span></span>
                <span>Cost: <span className="text-slate-200">{formatCost(agent.estimated_cost_usd)}</span></span>
                {agent.estimated_credits ? <span>Credits: <span className="text-slate-200">{agent.estimated_credits.toLocaleString()}</span></span> : null}
                {agent.full_context_estimate_tokens ? <span>Full est: <span className="text-slate-200">{agent.full_context_estimate_tokens.toLocaleString()}</span></span> : null}
                {agent.smart_context_tokens ? <span>Smart: <span className="text-cyan-200">{agent.smart_context_tokens.toLocaleString()}</span></span> : null}
                {typeof agent.smart_context_reduction_percent === "number" ? <span>Saved: <span className="text-emerald-300">{agent.smart_context_reduction_percent}%</span></span> : null}
              </div>
            </div>
          );
        })}
        {executionOnlyAgentNames.map((name) => (
          <div key={`execution-${name}`} className="rounded-lg border border-slate-800 bg-black/25 p-3">
            <div className="flex flex-wrap items-center justify-between gap-2">
              <div className="break-words text-sm font-bold text-slate-100">{name}</div>
              <div className="text-xs font-semibold text-slate-500">executed · no model call</div>
            </div>
            <div className="mt-3 h-4 overflow-hidden rounded-full bg-slate-900">
              <div className="h-full w-full rounded-full bg-slate-700/80" />
            </div>
            <div className="mt-2 text-xs text-slate-500">Agent execution was recorded in the workflow log; no input or output tokens were attributed to this agent.</div>
          </div>
        ))}
      </div>

      <div className="mt-4 flex flex-wrap gap-4 text-xs text-slate-400">
        <span className="inline-flex items-center gap-2"><span className="h-2.5 w-2.5 rounded-full bg-cyan-400" />Input tokens</span>
        <span className="inline-flex items-center gap-2"><span className="h-2.5 w-2.5 rounded-full bg-amber-300" />Output tokens</span>
      </div>
    </div>
  );
}

function tokenResponseHasUsefulUsage(usage: TokenHeatmapResponse | null): boolean {
  return Boolean(
    usage?.available &&
    usage.agents.length &&
    (usage.summary.total_tokens > 0 || usage.agents.some((agent) => (agent.total_tokens || 0) > 0)),
  );
}

function TokenHeatmapLoader({
  label,
  workflowId,
  status,
  logs,
}: {
  label: string;
  workflowId: string | null;
  status?: string | null;
  logs?: string | null;
}) {
  const [usage, setUsage] = useState<TokenHeatmapResponse | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [fetchedLogs, setFetchedLogs] = useState<string | null>(null);
  const effectiveLogs = logs ?? fetchedLogs;
  const fallbackAgentNames = useMemo(() => extractParticipatingAgentNames(effectiveLogs), [effectiveLogs]);

  useEffect(() => {
    setFetchedLogs(null);
    if (!workflowId || logs !== undefined) return;
    let active = true;
    const supabase = createClientComponentClient();
    supabase
      .from("workflows")
      .select("logs")
      .eq("id", workflowId)
      .single()
      .then(({ data, error }) => {
        if (!active || error) return;
        setFetchedLogs((data as WorkflowLogRow | null)?.logs || null);
      });
    return () => {
      active = false;
    };
  }, [workflowId, logs]);

  useEffect(() => {
    setUsage(null);
    setError(null);
    setLoading(false);
    if (!workflowId) return;
    let active = true;
    let timer: ReturnType<typeof setTimeout> | null = null;
    const terminal = ["completed", "failed", "cancelled", "stopped", "error"].includes(
      String(status || "").trim().toLowerCase(),
    );
    const loadTokenUsage = (attempt = 0) => {
      setLoading(true);
      apiGet<TokenHeatmapResponse>(`/apps/dashboard/token_heatmap/${encodeURIComponent(workflowId)}`)
        .then((data) => {
          if (!active) return;
          setUsage(data);
          setError(null);
          if (!terminal) {
            timer = setTimeout(() => loadTokenUsage(attempt + 1), 3000);
          } else if (!tokenResponseHasUsefulUsage(data) && attempt < 2) {
            timer = setTimeout(() => loadTokenUsage(attempt + 1), 2500);
          }
        })
        .catch((reason: unknown) => {
          if (!active) return;
          setError(reason instanceof Error ? reason.message : String(reason));
          if ((!terminal && attempt < 120) || (terminal && attempt < 2)) {
            timer = setTimeout(() => loadTokenUsage(attempt + 1), 2500);
          }
        })
        .finally(() => {
          if (active) setLoading(false);
        });
    };
    loadTokenUsage(0);
    return () => {
      active = false;
      if (timer) clearTimeout(timer);
    };
  }, [workflowId, status]);

  if (!workflowId) return null;
  return <TokenHeatmap label={label} usage={usage} loading={loading} error={error} fallbackAgentNames={fallbackAgentNames} />;
}

