              <Bar label="Analog RTL files" value={number(analogScope.rtl_file_count)} total={rtlFileTotal} color="bg-rose-500" />
              <Bar label="SoC RTL files" value={number(socScope.rtl_file_count)} total={rtlFileTotal} color="bg-fuchsia-500" />
              {agentCount !== null ? <Bar label="Agents participated" value={agentCount} total={participatedTotal} color="bg-slate-400" /> : null}
            </div>
            <div className="grid min-w-0 grid-cols-1 gap-3 sm:grid-cols-2 2xl:grid-cols-3">
              <CheckCard title="Digital Lint" status={firstString(lintSummary.digital, record(digitalScope.lint).status, "not run")} tool="verilator" />
              <CheckCard title="Analog Lint" status={firstString(lintSummary.analog, record(analogScope.lint).status, "not run")} tool="verilator" detail="behavioral model lint" />
              <CheckCard title="SoC Lint" status={firstString(lintSummary.soc, compile.sim, "not produced")} tool={`${compileTool} / ${lintTool}`} detail={toolDetail} />
              <CheckCard title="System Lint" status={firstString(lintSummary.system, record(systemScope.lint).status, "not run")} tool={`${compileTool} / ${lintTool}`} detail="Digital + analog + SoC roll-up" />
              <Stat title="Full-cycle Paths" value={number(timing.full_cycle_path_count)} />
              <Stat title="Half-cycle Paths" value={number(timing.half_cycle_path_count)} />
              <Stat title="Clock" value={firstString(clockReset.primary_clock, "not inferred")} />
              <Stat title="Reset" value={firstString(clockReset.primary_reset, "not inferred")} />
              <Stat title="Modules" value={number(systemScope.module_count)} />
              {physCompile && physCompile !== "skipped" ? <Stat title="Physical RTL Compile" value={physCompile} /> : null}
              {hasSpec2Rtl ? <Stat title="Spec2RTL" value={statusLabel(spec2rtl.status)} /> : null}
              {hasSpec2Rtl ? <Stat title="Spec2RTL Checked" value={metricValue(spec2rtlSummary.checked)} /> : null}
              {hasSpec2Rtl ? <Stat title="Spec2RTL Matched" value={metricValue(spec2rtlSummary.matched)} /> : null}
              {hasSpec2Rtl ? <Stat title="Spec2RTL Partial" value={metricValue(spec2rtlSummary.partial)} /> : null}
              {hasSpec2Rtl ? <Stat title="Spec2RTL Missing" value={metricValue(spec2rtlSummary.missing)} /> : null}
              {hasSpec2Rtl ? <Stat title="Spec2RTL Inconclusive" value={metricValue(spec2rtlSummary.inconclusive)} /> : null}
            </div>
          </div>
        );
      }
      const systemPkg = record(evidence["system_rtl_package.json"]);
      const systemDebug = record(evidence["system_rtl_package_debug.json"]);
      const compile = record(evidence["system_full_compile_summary.json"]);
      const intent = record(evidence["system_integration_intent.json"]);
      if (Object.keys(systemPkg).length || Object.keys(systemDebug).length || Object.keys(intent).length) {
        const filelists = record(systemPkg.filelists);
        const compileInfo = record(systemPkg.compile);
        const top = record(systemPkg.top);
        const simFiles = array(filelists.sim);
        const physFiles = array(filelists.phys);
        const instances = array(intent.instances);
        const connections = array(intent.connections);
        const artifacts = record(systemPkg.artifacts);
        return (
          <div className="mt-5 space-y-5">
            <div className="grid gap-3 sm:grid-cols-2">
              <Bar label="RTL files imported" value={simFiles.length || physFiles.length} total={Math.max(simFiles.length || physFiles.length, 1)} color="bg-cyan-500" />
              <Bar label="Integration instances" value={instances.length} total={Math.max(instances.length, 1)} color="bg-violet-500" />
            </div>
            <div className="grid min-w-0 grid-cols-1 gap-3 sm:grid-cols-2 xl:grid-cols-4">
              <Stat title="Top Module" value={firstString(top.sim, top.phys, "soc_top_sim")} />
              <Stat title="RTL Files" value={simFiles.length || physFiles.length} />
              <Stat title="Input Bits" value="not produced pre-synthesis" />
              <Stat title="Output Bits" value="not produced pre-synthesis" />
              <Stat title="Flip-flops" value="not produced pre-synthesis" />
              <Stat title="Latches" value="not produced pre-synthesis" />
              <Stat title="Full-cycle Paths" value="not produced pre-synthesis" />
              <Stat title="Half-cycle Paths" value="not produced pre-synthesis" />
              <Stat title="SoC Lint" value={firstString(compileInfo.sim, record(compile.sim).status, "not produced")} />
              <Stat title="Physical Lint" value={firstString(compileInfo.phys, record(compile.phys).status, "not produced")} />
              <Stat title="Instances" value={instances.length} />
              <Stat title="Connections" value={connections.length} />
              <Stat title="Analog Macro" value={artifacts.integration_intent ? "integrated by intent" : "not reported"} />
              <Stat title="Ready for Cosim" value={systemPkg.ready_for_cosim === true ? "yes" : "no"} />
              {agentCount !== null ? <Stat title="Agents Participated" value={agentCount} /> : null}
            </div>
          </div>
        );
      }
      return registers.length ? (
        <div className="mt-5">
          <div className="text-sm font-semibold text-slate-100">Generated Firmware Register Interface</div>
          <div className="mt-3 grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
            {registers.slice(0, 8).map((item, index) => {
              const register = record(item);
              return (
                <div key={`${String(register.name || "register")}-${index}`} className="min-w-0 rounded-lg border border-cyan-900/60 bg-cyan-950/15 p-3">
                  <div className="break-all text-xs text-cyan-300">{String(register.offset || "-")}</div>
                  <div className="mt-1 break-words font-semibold text-slate-100">{String(register.name || "REGISTER")}</div>
                  <div className="mt-1 break-words text-xs text-slate-400">{String(register.access || "")}</div>
                </div>
              );
            })}
          </div>
        </div>
      ) : <div className="mt-5 text-sm text-amber-300">Register-map artifact is not available for this completed run.</div>;
    }

    if (stage === "rtl_review") {
      const review = record(evidence["rtl_review.json"]);
      const summary = record(review.summary);
      const files = array(review.files).map(record);
      const fileRows = files.slice(0, 10).map((file) => ({
        check: firstString(file.path, "rtl file"),
        status: `${metricValue(file.module_count)} modules`,
        detail: `${metricValue(file.always_block_count)} always blocks, ${metricValue(file.continuous_assign_count)} assigns`,
        tool: "RTL review",
      }));
      return (
        <div className="mt-5 space-y-5">
          <div className="grid min-w-0 grid-cols-1 gap-3 sm:grid-cols-2 xl:grid-cols-4">
            <Stat title="Status" value={statusLabel(summary.status)} />
            <Stat title="RTL Files" value={metricValue(summary.rtl_file_count)} />
            <Stat title="Modules" value={metricValue(summary.module_count)} />
            <Stat title="Issues" value={metricValue(summary.issue_count)} />
            <Stat title="High Issues" value={metricValue(summary.high_issue_count)} />
            <Stat title="Medium Issues" value={metricValue(summary.medium_issue_count)} />
            <Stat title="Review Depth" value={metricValue(summary.review_depth)} />
            <Stat title="Tool Pass" value={metricValue(summary.tool_pass_count)} />
            <Stat title="Tool Fail" value={metricValue(summary.tool_fail_count)} />
            <Stat title="Tool Missing" value={metricValue(summary.tool_unavailable_count)} />
            {agentCount !== null ? <Stat title="Agents Participated" value={agentCount} /> : null}
          </div>
          {fileRows.length ? <CheckTable rows={fileRows} /> : null}
        </div>
      );
    }

    if (stage === "constraint_review") {
      const review = record(evidence["constraint_review.json"]);
      const summary = record(review.summary);
      const findingRows = array(review.findings).map(record).slice(0, 10).map((finding) => ({
        check: firstString(finding.category, "constraint finding"),
        status: firstString(finding.severity, "info"),
        detail: firstString(finding.message, finding.recommendation, "review generated"),
        tool: "SDC review",
      }));
      return (
        <div className="mt-5 space-y-5">
          <div className="grid min-w-0 grid-cols-1 gap-3 sm:grid-cols-2 xl:grid-cols-4">
            <Stat title="Status" value={statusLabel(summary.status)} />
            <Stat title="RTL Clocks" value={metricValue(summary.rtl_clock_count)} />
            <Stat title="Create Clocks" value={metricValue(summary.create_clock_count)} />
            <Stat title="Generated Clocks" value={metricValue(summary.generated_clock_count)} />
            <Stat title="Input Delays" value={metricValue(summary.input_delay_count)} />
            <Stat title="Output Delays" value={metricValue(summary.output_delay_count)} />
            <Stat title="False Paths" value={metricValue(summary.false_path_count)} />
            <Stat title="Findings" value={metricValue(summary.finding_count)} />
            <Stat title="Tool Pass" value={metricValue(summary.tool_pass_count)} />
            <Stat title="Tool Fail" value={metricValue(summary.tool_fail_count)} />
            <Stat title="Tool Missing" value={metricValue(summary.tool_unavailable_count)} />
            {agentCount !== null ? <Stat title="Agents Participated" value={agentCount} /> : null}
          </div>
          {findingRows.length ? <CheckTable rows={findingRows} /> : null}
        </div>
      );
    }

    if (stage === "timing_debug") {
      const debug = record(evidence["timing_debug.json"]);
      const summary = record(debug.summary);
      const reportRows = array(debug.reports).map(record).slice(0, 10).map((report) => {
        const metrics = record(report.metrics);
        return {
          check: firstString(report.path, "timing report"),
          status: `${metricValue(metrics.wns)} WNS`,
          detail: `setup ${metricValue(metrics.setup_wns)}, hold ${metricValue(metrics.hold_wns)}`,
          tool: "STA report parser",
        };
      });
      return (
        <div className="mt-5 space-y-5">
          <div className="grid min-w-0 grid-cols-1 gap-3 sm:grid-cols-2 xl:grid-cols-4">
            <Stat title="Status" value={statusLabel(summary.status)} />
            <Stat title="Reports" value={metricValue(summary.timing_report_count)} />
            <Stat title="Worst Slack" value={metricValue(summary.worst_slack_observed)} />
            <Stat title="Findings" value={metricValue(summary.finding_count)} />
            <Stat title="Stage" value={metricValue(summary.stage)} />
            <Stat title="OpenSTA" value={summary.opensta_available === true ? "available" : "not found"} />
            <Stat title="OpenROAD" value={summary.openroad_available === true ? "available" : "not found"} />
            {agentCount !== null ? <Stat title="Agents Participated" value={agentCount} /> : null}
          </div>
          {reportRows.length ? <CheckTable rows={reportRows} /> : null}
        </div>
      );
    }

    if (stage === "dqa") {
      const handoff = record(evidence["rtl_handoff_ingest_manifest.json"]);
      const lint = record(evidence["rtl_lint_report.json"]);
      const cdc = record(evidence["cdc_findings.json"]);
      const reset = record(evidence["reset_integrity_findings.json"]);
      const readiness = record(evidence["synthesis_readiness_findings.json"]);
      const summary = record(evidence["dqa_summary.json"] || evidence["executive_summary.json"]);
      const toolSummary = dqaToolSummary(
        lint,
        readiness,
        record(evidence["tool_execution_summary.json"]),
        record(evidence["tool_profile_used.json"])
      );
      const lintExecution = record(array(record(lint.tooling).executions)[0]);
      const lintTool = firstString(lintExecution.tool, "verilator");
      const synthTool = record(readiness.yosys).available === true ? "yosys" : "not available";
      const readinessScore = firstPresent(readiness.score);
      const yosysErrors = array(record(readiness.yosys).errors).length;
      const checkRows = [
        { check: "RTL Lint", status: lintVerdict(lint), detail: `${findingCount(lint)} findings`, tool: lintTool },
        { check: "CDC", status: findingsVerdict(cdc), detail: `${findingCount(cdc)} findings`, tool: "heuristic scan" },
        { check: "Reset", status: findingsVerdict(reset), detail: `${findingCount(reset)} findings`, tool: "heuristic scan" },
        {
          check: "Synth Ready",
          status: synthesisReadinessVerdict(readiness),
          detail: readinessScore !== undefined ? `score ${String(readinessScore)}${yosysErrors ? `, ${yosysErrors} yosys error(s)` : ""}` : "not produced",
          tool: synthTool,
        },
      ];
      const rtlFiles = firstNumber(
        summary.rtl_file_count,
        handoff.rtl_file_count,
        array(handoff.rtl_files).length
      );
      return (
        <div className="mt-5 space-y-5">
          <ToolStrip used={toolSummary.used} defaultTool={toolSummary.defaultTool} label="Toolchain (planned and detected)" />
          <div className="grid gap-3 sm:grid-cols-1">
            <Bar label="RTL files imported" value={rtlFiles} total={Math.max(rtlFiles, 1)} color="bg-cyan-500" />
          </div>
          <div className="grid min-w-0 grid-cols-1 gap-3 sm:grid-cols-2 xl:grid-cols-4">
            {checkRows.map((row) => (
              <CheckCard key={row.check} title={row.check} status={row.status} detail={row.detail} />
            ))}
          </div>
          <CheckTable rows={checkRows} />
          <div className="grid min-w-0 grid-cols-1 gap-3 sm:grid-cols-2 xl:grid-cols-4">
            <Stat title="Source" value={firstString(handoff.source_mode, "imported").replaceAll("_", " ")} />
            <Stat title="RTL Files" value={rtlFiles} />
            <Stat title="Top Module" value={firstString(handoff.top_module, "not inferred")} />
            <Stat title="Findings" value={findingCount(lint) + findingCount(cdc) + findingCount(reset) + findingCount(readiness)} />
            {agentCount !== null ? <Stat title="Agents Participated" value={agentCount} /> : null}
            <Stat title="Summary" value={firstString(summary.status, summary.verdict, status || "running")} />
          </div>
        </div>
      );
    }

    if (stage === "smoke") {
      const handoff = record(evidence["rtl_handoff_ingest_manifest.json"]);
      const sim = record(record(evidence["simulation_summary_coverage.json"]).simulation);
      const summary = record(evidence["executive_summary.json"]);
      const rtlFiles = firstNumber(handoff.rtl_file_count, array(handoff.rtl_files).length);
      const passed = firstNumber(sim.pass, sim.passed);
      const failed = firstNumber(sim.fail, sim.failed);
      return (
        <div className="mt-5 space-y-5">
          <div className="grid gap-3 sm:grid-cols-3">
            <Bar label="RTL files imported" value={rtlFiles} total={Math.max(rtlFiles, 1)} color="bg-cyan-500" />
            <Bar label="Simulation passed" value={passed} total={Math.max(passed + failed, 1)} color="bg-emerald-500" />
            <Bar label="Simulation failed" value={failed} total={Math.max(passed + failed, 1)} color="bg-rose-500" />
          </div>
          <div className="grid min-w-0 grid-cols-1 gap-3 sm:grid-cols-2 xl:grid-cols-4">
            <Stat title="Source" value={firstString(handoff.source_mode, "imported").replaceAll("_", " ")} />
            <Stat title="RTL Files" value={rtlFiles} />
            <Stat title="Top Module" value={firstString(handoff.top_module, "not inferred")} />
            <Stat title="Runs" value={firstNumber(sim.total, passed + failed)} />
            <Stat title="Simulation" value={failed > 0 ? "fail" : passed > 0 ? "pass" : "not run"} />
            {agentCount !== null ? <Stat title="Agents Participated" value={agentCount} /> : null}
            <Stat title="Summary" value={firstString(summary.status, summary.verdict, status || "running")} />
          </div>
        </div>
      );
    }

    if (stage === "fpga_target_explorer") {
      const ev = (...keys: string[]) => firstPresent(...keys.map((key) => evidence[key]));
      const explorer = record(ev("fpga_target_explorer.json", "fpga/target_explorer/fpga_target_explorer.json"));
      const results = array(explorer.results).map(record);
      const storedRecommendations = record(explorer.recommendations);
      const recommendationDetails = record(explorer.recommendation_details);
      const continuation = record(explorer.continuation);
      const ioMapping = record(ev("fpga_explorer_io_mapping.json", "fpga/target_explorer/fpga_explorer_io_mapping.json"));
      const serialTransport = record(ev("fpga_serial_transport.json", "fpga/target_explorer/fpga_serial_transport.json"));
      const transportContract = record(ev("fpga_spi_transport_contract.json", "fpga/target_explorer/interface_adapter/fpga_spi_transport_contract.json"));
      const ioMappings = array(ioMapping.mappings).map(record);
      const targetMhz = firstNumber(explorer.target_frequency_mhz);
      const maxFmax = Math.max(...results.map((item) => firstNumber(item.best_frequency_mhz) || 0), targetMhz || 1);
      // Older Explorer artifacts filtered out timing-valid boards when their
      // physical pin map was incomplete, leaving every recommendation card as
      // "Unavailable". Derive a read-only dashboard fallback from measured
      // implementation results; pin readiness remains a separate gate.
      const routedResults = results.filter((item) => (firstNumber(item.best_frequency_mhz) || 0) > 0);
      const targetMetResults = routedResults.filter((item) => item.target_met === true);
      const recommendationPool = targetMetResults.length ? targetMetResults : routedResults;
      const byPerformance = [...recommendationPool].sort((a, b) => (firstNumber(b.median_frequency_mhz, b.best_frequency_mhz) || 0) - (firstNumber(a.median_frequency_mhz, a.best_frequency_mhz) || 0))[0];
      const byGrowth = [...recommendationPool].sort((a, b) => (firstNumber(b.resource_headroom_percent) || 0) - (firstNumber(a.resource_headroom_percent) || 0))[0];
      const byLowCost = [...recommendationPool].sort((a, b) => (firstNumber(a.logic_cells_available) || Number.MAX_SAFE_INTEGER) - (firstNumber(b.logic_cells_available) || Number.MAX_SAFE_INTEGER))[0];
      const byOverall = [...recommendationPool].sort((a, b) => {
        const readiness = Number(b.programming_ready === true) - Number(a.programming_ready === true);
        if (readiness) return readiness;
        const passRate = (firstNumber(b.timing_pass_rate) || 0) - (firstNumber(a.timing_pass_rate) || 0);
        if (passRate) return passRate;
        return (firstNumber(b.resource_headroom_percent) || 0) - (firstNumber(a.resource_headroom_percent) || 0);
      })[0];
      const recommendations = {
        ...storedRecommendations,
        best_overall: firstString(storedRecommendations.best_overall, byOverall?.board),
        best_performance: firstString(storedRecommendations.best_performance, byPerformance?.board),
        best_low_cost: firstString(storedRecommendations.best_low_cost, byLowCost?.board),
        best_for_growth: firstString(storedRecommendations.best_for_growth, byGrowth?.board),
      };
      const recommendationItems = [
        ["Best Overall", recommendations.best_overall, "Balanced timing reliability, headroom, performance, and target size."],
        ["Best Performance", recommendations.best_performance, "Highest robust median implementation frequency."],
        ["Best Low-Cost Variant", recommendations.best_low_cost, "Smallest viable FPGA capacity proxy; live pricing is not assumed."],
        ["Best for Growth", recommendations.best_for_growth, "Largest remaining logic capacity after implementation."],
      ];
      const resultFor = (board: unknown) => results.find((item) => firstString(item.board) === firstString(board));
      const continueToPrototype = (board: string, result: JsonMap) => {
        if (typeof window === "undefined") return;
        const winningRun = record(result.winning_run);
        const synthesisRuns = array(result.synthesis_runs).map(record);
        const winningSynthesis = synthesisRuns.find((run) => firstString(run.netlist) === firstString(winningRun.netlist));
        const winningConfiguration = {
          seed: firstPresent(winningRun.seed, result.winning_seed),
          synthesisStrategy: firstString(winningRun.synthesis_strategy, winningSynthesis?.strategy, "baseline"),
          toolEffort: firstString(winningRun.effort, "balanced"),
          achievedFrequencyMhz: firstNumber(result.best_frequency_mhz),
          timingMarginPercent: firstNumber(result.timing_margin_percent),
        };
        window.localStorage.setItem("chiploop_fpga_bitstream_prefill", JSON.stringify({
          rtlSourceMode: "from_arch2rtl",
          sourceWorkflowId: workflowId,
          explorerSourceWorkflowId: workflowId,
          explorerWinningConfiguration: winningConfiguration,
          fpgaClosureMode: winningConfiguration.toolEffort === "advanced" ? "advanced" : "balanced",
          board,
          topModule: firstString(continuation.top_module, explorer.top_module),
          targetFrequency: String(targetMhz || 75),
          notes: `Started from FPGA Target Explorer workflow ${workflowId}. Winning seed ${String(winningConfiguration.seed ?? "not required")}; Explorer Fmax ${formatNumber(winningConfiguration.achievedFrequencyMhz)} MHz. FPGA Prototyping will rerun verification and implementation.`,
        }));
        window.location.href = "/apps/fpga-bitstream";
      };
      return (
        <div className="mt-5 space-y-4">
          <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
            <Stat title="Target Frequency" value={targetMhz ? `${formatNumber(targetMhz)} MHz` : "not specified"} />
            <Stat title="Candidates" value={firstNumber(explorer.candidate_count)} />
            <Stat title="Unique Implementations" value={firstNumber(explorer.unique_implementation_count)} />
            <Stat title="Primary Recommendation" value={firstString(explorer.selected_recommendation, "not available")} />
            <Stat title="Host Transport" value={firstString(continuation.host_transport, serialTransport.transport, "not selected").replaceAll("_", " ")} />
            <Stat title="Protocol Contract" value={Boolean(continuation.transport_contract_ready || transportContract.schema) ? "ready" : "not generated"} />
            <Stat title="Host Driver" value={continuation.host_driver_ready === true ? "ready" : "not generated"} />
          </div>

          <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-4">
            {recommendationItems.map(([label, board, description]) => {
              const result = resultFor(board);
              const boardKey = firstString(board);
              const detailKey = firstString(label).toLowerCase().replaceAll(" ", "_").replace("low-cost_variant", "low_cost");
              const detail = record(recommendationDetails[detailKey]);
              return (
                <div key={String(label)} className="rounded-2xl border border-cyan-500/25 bg-slate-950/45 p-4">
                  <div className="text-xs font-semibold uppercase tracking-wide text-cyan-300">{String(label)}</div>
                  <div className="mt-2 text-lg font-bold text-white">{firstString(result?.label, boardKey, "Unavailable")}</div>
                  <div className="mt-1 text-sm text-slate-300">{result ? `${formatNumber(firstNumber(result.best_frequency_mhz))} MHz | ${firstNumber(result.timing_margin_percent) >= 0 ? "+" : ""}${formatNumber(firstNumber(result.timing_margin_percent))}% timing margin | ${formatNumber(firstNumber(result.resource_headroom_percent))}% headroom` : "No viable target"}</div>
                  <div className="mt-2 text-xs leading-5 text-slate-400">{firstString(detail.why, description)}</div>
                  {result ? <div className="mt-2 text-[11px] text-slate-500">Toolchain {firstString(result.toolchain_confidence, "qualified")} · {result.programming_ready === true ? "physical pin map is programming-ready" : `${array(result.unmapped_ports).length} physical pin mapping(s) must be verified during FPGA Prototyping`}</div> : null}
                  {boardKey ? <button type="button" onClick={() => continueToPrototype(boardKey, result || {})} className="mt-3 w-full rounded-lg border border-cyan-500/40 bg-cyan-500/10 px-3 py-2 text-sm font-semibold text-cyan-100 hover:border-cyan-300">Continue with this board</button> : null}
                </div>
              );
            })}
          </div>

          <section className="rounded-2xl border border-slate-800 bg-slate-950/35 p-4">
            <div className="text-sm font-semibold text-slate-200">Achieved frequency by target</div>
            <div className="mt-4 space-y-3">
              {results.map((item) => {
                const fmax = firstNumber(item.best_frequency_mhz) || 0;
                const failureKind = firstString(item.failure_kind);
                const failureReason = firstString(item.failure_reason).toLowerCase();
                const capacityExceeded = failureKind === "capacity_exceeded" || firstNumber(item.logic_utilization_percent) > 100 || /no bels remaining|check constraints and utilisation/.test(failureReason);
                const outcome = capacityExceeded ? "does not fit" : failureKind === "io_packing" ? "tool I/O packing failed" : firstString(item.status) === "implementation_failed" ? "implementation failed" : item.target_met === true ? "target met" : "target missed";
                return <Bar key={firstString(item.board)} label={`${firstString(item.label, item.board)} - ${outcome}`} value={fmax} total={maxFmax} color={item.target_met === true ? "bg-emerald-500" : firstString(item.status) === "implementation_failed" ? "bg-rose-500" : "bg-amber-500"} />;
              })}
            </div>
          </section>

          <section className="space-y-2">
            {results.map((item) => {
              const runs = array(item.pnr_runs).map(record);
              const relaxation = record(item.frequency_relaxation);
              const boardIo = ioMappings.find((mapping) => firstString(mapping.board) === firstString(item.board));
              const implementationFailed = firstString(item.status) === "implementation_failed";
              const failureKind = firstString(item.failure_kind);
              const failureReason = firstString(item.failure_reason).toLowerCase();
              const capacityExceeded = failureKind === "capacity_exceeded" || firstNumber(item.logic_utilization_percent) > 100 || /no bels remaining|check constraints and utilisation/.test(failureReason);
              const failureLabel = capacityExceeded ? "Does not fit" : failureKind === "io_packing" ? "Tool I/O packing failed" : "Implementation failed";
